/* DAWAH X — ahmad, অধ্যায় 56 · খণ্ড 56 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][56]=[[11001,11001,"","ঈশ্বর তাকে আমার সম্বন্ধে বলা ও আমার প্রতি মিথ্যা বলা নয় বলে এবং আমাকে নির্যাতন করা হয়েছে বলে বলার জন্য অনুরোধ করেছেন । তারা আমার ছেলের কথা বলেছে, আমার গোপনীয়তা লজ্জা পাচ্ছে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَدِّثُوا عَنِّي وَلَا تَكْذِبُوا عَلَيَّ وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ وَحَدِّثُوا عَنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَلَا حَرَجَ ‏","","",""],[11002,11002,"","আমার বাবার সাথে কথা বলেছি আমার ভাইকে মারার চেষ্টা করার ব্যাপারে। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আমার দুই কারাবন্দীর কাছে ক্ষমা প্রার্থনা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَلَّ ‏ ‏سِبْطَانِ ‏ ‏مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَأَرْهَبُ ‏ ‏أَنْ تَكُونَ الضِّبَابَ ‏","","",""],[11003,11003,"","আমরা সেই বধিরদের কথা বলেছিলাম যখন আমরা কঠিন সময় খেলা শুরু করলাম। আমি ঈশ্বরের কাছে প্রার্থনা করব, তিনি মোটা আর মোটা চিন্তা দিয়ে দেবেন। অল্প কয়েক বছর আমার জানাশোনা কোন কল্পনা নয় । মৃত, গোপন রহস্যের মাধ্যমে... ...আমি ডান নামে... ...তিনটা কাজ করবো... ...তিন মেয়েকে চুমু দেবো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُسْتَمِرُّ بْنُ الرَّيَّانِ الْإِيَادِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ الْعَبْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ الدُّنْيَا فَقَالَ ‏ ‏إِنَّ الدُّنْيَا خَضِرَةٌ حُلْوَةٌ فَاتَّقُوهَا وَاتَّقُوا النِّسَاءَ ثُمَّ ذَكَرَ نِسْوَةً ثَلَاثًا مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏امْرَأَتَيْنِ طَوِيلَتَيْنِ تُعْرَفَانِ وَامْرَأَةً قَصِيرَةً لَا تُعْرَفُ فَاتَّخَذَتْ رِجْلَيْنِ مِنْ خَشَبٍ وَصَاغَتْ خَاتَمًا فَحَشَتْهُ مِنْ أَطْيَبِ الطِّيبِ الْمِسْكِ وَجَعَلَتْ لَهُ غَلَقًا فَإِذَا مَرَّتْ بِالْمَلَإِ ‏ ‏أَوْ بِالْمَجْلِسِ ‏ ‏قَالَتْ بِهِ فَفَتَحَتْهُ فَفَاحَ رِيحُهُ ‏ ‏قَالَ ‏ ‏الْمُسْتَمِرُّ ‏ ‏بِخِنْصَرِهِ الْيُسْرَى فَأَشْخَصَهَا دُونَ أَصَابِعِهِ الثَّلَاثِ شَيْئًا وَقَبَضَ الثَّلَاثَةَ ‏","","",""],[11004,11004,"","আমরা যে বধিরদের কথা বলেছিলাম, তাদের কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُسْتَمِرُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ يُرْفَعُ لَهُ بِقَدْرِ ‏ ‏غَدْرَتِهِ ‏ ‏أَلَا وَلَا ‏ ‏غَادِرَ ‏ ‏أَعْظَمُ مِنْ ‏ ‏غَدْرَةِ ‏ ‏أَمِيرِ عَامَّةٍ ‏","","",""],[11005,11005,"","ঈশ্বর তা করতে পারেন আর তিনি আপনাকে বা কাউকে ভয় বা মন্দতা থেকে রক্ষা করতে পারবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُسْتَمِرُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمْنَعَنَّ أَحَدًا مِنْكُمْ مَخَافَةُ النَّاسِ ‏ ‏أَوْ بَشَرٍ ‏ ‏أَنْ يَتَكَلَّمَ بِالْحَقِّ إِذَا رَآهُ أَوْ عَلِمَهُ ‏ ‏أَوْ رَآهُ أَوْ سَمِعَهُ ‏","","",""],[11006,11006,"","ঈশ্বরের কাছে প্রার্থনা করা উত্তম । দুর্দশার বেদনাদায়কতার নিপীড়নকে পরিত্যাগ করুন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْفِضَّةُ بِالْفِضَّةِ وَالذَّهَبُ بِالذَّهَبِ مِثْلًا بِمِثْلٍ ‏","","",""],[11007,11007,"","আমরা আমার বাবা তাকে সাহায্য করার চেষ্টা করেছি বলে ঈশ্বর তার জন্য প্রার্থনা করেছেন। সেখানে গিয়ে তাদের কেউ কেউ চড় মেরে চুরি করে আর চুরি করে খুশি হবে না।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الذَّهَبُ بِالذَّهَبِ ‏ ‏وَالْوَرِقُ ‏ ‏بِالْوَرِقِ ‏ ‏وَلَا تُفَضِّلُوا بَعْضَهَا عَلَى بَعْضٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏مِثْلَهُ بِإِسْنَادِهِ ‏","","",""],[11008,11008,"","আমরা সেই বধিরদের কথা বলেছি, যা আমাদের বাবার ছেলে হওয়ার চেষ্টা করছে। বার্কলাটার আশীর্বাদে সকাল বেলায় কাজ করছে","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏الْمَهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏مُدِّنَا ‏ ‏اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏صَاعِنَا ‏ ‏وَاجْعَلْ مَعَ الْبَرَكَةِ بَرَكَتَيْنِ ‏","","",""],[11009,11009,"","আমার বাবা হয়তো বলেছিলেন যে, আপনি হয়তো এই কথাগুলো শুনে খুশি হবেন । তুমি তাদের দেখেছ, তুমি তাদের আর নিষ্পাপ দেখেছ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قُلْنَا يَا رَسُولَ اللَّهِ هَذَا السَّلَامُ عَلَيْكَ قَدْ عَلِمْنَاهُ فَكَيْفَ الصَّلَاةُ عَلَيْكَ قَالَ قُولُوا ‏ ‏اللَّهُمَّ صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏عَبْدِكَ وَرَسُولِكَ كَمَا صَلَّيْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَبَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَآلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا بَارَكْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَآلِ ‏ ‏إِبْرَاهِيمَ ‏","","",""],[11010,11010,"","আমরা আপনাকে সারা জীবনের জন্য আশীর্বাদ করতে চেয়েছিলাম, যখন আমরা আপনাকে ঈশ্বরের দোহাই দিয়ে কিনতে চেষ্টা করেছি। তার বাবার কথা বলেছিলাম আমরা ঈশ্বরের ইচ্ছার সাথে বের হয়ে যাবো এবং তাকে উদ্ধার করবো। আমি একটা স্বপ্ন দেখেছি যেটা তাকে উদ্ধার করতে হবে আর দুটো বই দিতে হবে। তাকে রক্ষা করলাম এবং সে বলবে যে আমরা তাকে বরখাস্ত করেছি... ...যে তাকে বলে যে, সে রাব্বির ছেলে, আমি তাকে দেখতে পাচ্ছি যদি কোন মহিলা তাকে পানি না দেয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏شَرِيكِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي نَمِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏قُبَاءَ ‏ ‏يَوْمَ ‏ ‏الِاثْنَيْنِ فَمَرَرْنَا فِي ‏ ‏بَنِي سَالِمٍ ‏ ‏فَوَقَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِبَابِ ‏ ‏ابْنِ عِتْبَانَ ‏ ‏فَصَرَخَ ‏ ‏وَابْنُ عِتْبَانَ ‏ ‏عَلَى بَطْنِ امْرَأَتِهِ فَخَرَجَ يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏فَلَمَّا رَآهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَعْجَلْنَا الرَّجُلَ قَالَ ‏ ‏ابْنُ عِتْبَانَ ‏ ‏يَا رَسُولَ اللَّهِ أَرَأَيْتَ الرَّجُلَ إِذَا ‏ ‏أَتَى ‏ ‏امْرَأَةً وَلَمْ ‏ ‏يُمْنِ ‏ ‏عَلَيْهَا مَاذَا عَلَيْهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا ‏ ‏الْمَاءُ مِنْ الْمَاءِ ‏","","",""],[11011,11011,"","আমি আমার বাবাকে বলেছিলাম যে সে নাকি ভুল করে তাকে উপরে যেতে বলবে। আমি তাকে বলবো কে ঈশ্বর ও ঈশ্বরকে ভয় দেখাবে। এটা গান গাইতে হবে, ধৈর্য্য ধরে রাখো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏زَيْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي أَهْلِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْأَلُهُ طَعَامًا فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَخْطُبُ فَسَمِعْتُهُ يَقُولُ ‏ ‏مَنْ يَصْبِرْ يُصَبِّرْهُ اللَّهُ وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ وَمَنْ ‏ ‏يَسْتَعِفَّ ‏ ‏يُعِفَّهُ ‏ ‏اللَّهُ وَمَا رُزِقَ الْعَبْدُ رِزْقًا أَوْسَعَ لَهُ مِنْ الصَّبْرِ ‏","","",""],[11012,11012,"","ঈশ্বর বলে আপনি প্রভুর সবচেয়ে ভদ্র পর্দা নন । বলা হয়েছে অন্ধ হয়ে যাওয়া আর আঘাত করা বন্ধ করা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏زَيْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِيَّاكُمْ وَالْجُلُوسَ بِالطُّرُقَاتِ قَالُوا يَا رَسُولَ اللَّهِ مَا لَنَا مِنْ مَجَالِسِنَا بُدٌّ نَتَحَدَّثُ فِيهَا قَالَ ‏ ‏فَأَعْطُوا الطَّرِيقَ حَقَّهَا قَالُوا وَمَا حَقُّ الطَّرِيقِ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏غَضُّ ‏ ‏الْبَصَرِ وَكَفُّ الْأَذَى وَالْأَمْرُ بِالْمَعْرُوفِ وَالنَّهْيُ عَنْ الْمُنْكَرِ ‏","","",""],[11013,11013,"","আমরা আমার বাবার সাথে ঈশ্বরের কথা বলেছিলাম, আমার পরে ভাইয়ের সাথে আমার পরে দেখা হয়েছে, সে একটা অন্ত্যেষ্টিক্রিয়ার মাধ্যমে চলে গেছে, সে বলেনি যে সে ঈশ্বরকে শান্তি দিতে বলেছে। যা চেয়েছিল.","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي السَّفَرِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏مُرَّ عَلَى ‏ ‏مَرْوَانَ ‏ ‏بِجَنَازَةٍ فَلَمْ يَقُمْ قَالَ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُرَّ عَلَيْهِ بِجَنَازَةٍ فَقَامَ قَالَ فَقَامَ ‏ ‏مَرْوَانُ ‏","","",""],[11014,11014,"","আমরা আপনার বাবার মৃত্যুর পর যারা আমাদের জন্য খুশি হয়েছে তাদের কথা বলছি। আমরা তাদের মানুষদের স্পর্শ করব, আমি আল্লাহর কাছে প্রার্থনা করব যেন তিনি মুক্তি পান। তার সব থেকে পানি বের হবে ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَصَبْنَا ‏ ‏سَبْيًا ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فَكُنَّا نَلْتَمِسُ فِدَاءَهُنَّ فَسَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْعَزْلِ ‏ ‏فَقَالَ ‏ ‏اصْنَعُوا مَا بَدَا لَكُمْ فَمَا قَضَى اللَّهُ فَهُوَ كَائِنٌ فَلَيْسَ مِنْ كُلِّ ‏ ‏الْمَاءِ ‏ ‏يَكُونُ الْوَلَدُ ‏","","",""],[11015,11015,"","আমরা কিছু সমস্যায় পড়েছি, মাথা মাস্টার করার জন্য, নবী ঈশ্বরের কাছে প্রার্থনা করেছেন, তিনি বলেছিলেন তিনি ছিলেন একজন ভালো লেখক।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خُلَيْدِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏ذُكِرَ الْمِسْكُ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هُوَ أَطْيَبُ الطِّيبِ ‏","","",""],[11016,11016,"","আমরা দু'বছরের কথা বলেছি যখন হঠাৎ করে আমরা দু'বার ভীত হয়ে পড়ি, আমার বাবা খুশি যে ঈশ্বর তাকে পাঠাতে বলেছেন এবং তাকে আদেশ দিয়েছেন। আমি তাকে বলতে চাই যে তাকে খুন করতে হবে। ভয় পাওয়া, বাবা, কথা বলা, কথা বলা এবং আমার সাথে কথা বলা।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَعَبْدِ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحْقِرَنَّ أَحَدُكُمْ نَفْسَهُ إِذَا رَأَى أَمْرًا لِلَّهِ فِيهِ مَقَالٌ أَنْ يَقُولَ فِيهِ فَيُقَالُ لَهُ يَوْمَ الْقِيَامَةِ ‏ ‏مَا مَنَعَكَ أَنْ تَقُولَ ‏ ‏فِيهِ فَيَقُولُ رَبِّ خَشِيتُ النَّاسَ قَالَ فَأَنَا أَحَقُّ أَنْ ‏ ‏تَخْشَى ‏ ‏وَقَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏يَعْنِي فِي الْحَدِيثِ وَإِنِّي كُنْتُ أَحَقُّ أَنْ تَخَافَنِي ‏","","",""],[11017,11017,"","আমরা আমার বাবার ছেলেকে খুশি করার কথা বলেছি, যখন তারা আগুন জ্বালিয়ে দিবে, আর তারা জেলে যাবে, আমাদের স্বপ্নের কথা বলছি। আমার সবচেয়ে ভালো আচরণ সম্পর্কে, ড্রাগ বলেছিল, তারা তোমার মত সুখী হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَخْرُجُ نَاسٌ مِنْ النَّارِ بَعْدَمَا احْتَرَقُوا وَصَارُوا فَحْمًا فَيَدْخُلُونَ الْجَنَّةَ فَيَنْبُتُونَ فِيهَا كَمَا يَنْبُتُ ‏ ‏الْغُثَاءُ ‏ ‏فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عَلَيِّ بْنِ صَالِحٍ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏فَيَنْبُتُونَ كَمَا تَنْبُتُ ‏ ‏السَّعْدَانَةُ ‏","","",""],[11018,11018,"","আমরা তোমার ক্রেতাদের কথা বলেছি তার বাবার খুশি বাবাকে বলে যে, নবী তার ক্ষমতায় আছে। তো তুমি একটা অন্ত্যেষ্টিক্রিয়া বিক্রি করছ, সে তোমাকে না দেয়া পর্যন্ত বসে ছিল না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَبِعَ جَنَازَةً لَمْ يَجْلِسْ حَتَّى تُوضَعَ ‏","","",""],[11019,11019,"","আমরা একটা ছেলের কথা বলেছিলাম যে ঈশ্বর হতে চেয়েছিলেন, সে আত্মসমর্পণ করবে যদি আমি সঠিক বলতে না পারি যে...","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ عَمَّارٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ شُمَيْخٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اجْتَهَدَ فِي الْيَمِينِ قَالَ لَا وَالَّذِي نَفْسُ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏بِيَدِهِ ‏","","",""],[11020,11020,"","আমরা একসাথে কথা বলেছি, কিন্তু একবার অভ্যাস করার পর আমরা নিয়ম মেনে চলে এসেছি। আমার বাবা তার কাছে বলেছেন যে তিনি এটা নিয়ে যেতে পেরেছেন। শেষবার আমরা একটা করে ফেলেছি। আমি এটা নিয়ে এসেছি। আমি মনে করি, আমি যদি আমার বাবা আমাদের কাছে ফিরে যেতে চান, আমি জানি, আমি কি এটা নিয়ে যেতে পারি? আমি জানি, আমি কি এটা করতে পারি? পার্থক্য হলো আমার বাবার সম্পর্কে তার সম্পর্কে খারাপ কথা বলা। পাস।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُثَنَّى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَوَكِيعٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي عِيسَى ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُودُوا ‏ ‏الْمَرْضَى وَاتَّبِعُوا الْجَنَائِزَ تُذَكِّرُكُمْ الْآخِرَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي عِيسَى الْأُسْوَارِيِّ ‏ ‏فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ الْمَرِيضَ ‏","","",""],[11021,11021,"","আমরা একে অপরের কথা বলেছি, আমার ছেলেকে শুনতে সক্ষম হবে। এটা আপ.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ عَلِيٍّ الرَّبْعِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْجَوْزَاءِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يُفْتِي فِي ‏ ‏الصَّرْفِ ‏ ‏قَالَ فَأَفْتَيْتُ بِهِ زَمَانًا قَالَ ثُمَّ لَقِيتُهُ فَرَجَعَ عَنْهُ قَالَ فَقُلْتُ لَهُ وَلِمَ فَقَالَ إِنَّمَا هُوَ رَأْيٌ رَأَيْتُهُ حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُ ‏","","",""],[11022,11022,"","আমরা বাবার সবচেয়ে ভাল শপথ নিয়ে কথা বলেছি, যেখানে তিনি নিজের ভাষায় কথা বলেছেন, ঈশ্বরের একজন মই আছে যে তাকে হত্যা করবে বা ক্রুদের হত্যা করবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ الْعَبْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْرُقُ ‏ ‏مَارِقَةٌ ‏ ‏عِنْدَ فِرْقَةٍ مِنْ الْمُسْلِمِينَ يَقْتُلُهَا أَوْلَى الطَّائِفَتَيْنِ بِالْحَقِّ ‏","","",""],[11023,11023,"","আমরা বাবার সবচেয়ে ভাল পছন্দের কথা বলেছি। কিন্তু, সে আমার জীবনের সব কথা বলে এবং তারা আমাকে মেরে ফেলবে। একে অপরের সাথে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَعَمِّهِ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُوا لُحُومَ الْأَضَاحِيِّ وَادَّخِرُوا ‏","","",""],[11024,11024,"","আমরা আমার প্রতিভার কথা বলেছি যখন আমরা থামছিলাম, আমার বাবা তার কাছে প্রার্থনা করতে পেরে খুশি। আর তিনি বধিরদের যা বলেছেন, তারা আসলে দু:খী নয়, তারা আঘাত পায় না, এমনকি অন্ধকারও নয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ حَلْحَلَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا يُصِيبُ الْمُؤْمِنَ مِنْ ‏ ‏وَصَبٍ ‏ ‏وَلَا ‏ ‏نَصَبٍ ‏ ‏وَلَا هَمٍّ وَلَا حَزَنٍ وَلَا أَذًى وَلَا غَمٍّ حَتَّى الشَّوْكَةِ يُشَاكُهَا إِلَّا كَفَّرَ اللَّهُ مِنْ خَطَايَاهُ ‏","","",""],[11025,11025,"","আমরা আমার ছেলেকে বলেছিলাম যে আমাদের ভাই আমাকে সাহায্য করার চেষ্টা করছে, ঈশ্বর তাকে জিজ্ঞেস করেছেন আর যদি তিনি সেটা করেন তাহলে তিনি তাকে অনুসরণ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا رَأَيْتُمْ الْجَنَازَةَ فَقُومُوا فَمَنْ اتَّبَعَهَا فَلَا يَقْعُدْ حَتَّى تُوضَعَ ‏","","",""],[11026,11026,"","আমরা একটা স্বপ্নের কথা বলেছিলাম যেটা বাবার মত জীবনযাপনের কথা বলে আমার বাবা খুশি মনে বলেছিলেন আমরা ঈশ্বরের অনুগ্রহে মিলিত হব আর আল্লাহ্‌ই হবেন। এটা সম্ভব.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَيَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا نُرْزَقُ تَمْرَ ‏ ‏الْجَمْعِ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11027,11027,"","আমরা একটা ছেলেকে ঘাস নিয়ে ঘুরে বেড়ালাম, বাবা, যে কিনা বলত ঈশ্বর যেন সব থেকে ভালো হয়, এটা একটা শীতের বিষ।","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ إِيَاسٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَمْأَةُ ‏ ‏مِنْ ‏ ‏الْمَنِّ ‏ ‏وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ وَالْعَجْوَةُ مِنْ الْجَنَّةِ وَهِيَ شِفَاءٌ مِنْ السُّمِّ ‏","","",""],[11028,11028,"","আমরা লর্ডের কাছে উৎসাহ পেয়েছি বেনকে আমার বাবার আনন্দ বাড়ানোর জন্য, সে বলবে তারা যদি অল্প ছিল, তাদের দোষ দিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏شُجَاعُ بْنُ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانُوا ثَلَاثَةً فَلْيَؤُمَّهُمْ أَحَدُهُمْ وَأَحَقُّهُمْ بِالْإِمَامَةِ أَقْرَؤُهُمْ ‏","","",""],[11029,11029,"","তিনি গ্র্যাজুয়েট হওয়ার পর, তার প্রতি প্রেম দেখানোর জন্য ঈশ্বর তাকে নিযুক্ত করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيُحَجَّنَّ ‏ ‏الْبَيْتُ ‏ ‏بَعْدَ خُرُوجِ ‏ ‏يَأْجُوجَ ‏ ‏وَمَأْجُوجَ ‏","","",""],[11030,11030,"","ঈশ্বর তার জন্য প্রার্থনা করবেন এবং তিনি আমার উত্তরাধিকারী হবেন, যিনি এত টাকা পাবেন না আর তাকে গণনা করবেন না । পিছনে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكُونُ بَعْدِي خَلِيفَةٌ ‏ ‏يَحْثِي ‏ ‏الْمَالَ ‏ ‏حَثْيًا ‏ ‏وَلَا يَعُدُّهُ عَدًّا ‏","","",""],[11031,11031,"","আমরা এক জীবন যাপনের কথা বলেছিলাম, আর তাকে আমাদের বাবাকে কতটা ভালবাসি বলে খুশি হলাম। এই জাহাজের মোড়কে আটকে রাখার জন্য তাকে ওই ছাত্রদের বিক্রির সুযোগ করে দিতে হবে যাতে সে তার ভাল কিছু করার সুযোগ পায়. তারা একটু দৌড়াচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَيَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏كُنَّا نُرْزَقُ تَمْرَ ‏ ‏الْجَمْعِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏تَمْرًا مِنْ تَمْرِ ‏ ‏الْجَمْعِ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَبِيعُ ‏ ‏الصَّاعَيْنِ ‏ ‏بِالصَّاعِ ‏ ‏فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا ‏ ‏صَاعَيْ ‏ ‏تَمْرٍ ‏ ‏بِصَاعٍ ‏ ‏وَلَا ‏ ‏صَاعَيْ ‏ ‏حِنْطَةٍ ‏ ‏بِصَاعٍ ‏ ‏وَلَا دِرْهَمَيْنِ بِدِرْهَمٍ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏لَا ‏ ‏صَاعَا ‏ ‏تَمْرٍ ‏ ‏بِصَاعٍ ‏ ‏وَلَا ‏ ‏صَاعَا ‏ ‏حِنْطَةٍ ‏ ‏بِصَاعٍ ‏","","",""],[11032,11032,"","আমি আমার ভাইয়ের সাথে খারাপ ভাইয়ের সম্পর্ক নিয়ে কথা বলেছি, আমি আমার বাবার কাছ থেকে শুনেছি যে তিনি পৃথিবীতে যে ভবিষ্যদ্বাণী করেছেন তা জানতে পেরে খুশি। এটার মূল্য অনেক বেশি।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏مَعْبَدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قُلْتُ لَهُ سَمِعْتَهُ مِنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ نَعَمْ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْعَزْلِ ‏ ‏قَالَ ‏ ‏لَا عَلَيْكُمْ أَنْ لَا تَفْعَلُوا ذَلِكُمْ فَإِنَّمَا هُوَ الْقَدَرُ ‏","","",""],[11033,11033,"","আমরা আমার প্রিয় ছেলের কাছে তার সাহায্যের জন্য প্রার্থনা করেছিলাম, ঈশ্বর তাকে প্রার্থনা করতেন এবং যদি তিনি উপস্থিত হতেন, তিনি আত্মসমর্পণ করতেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ ‏ ‏يُصَلِّي فَلَا يَتْرُكْ أَحَدًا يَمُرُّ بَيْنَ يَدَيْهِ فَإِنْ أَبَى فَلْيُقَاتِلْهُ فَإِنَّمَا هُوَ شَيْطَانٌ ‏","","",""],[11034,11034,"","আমরা কথা বলেছি খারাপ ছেলে বা অন্যকিছুর সাথে আমাদের লড়াই করতে হয়েছে। প্রার্থনা করা এমন একজন মানুষ যিনি বলেছেন, \"ঈশ্বর,\" তুমি বলেছিলে, \"এখান থেকে বেরিয়ে যাও\" তিনি হয়ত আমাকে বলতেন আল্লাহ আছে। তাকে বলে সে তোমাকে কে দেখেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏أَوَّلُ مَنْ قَدَّمَ الْخُطْبَةَ قَبْلَ الصَّلَاةِ ‏ ‏مَرْوَانُ ‏ ‏فَقَامَ رَجُلٌ فَقَالَ يَا ‏ ‏مَرْوَانُ ‏ ‏خَالَفْتَ السُّنَّةَ قَالَ تُرِكَ مَا هُنَاكَ يَا أَبَا فُلَانٍ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَمَّا هَذَا فَقَدْ قَضَى مَا عَلَيْهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ ‏","","",""],[11035,11035,"","আমরা যে সব থেকে ভালো লড়াই করেছি, তার কথা বলছি কিন্তু সে খুশি হবে। আমার বাবা, ঈশ্বরের কাছে প্রার্থনা করে তার কাছে প্রার্থনা করেছেন। আর তিনি আমার মেয়েকে ফিরিয়ে নিয়ে এসেছেন। আমি যত মানুষ চ্যালেঞ্জ করি আর ভাড়া করি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبُ بْنُ شَدَّادٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏الْمَهْدِيِّ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ بَعْثًا إِلَى ‏ ‏بَنِي لِحْيَانَ ‏ ‏مِنْ ‏ ‏هُذَيْلٍ ‏ ‏فَقَالَ ‏ ‏لِيَنْبَعِثْ مِنْ كُلِّ رَجُلَيْنِ أَحَدُهُمَا وَالْأَجْرُ بَيْنَهُمَا ‏","","",""],[11036,11036,"","আমরা আমার বাবার সবচেয়ে ভালো কথা বলেছি, আমার বাবা বাবার সাথে পালিয়ে যাওয়ার চেষ্টা করছে, দুই বছর আগে আমরা তাদের বোকা বানিয়েছি আর আমরা তোমার অভিজাতদের মেরে ফেলব। আল্লাহ্‌র আত্মসমর্পণ করুন, আমি ঈশ্বরের কাছে প্রার্থনা করব, যেন তিনি তার কাছে প্রার্থনা করেন এবং আমি যা বলি তার থেকে তাকে আত্মসমর্পণ না করে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏أَصَبْنَا ‏ ‏سَبْيًا ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فَجَعَلْنَا ‏ ‏نَعْزِلُ ‏ ‏عَنْهُمْ وَنَحْنُ نُرِيدُ الْفِدَاءَ فَقَالَ بَعْضُنَا لِبَعْضٍ تَفْعَلُونَ ذَلِكَ وَفِيكُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَيْسَ مِنْ كُلِّ ‏ ‏الْمَاءِ ‏ ‏يَكُونُ الْوَلَدُ إِذَا أَرَادَ اللَّهُ أَنْ يَخْلُقَ شَيْئًا لَمْ يَمْنَعْهُ شَيْءٌ ‏","","",""],[11037,11037,"","বাবার সব থেকে ভালো সমস্যা আর আমার ভালোবাসা আমার বাবার জন্য খেপেছে। আমার বাবা খুশি যে তারা ঈশ্বরের কাছে প্রার্থনা করছে। ( ২ বংশা.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَسُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ أَبِي مُسْلِمٍ ‏ ‏قَالَ أَشْهَدُ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏أَنَّهُمَا ‏ ‏شَهِدَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا جَلَسَ قَوْمٌ يَذْكُرُونَ اللَّهَ إِلَّا ‏ ‏حَفَّتْ ‏ ‏بِهِمْ الْمَلَائِكَةُ وَغَشِيَتْهُمْ الرَّحْمَةُ وَذَكَرَهُمْ اللَّهُ فِيمَنْ عِنْدَهُ ‏","","",""],[11038,11038,"","আমরা আমার বাবার কথা বলেছিলাম যে আমাদের একজন বড় ভাই আমাদের সাথে কথা বলেছে আমার ভাইয়ের দুর্বল নেতা হিসেবে। ঈশ্বরের কাছে তার আদেশ আছে এবং গোপন আর পাসের মাধ্যমে আত্মসমর্পণ করা হবে। এবং পাস করে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ خَلِيطِ ‏ ‏الْبُسْرِ ‏ ‏وَالتَّمْرِ وَالزَّبِيبِ وَالتَّمْرِ ‏","","",""],[11039,11039,"","আমরা রাজার সাথে কথা বলেছি, বাবার সাথে আমার দেখা করার প্রয়োজন হবে, হয়তো আমার বাবা আমার চেয়ে ভালো বাবা হতে পেরে খুশি হবেন। এমনকি আমরা রাতের বেলায় ছিলাম। ঈশ্বর তাকে মেরে ফেলতে সক্ষম হয়েছেন এবং ঈশ্বর তাকে মারতে সক্ষম হয়েছেন। আর প্রার্থনা করার সময় তিনি তার প্রার্থনার উত্তর দেবেন। ঈশ্বর ভয় অথবা হাঁটু গেড়ে বসে আছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏حُبِسْنَا يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏عَنْ الصَّلَاةِ حَتَّى كَانَ بَعْدَ الْمَغْرِبِ ‏ ‏بِهَوِيٍّ ‏ ‏مِنْ اللَّيْلِ حَتَّى كُفِينَا وَذَلِكَ قَوْلُ اللَّهِ تَعَالَى ‏ { ‏وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ وَكَانَ اللَّهُ قَوِيًّا عَزِيزًا ‏} ‏قَالَ ‏ ‏فَدَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلَالًا ‏ ‏فَأَقَامَ صَلَاةَ الظُّهْرِ فَصَلَّاهَا وَأَحْسَنَ صَلَاتَهَا كَمَا كَانَ يُصَلِّيهَا فِي وَقْتِهَا ثُمَّ أَمَرَهُ فَأَقَامَ الْعَصْرَ فَصَلَّاهَا وَأَحْسَنَ صَلَاتَهَا كَمَا كَانَ يُصَلِّيهَا فِي وَقْتِهَا ثُمَّ أَمَرَهُ فَأَقَامَ الْمَغْرِبَ فَصَلَّاهَا كَذَلِكَ قَالَ وَذَلِكُمْ قَبْلَ أَنْ يُنْزِلَ اللَّهُ فِي صَلَاةِ الْخَوْفِ ‏ { ‏فَرِجَالًا أَوْ رُكْبَانًا ‏}","","",""],[11040,11040,"","ঈশ্বর তাঁর প্রভু অথবা তাঁর প্রভুকে আদেশ দিয়েছেন । তাকে দেয়া হয়েছে আর আমার বাবা অনেক দূরে চলে গেছে, আর ভালো খবরও আসছে D-db-db-db-db-db-db-db-db-db-db-db-db-db-bb-db-db-db-dbb-db-dbbb-db-dddb-db-db-db-db-db-dddddb-db-dddddb-db-dddb-db-db-dddb-db-db-db-ddddddddddddb-ddb-dddb-db-db-db-ddddddb-db-ddb-dddb-db-dddddddddb-dddddddddddd-d-d-d-d-ddddব-ddddd-d-d-d-db-ddddd-d-d-dd-dd d-dddddd-dd-dddd-dd-dddd-dd-dd-dddddddddd-dd-dddddd-dddddd-ddddd-dddddd-ddddddd-ddddddddddddddddnddddddddddd-dddddddddd-dddd-dddddddddddddddddddddd-dddddddddddddddddddddddd-ddddddddddddddddddddddddddddddddddddddddd-ddddddddddddddddd-d-ddddddddddddddddddddd আর এটাকে খারাপ কিছু দিয়ে দাও।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُتَوَكِّلِ النَّاجِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ رَجُلٌ مِنْ الْقَوْمِ أَمَا بَيْنَكَ وَبَيْنَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيْرُ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ لَا وَاللَّهِ مَا بَيْنِي وَبَيْنَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيْرُ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏الذَّهَبُ بِالذَّهَبِ وَالْفِضَّةُ ‏ ‏بِالْفِضَّةِ ‏ ‏وَالْبُرُّ ‏ ‏بِالْبُرِّ ‏ ‏وَالشَّعِيرُ بِالشَّعِيرِ وَالتَّمْرُ بِالتَّمْرِ وَالْمِلْحُ بِالْمِلْحِ سَوَاءً بِسَوَاءٍ مَنْ زَادَ أَوْ ازْدَادَ فَقَدْ ‏ ‏أَرْبَى ‏ ‏الْآخِذُ وَالْمُعْطِي فِيهِ سَوَاءٌ ‏","","",""],[11041,11041,"","আমরা একটা হাত দিয়ে খেলতে চেষ্টা করেছি, যা আমার বাবার মৃত্যুর পর আমাকে সাহায্য করেছে। সে বলল, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি যাকে দেখব, তার কাছে আমার কাছে পেশ করবে। বাবা ঘুমের ঘোরে উঠেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَهْلَ ‏ ‏عِلِّيِّينَ ‏ ‏لَيَرَاهُمْ مَنْ هُوَ أَسْفَلَ مِنْهُمْ كَمَا يُرَى الْكَوْكَبُ فِي أُفُقِ السَّمَاءِ وَإِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏لَمِنْهُمْ وَأَنْعَمَا ‏","","",""],[11042,11042,"","আমরা আমার ভাগ্যের সাথে লড়াই করার কথা বলেছিলাম, ঈশ্বর বলে যে ঈশ্বর তার কাছে প্রার্থনা করেছেন আর যদি আমি কখনো তাকে আত্মসমর্পণ করি, আমি দুইজন মানুষকে খুঁজে পাব না, তাই আমি করছি আমি এমন কিছু করবো, সে তার নাকের বাতাস পেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏عِيَاضُ بْنُ هِلَالٍ الْأَنْصَارِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فَنَسِيَ كَمْ صَلَّى ‏ ‏أَوْ قَالَ فَلَمْ يَدْرِ زَادَ أَمْ نَقَصَ ‏ ‏فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ وَإِذَا جَاءَ أَحَدَكُمْ الشَّيْطَانُ فَقَالَ إِنَّكَ قَدْ ‏ ‏أَحْدَثْتَ ‏ ‏فَلْيَقُلْ كَذَبْتَ إِلَّا مَا سَمِعَهُ بِأُذُنِهِ أَوْ وَجَدَ رِيحَهُ بِأَنْفِهِ ‏","","",""],[11043,11043,"","আমরা কথা বলেছিলাম যে আমরা কতটা খুশি ছিলাম। অভিজ্ঞ গুরু বলেছিলেন, তার কাছে যেন তার বধিরতা আর তার নাম আবার পাওয়া যায়। তারপর প্রভু আপনাকে বলেন, তোমাকে বলা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اسْتَجَدَّ ‏ ‏ثَوْبًا سَمَّاهُ بِاسْمِهِ عِمَامَةً أَوْ قَمِيصًا أَوْ رِدَاءً ثُمَّ يَقُولُ ‏ ‏اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ أَسْأَلُكَ خَيْرَهُ وَخَيْرَ مَا صُنِعَ لَهُ وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَمِنْ شَرِّ مَا صُنِعَ لَهُ ‏","","",""],[11044,11044,"","আমরা একটি সুখী ছেলেকে লিখতে চেষ্টা করেছি, আমরা আল্লাহ্‌র পরে আমার ভাইকে খুঁজে বের করার ব্যাপারে কথা বলেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার পিতার একটি ভুল ধারণা রয়েছে। তার যথাসাধ্য করাকে বোকামি করো, আগুনের এক আলোকে, সে তার হৃদয় কামড় দেয়।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذُكِرَ عِنْدَهُ عَمُّهُ ‏ ‏أَبُو طَالِبٍ ‏ ‏فَقَالَ ‏ ‏لَعَلَّهُ تَنْفَعُهُ ‏ ‏شَفَاعَتِي ‏ ‏يَوْمَ الْقِيَامَةِ فَيُجْعَلَ فِي ‏ ‏ضَحْضَاحٍ ‏ ‏مِنْ النَّارِ يَبْلُغُ كَعْبَيْهِ يَغْلِي مِنْهُ دِمَاغُهُ ‏","","",""],[11045,11045,"","আমি আমার বাবাকে বলেছিলাম যে, তিনি আমাদের সঙ্গে আছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ إِيَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏كُنَّا نُسَافِرُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَمَضَانَ ‏ ‏فَمِنَّا الصَّائِمُ وَمِنَّا الْمُفْطِرُ فَلَا يَعِيبُ الصَّائِمُ عَلَى الْمُفْطِرِ وَلَا الْمُفْطِرُ عَلَى الصَّائِمِ ‏","","",""],[11046,11046,"","ঈশ্বরের পুত্র-স্বজন দ্বারা বাপ্তাইজিত হয়েছি, অথবা আমরা আন্তরিকতার সাথে কথা বলেছি। আমার পিতার ভালো ইচ্ছার দুটি আত্মার কথা তিনি ঈশ্বরের সাথে কথা বলেছিলেন। তিনি ঈশ্বরের ইচ্ছার সাথে কথা বলেছেন। তারা অনেক কিছু করেছে। তারা এটা করতে পারে না। তারা আসলে, তারা একটি মহান কাজ করেছে। তারা আমাদের কাছে আছে। আমরা যদি তাদের কাছে এটা নিয়ে কথা বলে, আমরা যদি কিছু না বলি, তাহলে আমরা এটা করতে পারি। আমরা আমাদের কাছে এটা একটা ভাল উপায় আছে। আমরা শুধু একটা প্রশ্ন করি। আমরা যদি আমাদের কাছে এটা একটা প্রশ্ন করি, তাহলে আমরা আমাদের কাছে এটা একটা প্রশ্ন করি, আমরা শুধু একটা প্রশ্ন করি। আমরা কি করতে পারি। আমরা কি করবো? কিন্তু আমরা যদি আমাদের পিতা-মাইনসত্ত্বে, আমরা আমাদের পিতা-মানুষ না, তাহলে আমরা এটা করতে পারি। আমরা এটা আমাদের কাছে এটা একটা বড় কিছু করতে হবে। কিন্তু আমরা যদি আমরা শুধু একটা প্রশ্ন করি, তাহলে আমরা আমাদের পিতা-মাশার সাথে কথা বলি। আমরা যখন আমরা এটা করতে পারি, আমরা এটা করতে পারি। আমরা যখন আমরা এটা করি, তখন আমরা এটা হবে। আমরা যখন আমরা এটা একটা প্রশ্ন করি, আমরা যখন আমরা এটা করি, তখন আমরা যখন আমরা আমাদের পিতা----------------------- আমরা যে গ্রাম খুব শীঘ্রই করতে পারি, আপনি কত পুরুষ বলতে পারবেন আমার বাবা তিনি মারা গেছেন? আমি একবার তাকে এটা করতে বলেছি, তিনি এটা করেছেন, আমি কিছু ছেড়ে দেব আমরা এটা করতে পারি না, যদিও ঈশ্বর তাকে জিজ্ঞেস করেছেন এবং আমাদের সবাইকে মেরে ফেলবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ النُّعْمَانِ أَبُو النُّعْمَانِ الْأَنْصَارِيُّ ‏ ‏بِالْكُوفَةِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ قَنَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْثًا فَكُنْتُ فِيهِمْ فَأَتَيْنَا عَلَى قَرْيَةٍ فَاسْتَطْعَمْنَا أَهْلَهَا فَأَبَوْا أَنْ يُطْعِمُونَا شَيْئًا فَجَاءَنَا رَجُلٌ مِنْ أَهْلِ الْقَرْيَةِ فَقَالَ يَا مَعْشَرَ ‏ ‏الْعَرَبِ ‏ ‏فِيكُمْ رَجُلٌ ‏ ‏يَرْقِي ‏ ‏فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏قُلْتُ وَمَا ذَاكَ قَالَ مَلِكُ الْقَرْيَةِ يَمُوتُ قَالَ فَانْطَلَقْنَا مَعَهُ ‏ ‏فَرَقَيْتُهُ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏فَرَدَّدْتُهَا عَلَيْهِ مِرَارًا فَعُوفِيَ فَبَعَثَ إِلَيْنَا بِطَعَامٍ وَبِغَنَمٍ تُسَاقُ فَقَالَ أَصْحَابِي لَمْ يَعْهَدْ إِلَيْنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا بِشَيْءٍ لَا نَأْخُذُ مِنْهُ شَيْئًا حَتَّى نَأْتِيَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسُقْنَا الْغَنَمَ حَتَّى أَتَيْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَدَّثْنَاهُ فَقَالَ ‏ ‏كُلْ وَأَطْعِمْنَا مَعَكَ وَمَا يُدْرِيكَ أَنَّهَا ‏ ‏رُقْيَةٌ ‏ ‏قَالَ قُلْتُ أُلْقِيَ فِي ‏ ‏رَوْعِي ‏","","",""],[11047,11047,"","আমরা চেষ্টা করেছি এমন একটা ছেলেকে খুঁজতে, যে কিনা কখনো জীবিত বাবা মাদকের শিকার হয়ে বলে যে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার প্রার্থনার জন্য প্রার্থনা করেছেন। এরপর তিনি ঈশ্বরের কাছে বলেন, ঈশ্বর ঈশ্বর ঈশ্বর জানেন যে, তিনি কোথায় যান এবং তিনি জয় করেন । তার পরাজয় আর তার ভীতি আর তার লুটন আর উত্তেজনা।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْحَسَنِ بْنِ أَتْشٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ يَعْنِي ابْنَ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَلِيٍّ الْيَشْكُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ مِنْ اللَّيْلِ وَاسْتَفْتَحَ صَلَاتَهُ وَكَبَّرَ قَالَ ‏ ‏سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ تَبَارَكَ اسْمُكَ وَتَعَالَى ‏ ‏جَدُّكَ ‏ ‏وَلَا إِلَهَ غَيْرُكَ ثُمَّ يَقُولُ لَا إِلَهَ إِلَّا اللَّهُ ثَلَاثًا ثُمَّ يَقُولُ أَعُوذُ بِاللَّهِ السَّمِيعِ الْعَلِيمِ مِنْ الشَّيْطَانِ الرَّجِيمِ مِنْ ‏ ‏هَمْزِهِ ‏ ‏وَنَفْخِهِ ‏ ‏ثُمَّ يَقُولُ اللَّهُ أَكْبَرُ ثَلَاثًا ثُمَّ يَقُولُ أَعُوذُ بِاللَّهِ السَّمِيعِ الْعَلِيمِ مِنْ الشَّيْطَانِ الرَّجِيمِ مِنْ ‏ ‏هَمْزِهِ ‏ ‏وَنَفْخِهِ ‏ ‏وَنَفْثِهِ ‏","","",""],[11048,11048,"","আমি বাবার চাইতে ভাল কথা বলেছি, আল্লাহ বলেছেন, আল্লাহ তাঁর জন্য প্রার্থনা করেছেন এবং তিনি কাউকে তার থেকে বিরত রাখবেন না। তিনি অনেক দিন ধরে চলে গেছেন এবং অনেক সময় ধরে তিনি খুব কাছে। সত্য বলা থেকে কখনো কিছু মনে রেখো না অথবা একটা মহান কাজ মনে রেখো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْحَسَنِ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏عَنِ ‏ ‏الْمُعَلَّى الْقُرْدُوسِيِّ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا لَا يَمْنَعَنَّ أَحَدَكُمْ رَهْبَةُ النَّاسِ أَنْ يَقُولَ بِحَقٍّ إِذَا رَآهُ ‏ ‏أَوْ شَهِدَهُ ‏ ‏فَإِنَّهُ لَا يُقَرِّبُ مِنْ أَجَلٍ وَلَا يُبَاعِدُ مِنْ رِزْقٍ أَنْ يَقُولَ بِحَقٍّ أَوْ يُذَكِّرَ بِعَظِيمٍ ‏","","",""],[11049,11049,"","আমরা রাজার স্বপ্ন নিয়ে কথা বলেছিলাম. দুই তারকা বিক্রেতা তার সাথে এই খবর তৈরি করে, সে এমনকি স্বপ্নও দেখে নি, আমি তেমন কিছু অনুভব করি না, আর আমি তাদের চিনি না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا نُرْزَقُ تَمْرَ ‏ ‏الْجَمْعِ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏تَمْرٌ مِنْ تَمْرِ ‏ ‏الْجَمْعِ ‏ ‏عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَبِيعُ ‏ ‏الصَّاعَيْنِ ‏ ‏بِالصَّاعِ ‏ ‏فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا ‏ ‏صَاعَيْ ‏ ‏تَمْرٍ ‏ ‏بِصَاعٍ ‏ ‏وَلَا ‏ ‏صَاعَيْ ‏ ‏حِنْطَةٍ ‏ ‏بِصَاعٍ ‏ ‏وَلَا دِرْهَمَيْنِ بِدِرْهَمٍ ‏","","",""],[11050,11050,"","আমরা আমার ছেলের স্বপ্নের কথা বলেছিলাম আমার প্রভুর কাছে স্বপ্ন আছে। ঈশ্বর তাকে জিজ্ঞেস করেছেন, তিনি তার অন্ত্যেষ্টিক্রিয়ার দিনগুলো দেখবেন কিনা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا رَأَيْتُمْ الْجَنَازَةَ فَقُومُوا فَمَنْ تَبِعَهَا فَلَا يَقْعُدْ حَتَّى تُوضَعَ ‏","","",""],[11051,11051,"","আমরা আমার বাবার জীবন রক্ষা করার জন্য অনেক বেশী কথা বলেছি। বাবার দাম অনেক আনন্দের যে আমার ছেলে তার কাছে প্রার্থনা করেছে এবং তাকে বলতে বলেছে, আমি একজন হ্যান্ড। সে আমাকে ছেড়ে চলে যেতে বলেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو رِفَاعَةَ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي ‏ ‏وَلِيدَةً ‏ ‏وَأَنَا ‏ ‏أَعْزِلُ ‏ ‏عَنْهَا وَأَنَا أُرِيدُ مَا يُرِيدُ الرَّجُلُ وَأَكْرَهُ أَنْ تَحْمِلَ وَإِنَّ ‏ ‏الْيَهُودَ ‏ ‏تَزْعُمُ أَنَّ ‏ ‏الْمَوْءُودَةَ ‏ ‏الصُّغْرَى ‏ ‏الْعَزْلُ ‏ ‏فَقَالَ كَذَبَتْ ‏ ‏يَهُودُ ‏ ‏إِنَّ اللَّهَ إِذَا أَرَادَ أَنْ يَخْلُقَهُ لَمْ يَسْتَطِعْ أَحَدٌ أَنْ يَصْرِفَهُ ‏","","",""],[11052,11052,"","আমরা একটি পুরনো সময় সম্পর্কে কথা বলেছি যে আমি কখনও এক সুখী ভাই চাইতে চাই। আমি প্রার্থনা করি তিনি ব্যর্থ হবেন না কারণ তিনি বলেছেন যে তিনি ঈশ্বরের প্রভু হতে আদেশ দিয়েছেন আর তাকে আত্মসমর্পণ করে, তুমি দুজন মেয়ে খুজে পেয়েছ আমি তোমাকে বলছি কিভাবে মেরে ফেলতে হয়।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عِيَاضٌ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏فَقَالَ ‏ ‏إِنَّ أَحَدَنَا ‏ ‏يُصَلِّي فَلَا يَدْرِي كَمْ صَلَّى فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فَلَمْ يَدْرِ كَمْ صَلَّى فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ فَإِذَا جَاءَ أَحَدَكُمْ الشَّيْطَانُ فَقَالَ إِنَّكَ قَدْ ‏ ‏أَحْدَثْتَ ‏ ‏فِي صَلَاتِكَ فَلْيَقُلْ كَذَبْتَ إِلَّا مَا وَجَدَ رِيحًا بِأَنْفِهِ أَوْ سَمِعَ صَوْتًا بِأُذُنِهِ ‏","","",""],[11053,11053,"","আমি বাবার বিয়ের ব্যাপারে কথা বলেছি, এমন একজন মানুষ যাকে খুন করা হয়েছে সে কোন দানব নয় যে তোমার চেয়ে বেশি মানুষ হতে পারে। আমি তাকে গ্রীষ্মের কথা জিজ্ঞেস করেছিলাম... ...তিনি বলেছিলেন যে আপনি আমার একজন বলেছেন, আপনার দৃষ্টি আমার এবং এজন্যই আমার বাবা হতে যাচ্ছে তার সাথে কথা বলে খুশি হলাম, সে আমাকে ঈশ্বরের বার্তাবাহকের সাথে দেখা করতে দেখেছে, ঈশ্বর তাকে জিজ্ঞেস করেছেন এবং আত্মসমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ عَلِيٍّ الرَّبْعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْجَوْزَاءِ ‏ ‏غَيْرَ مَرَّةٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏الصَّرْفِ ‏ ‏يَدًا بِيَدٍ فَقَالَ ‏ ‏لَا بَأْسَ بِذَلِكَ اثْنَيْنِ بِوَاحِدٍ أَكْثَرُ مِنْ ذَلِكَ وَأَقَلُّ ‏ ‏قَالَ ثُمَّ حَجَجْتُ مَرَّةً أُخْرَى وَالشَّيْخُ حَيٌّ فَأَتَيْتُهُ فَسَأَلْتُهُ عَنْ ‏ ‏الصَّرْفِ ‏ ‏فَقَالَ ‏ ‏وَزْنًا بِوَزْنٍ قَالَ فَقُلْتُ إِنَّكَ قَدْ أَفْتَيْتَنِي اثْنَيْنِ بِوَاحِدٍ فَلَمْ أَزَلْ أُفْتِي بِهِ مُنْذُ أَفْتَيْتَنِي فَقَالَ إِنَّ ذَلِكَ كَانَ عَنْ رَأْيِي وَهَذَا ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَرَكْتُ رَأْيِي إِلَى حَدِيثِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11054,11054,"","আমরা একজন ভালো মানুষের কথা বলেছিলাম, যে কিনা একটা কুত্তার ছেলেকে নিয়ে কথা বলেছিল। আমার যা হয় তা হচ্ছে, তুমি আমাকে শুনতে পেরে খুশি আমি তাকে যেতে দেব, আর আমি তাকে যেতে বলবো, যত খারাপই হোক না কেন, তারা সারাজীবনের জন্য বিক্রি করবে না। অথবা অন্য কিছু.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ يُحَدِّثُ ‏ ‏ابْنَ عُمَرَ ‏ ‏بِحَدِيثٍ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏فِي ‏ ‏الصَّرْفِ ‏ ‏قَالَ فَقَدِمَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَنَزَلَ هَذِهِ الدَّارَ فَأَخَذَ ‏ ‏ابْنُ عُمَرَ ‏ ‏بِيَدِي وَيَدِ الرَّجُلِ حَتَّى أَتَيْنَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏فَقَامَ عَلَيْهِ فَقَالَ مَا يُحَدِّثُنِي هَذَا عَنْكَ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏نَعَمْ بَصُرَ عَيْنِي وَسَمِعَ أُذُنِي ‏ ‏وَأَشَارَ بِإِصْبَعِهِ إِلَى عَيْنَيْهِ وَأُذُنَيْهِ فَمَا نَسِيتُ قَوْلَهُ بِإِصْبَعَيْهِ ‏ ‏مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ نَهَى عَنْ الذَّهَبِ بِالذَّهَبِ ‏ ‏وَالْوَرِقِ ‏ ‏بِالْوَرِقِ ‏ ‏إِلَّا سَوَاءً بِسَوَاءٍ مِثْلًا بِمِثْلٍ أَلَا لَا تَبِيعُوا ‏ ‏غَائِبًا ‏ ‏بِنَاجِزٍ ‏ ‏وَلَا ‏ ‏تُشِفُّوا ‏ ‏أَحَدَهُمَا عَلَى الْآخَرِ ‏","","",""],[11055,11055,"","আমার বাবা মারা যাওয়ার ব্যাপারে কথা বলেছিলাম। আমার বাবা চেষ্টা করে যাচ্ছেন। ঈশ্বরের কল্পনায় আমার বাবার আনন্দ বুঝতে পেরে আমি কষ্ট পাচ্ছি। বিশ্বাস করো, আমি তাদের শপথ করে বলছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اجْتَمَعَ ثَلَاثَةٌ فَلْيَؤُمَّهُمْ أَحَدُهُمْ وَأَحَقُّهُمْ بِالْإِمَامَةِ أَقْرَؤُهُمْ ‏","","",""],[11056,11056,"","আমরা দুই হাত দিয়ে বেঁচে থাকার চেষ্টা করেছি, কিন্তু আমরা পরম করুণাময়ের জন্য খুশি হয়েছি। ঈশ্বরের দয়ায়, ঈশ্বর এটা করেছেন এবং একটি মোটেলোর মধ্যে তারা একটি কনডমের মধ্যে ঢুকে পড়েছে। আমার বাবা আমাদের জন্য গর্বিত ছিলেন, আমাদের বাড়ির এথিকের সাথে লড়াই করতে পেরে আমি খুশি যে তুমি খুব নিষ্ঠুর হয়ে যাচ্ছ. যখন বাহিনী খেতে যাচ্ছে, তুমি জানো, আমি মানুষ. আমি. আমি তোমার জন্য গর্বিত. আমি এখন তোমার সাথে আছি. আমি তোমার সাথে যুদ্ধ করতে চাই. আমি তোমার জন্য ধন্যবাদ. আমি তোমার জন্য ধন্যবাদ. আমি তোমার জন্য ধন্যবাদ. আমি ভাল. আমি ভাল কিছু. আমি জানি. আমি জানি. আমি ভাল. আমি ভাল. আমি ভাল. আমি ভাল. আমি জানি. আমি জানি. আমি জানি. আমি ভাল. আমি জানি. আমি জানি. আমি জানি. আমি জানি. আমি জানি. আমি জানি. আমি কি. আমি তোমার জন্য. আমি তোমার জন্য ধন্যবাদ. আমি জানি না. আমি জানি তুমি এটা আমার বাবা. আমি কি. আমি তোমার জন্য ধন্যবাদ. আমি কি. আমি তোমার জন্য ধন্যবাদ. আমি কি. পালিয়ে পালিয়ে যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏رُبَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُمْ ‏ ‏خَرَجُوا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَنَزَلُوا رُفَقَاءَ رُفْقَةٌ مَعَ فُلَانٍ وَرُفْقَةٌ مَعَ فُلَانٍ ‏ ‏قَالَ ‏ ‏فَنَزَلْتُ فِي رُفْقَةِ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَكَانَ مَعَنَا أَعْرَابِيٌّ مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏فَنَزَلْنَا بِأَهْلِ بَيْتٍ مِنْ ‏ ‏الْأَعْرَابِ ‏ ‏وَفِيهِمْ امْرَأَةٌ حَامِلٌ فَقَالَ لَهَا الْأَعْرَابِيُّ أَيَسُرُّكِ أَنْ تَلِدِي غُلَامًا إِنْ أَعْطَيْتِنِي شَاةً وَلَدْتِ غُلَامًا فَأَعْطَتْهُ شَاةً ‏ ‏وَسَجَعَ ‏ ‏لَهَا ‏ ‏أَسَاجِيعَ ‏ ‏قَالَ فَذَبَحَ الشَّاةَ فَلَمَّا جَلَسَ الْقَوْمُ يَأْكُلُونَ قَالَ رَجُلٌ أَتَدْرُونَ مَا هَذِهِ الشَّاةُ فَأَخْبَرَهُمْ قَالَ فَرَأَيْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏مُتَبَرِّيًا ‏ ‏مُسْتَنْبِلًا ‏ ‏مُتَقَيِّئًا ‏","","",""],[11057,11057,"","আমি যখন সেখানে পৌঁছাই, তখন আমার বাবা - মা আমাকে জিজ্ঞেস করেছিল, “তুমি কি সত্যিই আমাকে সাহায্য করবে? ” আমি তাকে কখনো বলতে শুনিনি যে, ঈশ্বর তার জন্য প্রার্থনা করছেন এবং তিনি তৃতীয় বারের মতো তাকে দেখতে চান না । শর্ট।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏حَدَّثَنِي ‏ ‏قَزَعَةُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَعْجَبَنِي فَدَنَوْتُ مِنْهُ وَكَانَ فِي نَفْسِي حَتَّى أَتَيْتُهُ فَقُلْتُ أَنْتَ سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَغَضِبَ غَضَبًا شَدِيدًا قَالَ فَأُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَمْ أَسْمَعْهُ نَعَمْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تُشَدُّ الرِّحَالُ إِلَّا إِلَى ثَلَاثَةِ مَسَاجِدَ ‏ ‏مَسْجِدِي ‏ ‏هَذَا ‏ ‏وَالْمَسْجِدِ الْحَرَامِ ‏ ‏وَالْمَسْجِدِ الْأَقْصَى ‏","","",""],[11058,11058,"","আমি ঈশ্বরের কাছে প্রার্থনা করব তার কাছে আছে আর সে বলবে তুমি তাকে তার সাথে ক্ষমা করবে না.","‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تُسَافِرُ الْمَرْأَةُ إِلَّا مَعَ زَوْجِهَا أَوْ ذِي مَحْرَمٍ مِنْهَا ‏","","",""],[11059,11059,"","আমি ঈশ্বরের কাছে প্রার্থনা করব তার কাছে আছে আর সে কোন সানাম বলবে না, সে দিন তার কাছে পরিষ্কার আর বধিরদের কাছে।","‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا صِيَامَ فِي يَوْمَيْنِ يَوْمِ الْأَضْحَى وَيَوْمِ الْفِطْرِ مِنْ رَمَضَانَ ‏","","",""],[11060,11060,"","সে শুনতে পাবে যে, দুই প্রার্থনা গাছ পর্যন্ত পৌঁছে গেলে... ... সূর্যকে তুলে নেওয়া হবে এবং সূর্য শক্তি সূর্যের উপরে চলে আসবে।","‏ ‏وَسَمِعْتُهُ يَقُولُ ‏ ‏لَا صَلَاةَ بَعْدَ صَلَاتَيْنِ صَلَاةِ الْفَجْرِ حَتَّى تَطْلُعَ الشَّمْسُ وَصَلَاةِ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ ‏","","",""],[11061,11061,"","হামাদ বিনের প্রতি ভালোবাসা আমরা কথা বলেছি আমরা লর্ডের হাতে কথা বলেছি। আমার বিতাড়িত বন্ধু আমার বাবার সুখী দাসের জন্য বেঁচে আছে। তার শান্তি রক্ষা কর, আমি ঈশ্বরের নামে শপথ করে বলছি, আমার মায়ের কাছে পৃথিবীর অনেক দূরের সদস্য পাওয়া যাবে, সে পানি পাবে এবং সে বলবে সে অসুস্থ গান গেয়ে মা, তাই আমার একটা দরকার। তিনি বলেছিলেন, একজন মানুষ বলবে যে আমরা তাকে হারানোর কথা বলব। সবচেয়ে দুঃখের কথা বলতে হবে যে, যদি আমি বের হই, তাহলে তার স্ত্রী আছে কিনা। আমি তাকে সতর্ক করে দিচ্ছি আমি বধির হব। তারা কখনো দুই বছর বা দুই বছর পর তার কোন সাহায্য করবে না, না হলে সে আবার সাহায্য করবে। আমি শুধু এটা শুনতে খুশি যে আমি চেষ্টা করছি। আমার বাবার সাথে দেখা করার জন্য আমার অনেক কিছু আছে, তার সুখী গাল থাকার জন্য, তার আনন্দের সাথে আমার বাবার সাথে দেখা করার জন্য, যেমন তার একটা গামছা আছে। সাধুরা বলবে এর সাথে কোন সম্পর্ক নেই।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ زِيَادٍ الْمِعْوَلِيُّ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ بَشِيرٍ الْمُزَنِىِّ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُبَشِّرُكُمْ ‏ ‏بِالْمَهْدِىِّ ‏ ‏يُبْعَثُ فِي أُمَّتِي عَلَى اخْتِلَافٍ مِنْ النَّاسِ وَزَلَازِلَ فَيَمْلَأُ الْأَرْضَ قِسْطًا وَعَدْلًا كَمَا مُلِئَتْ ‏ ‏جَوْرًا ‏ ‏وَظُلْمًا ‏ ‏وَيَرْضَى عَنْهُ سَاكِنُ السَّمَاءِ وَسَاكِنُ الْأَرْضِ وَيَمْلَأُ اللَّهُ قُلُوبَ أُمَّةِ ‏ ‏مُحَمَّدٍ ‏ ‏غِنًى فَلَا يَحْتَاجُ أَحَدٌ إِلَى أَحَدٍ فَيُنَادِي مُنَادٍ مَنْ لَهُ فِي الْمَالِ حَاجَةٌ قَالَ فَيَقُومُ رَجُلٌ فَيَقُولُ أَنَا فَيُقَالُ لَهُ ائْتِ ‏ ‏السَّادِنَ ‏ ‏يَعْنِي الْخَازِنَ ‏ ‏فَقُلْ لَهُ قَالَ لَكَ ‏ ‏الْمَهْدِيُّ ‏ ‏أَعْطِنِي قَالَ فَيَأْتِي ‏ ‏السَّادِنَ ‏ ‏فَيَقُولُ لَهُ فَيُقَالُ لَهُ ‏ ‏احْتَثِي ‏ ‏فَيَحْتَثِي ‏ ‏فَإِذَا ‏ ‏أَحْرَزَهُ ‏ ‏قَالَ كُنْتُ أَجْشَعَ أُمَّةِ ‏ ‏مُحَمَّدٍ ‏ ‏نَفْسًا ‏ ‏أَوَعَجَزَ ‏ ‏عَنِّي مَا ‏ ‏وَسِعَهُمْ ‏ ‏قَالَ فَيَمْكُثُ سَبْعَ سِنِينَ أَوْ ثَمَانِ سِنِينَ أَوْ تِسْعَ سِنِينَ ثُمَّ لَا خَيْرَ فِي الْحَيَاةِ ‏ ‏أَوْ فِي الْعَيْشِ ‏ ‏بَعْدَهُ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ زِيَادٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ بَشِيرٍ الْمُزَنِيِّ ‏ ‏وَكَانَ بَكَّاءً عِنْدَ الذِّكْرِ شُجَاعًا عِنْدَ اللِّقَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏مِثْلَهُ وَزَادَ فِيهِ فَيَنْدَمُ فَيَأْتِي بِهِ ‏ ‏السَّادِنَ ‏ ‏فَيَقُولُ لَهُ لَا نَقْبَلُ شَيْئًا أَعْطَيْنَاهُ ‏","","",""],[11062,11062,"","আমি আমাকে খুন করার কথা বলেছিলাম, কিন্তু আমি আমার চেয়ে ভালো কিছুর চেষ্টা করছি, সে বলল সে আত্মসমর্পণ করবে এবং সে অপরাধ ভুলে যাবে না, আর আমি আমাকে ক্ষমা করব না। তাকে আশীর্বাদ করলাম এবং তার হাত বলল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنِي ‏ ‏فُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏مَوْلَى ‏ ‏بَنِي عَنْزٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَنْ يَدْخُلَ الْجَنَّةَ أَحَدٌ إِلَّا بِرَحْمَةِ اللَّهِ قُلْنَا يَا رَسُولَ اللَّهِ وَلَا أَنْتَ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِيَ ‏ ‏اللَّهُ بِرَحْمَتِهِ وَقَالَ بِيَدِهِ فَوْقَ رَأْسِهِ ‏","","",""],[11063,11063,"","আমরা এমন একজনের সাথে কথা বলেছি যার দেখা হয়েছে। ঈশ্বরের কাছে প্রার্থনা করা উচিত ছিল যেন তিনি শান্তি স্বীকার করেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِزْرَةُ ‏ ‏الْمُسْلِمِ إِلَى نِصْفِ السَّاقِ فَمَا كَانَ إِلَى الْكَعْبِ فَلَا بَأْسَ وَمَا تَحْتَ الْكَعْبِ فَفِي النَّارِ ‏","","",""],[11064,11064,"","আমরা একটা হাত দিয়ে কথা বলেছি যেটা আমরা পৃথিবীর সেরাদের সাথে করেছি, হয়তো তারা আমাদেরকে শত শত বছর ধরে পড়তে পারবে আর আমরা অন্য উপায় খুঁজে বের করব। সেই মোটা পাখি যেভাবে ধূসর রঙের স্টক হতে যাচ্ছে, তা হল, সেই খাদ্য কতই না মূল্যবান!","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ نَجِيحٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ الْفَقِيرِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏إِنَّ مِنَّا رِجَالًا هُمْ أَقْرَؤُنَا لِلْقُرْآنِ وَأَكْثَرُنَا صَلَاةً ‏ ‏وَأَوْصَلُنَا لِلرَّحِمِ وَأَكْثَرُنَا صَوْمًا خَرَجُوا عَلَيْنَا بِأَسْيَافِهِمْ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَخْرُجُ قَوْمٌ يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏حَنَاجِرَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏","","",""],[11065,11065,"","আমরা একজন দাসের সাথে কথা বলেছি যে আমার বাবার সাথে দুনিয়ার দিকে বসবাস করছে, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তার কাছে প্রার্থনা করেছেন যে ছেলে তাকে খুঁজে পাবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي عَلَى حَصِيرٍ وَيَسْجُدُ عَلَيْهِ ‏","","",""],[11066,11066,"","আমরা আমার বাবার সঙ্গে কথা বলেছিলাম, একজন ভাল ছেলে বলেছিলেন যে তিনি ঈশ্বরের কাছে যাচ্ছেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْرِدُوا ‏ ‏بِالظُّهْرِ فِي الْحَرِّ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَوْحِ ‏ ‏جَهَنَّمَ ‏ ‏هَكَذَا ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏مِنْ ‏ ‏فَوْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[11067,11067,"","আমরা হাত দিয়ে কথা বলেছি যে আমার বাবাকে সাহায্য করার অভ্যাস দিয়ে। তারা বলে নি যে, তারা বলে নি যে, তারা বলে নি যে, তারা বলে নি যে তারা এই কথা বলেনি যে, তারা এমনটি বলেনি যে তারা বলেনি । আমরা ভয় পেয়েছিলাম, তাই সে বলে কে এটা বলছে আর তাই বলে কি সেটা।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلَكَ ‏ ‏الْمُثْرُونَ ‏ ‏قَالُوا إِلَّا مَنْ قَالَ هَلَكَ ‏ ‏الْمُثْرُونَ ‏ ‏قَالُوا إِلَّا مَنْ قَالَ هَلَكَ ‏ ‏الْمُثْرُونَ ‏ ‏قَالَ حَتَّى خِفْنَا أَنْ يَكُونَ قَدْ وَجَبَتْ قَالَ إِلَّا مَنْ قَالَ هَكَذَا وَهَكَذَا وَهَكَذَا وَقَلِيلٌ مَا هُمْ ‏","","",""],[11068,11068,"","আমরা একটা হাত দিয়ে এই বাপ্তাইজিত হয়েছি, আমরা কথা শুনেছি সে কিভাবে তার বাবা বা বাবার কাছ থেকে এলো। শত্রু প্রথমে পরিকল্পনা শুরু করবে। প্রার্থনা করে সে তাকে মেরে ফেলবে। সে চলে গেছে এবং প্রার্থনা করার আগে সে বলেছে, সে খুশি হয়েছে। তাকে দেখে তিনি তার প্রভুর জন্য গান গাইতে পারেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ رَجَاءٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَوَّلُ مَنْ أَخْرَجَ الْمِنْبَرَ يَوْمَ الْعِيدِ ‏ ‏مَرْوَانُ ‏ ‏وَأَوَّلُ مَنْ بَدَأَ بِالْخُطْبَةِ قَبْلَ الصَّلَاةِ فَقَامَ رَجُلٌ فَقَالَ يَا ‏ ‏مَرْوَانُ ‏ ‏خَالَفْتَ السُّنَّةَ أَخْرَجْتَ الْمِنْبَرَ وَلَمْ يَكُ يُخْرَجُ وَبَدَأْتَ بِالْخُطْبَةِ قَبْلَ الصَّلَاةِ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَنْ هَذَا قَالُوا فُلَانُ بْنُ فُلَانٍ قَالَ أَمَّا هَذَا فَقَدْ قَضَى مَا عَلَيْهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ رَأَى مُنْكَرًا فَإِنْ ‏ ‏اسْتَطَاعَ أَنْ يُغَيِّرَهُ بِيَدِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ ‏","","",""],[11069,11069,"","আমরা একটা দাসের সাথে কথা বলেছি, যে আমার বাবার ছেলের ব্যাপারে কথা বলেছি, ঈশ্বর তাকে প্রার্থনা করেছেন আর তিনি আমার কাছে প্রার্থনা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي ‏ ‏مُتَوَشِّحًا ‏","","",""],[11070,11070,"","আমরা একটা ছেলেকে সাহায্য করার কথা বলেছিলাম যে কিভাবে একজন ভাইকে সাহায্য করতে হয়। আর এখন ছেলেটা তার জন্য প্রার্থনা করছে, সকালে তাকে তোমার কাছে হস্তান্তর করা হয়েছে, সে আমার হাত তুলে নিয়েছে এবং সে তার হাত তুলে নিয়েছে। তুমি তাকে নরকের দিকে ঠেলে দিয়েছ, তুমি তাকে ভবিষ্যৎ বাণী থেকে তার কাছে প্রার্থনা করতে বলেছিলে... ...আর তার গর্ভে আত্মসমর্পণ করবে... ...আর তাকে বলে দেবে তুমি এমন একজন নারীর মত হবে না যার সাথে তুমি এমন হবে যে আছে কেউ কেউ বেঁচে থাকার জন্য তার বোকামি বিক্রি করে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏قَالَ ‏ ‏بَلَغَ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَأْثُرُ حَدِيثًا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الصَّرْفِ ‏ ‏فَأَخَذَ يَدِي فَذَهَبْتُ أَنَا وَهُوَ وَالرَّجُلُ فَقَالَ مَا حَدِيثٌ بَلَغَنِي عَنْكَ تَأْثُرُهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الصَّرْفِ ‏ ‏فَقَالَ سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَبِيعُوا الذَّهَبَ بِالذَّهَبِ إِلَّا مِثْلًا بِمِثْلٍ وَلَا الْفِضَّةَ بِالْفِضَّةِ إِلَّا مِثْلًا بِمِثْلٍ وَلَا تُفَضِّلُوا بَعْضَهَا عَلَى بَعْضٍ وَلَا تَبِيعُوا مِنْهَا ‏ ‏غَائِبًا ‏ ‏بِنَاجِزٍ ‏","","",""],[11071,11071,"","আমরা আনন্দের সাথে কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ جَنِينِ النَّاقَةِ وَالْبَقَرَةِ فَقَالَ ‏ ‏إِنْ شِئْتُمْ فَكُلُوهُ فَإِنَّ ‏ ‏ذَكَاتَهُ ‏ ‏ذَكَاةُ ‏ ‏أُمِّهِ ‏","","",""],[11072,11072,"","ঈশ্বর যদি গরম না হয়, তা হলে প্রার্থনা করলে তা শান্তি নিয়ে আসবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[11073,11073,"","আমি আমার বাবার কথা বলেছি, সে যে স্বপ্নের কথা শুনেছে তাতে খুশি, আমি বলেছি যে নরকের আগুনটা তারা বন্ধ হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏شِدَّةُ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ ‏","","",""],[11074,11074,"","আমি তাকে বলেছিলাম যে, বাবা আমার সঙ্গে লড়াই করছেন । তার কথা শোনে নি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏التَّيْمِيِّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمْنَعَنَّ أَحَدَكُمْ ‏ ‏هَيْبَةُ ‏ ‏النَّاسِ أَنْ يَتَكَلَّمَ بِحَقٍّ إِذَا رَآهُ أَوْ شَهِدَهُ أَوْ سَمِعَهُ ‏ ‏فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَدِدْتُ أَنِّي لَمْ أَكُنْ سَمِعْتُهُ ‏ ‏و قَالَ ‏ ‏أَبُو نَضْرَةَ ‏ ‏وَدِدْتُ أَنِّي لَمْ أَكُنْ سَمِعْتُهُ ‏","","",""],[11075,11075,"","আমরা কথা বলেছি তিনি কিছু সময় জন্য জীবন জন্য ... ...তিনি আমার হাত পেতে সাহায্য করবেন. তিনি ঈশ্বরের কাছে প্রার্থনা করতে বলেছেন তিনি এটা উদ্ধার করতে হবে এবং যদি আপনি ফিরে যান তাহলে তাকে একটি পটে যাওয়া হবে আমি জানি আমি কত কিছু পাব, সে বলল তুমি হয়তো বলবে তুমি মিথ্যা বলেছ আর এটা ভাঙ্গার জন্য একটা আত্মা খুজে পেয়েছ. ঈশ্বরকে খুশি করে আমি তার কথা বলি । আমি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عِيَاضٍ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏قَالَ أَحَدُنَا ‏ ‏يُصَلِّي لَا يَدْرِي كَمْ صَلَّى قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فَلَمْ يَدْرِ كَمْ صَلَّى فَلْيَسْجُدْ سَجْدَتَيْنِ فَإِنْ أَتَاهُ الشَّيْطَانُ فَقَالَ إِنَّكَ قَدْ ‏ ‏أَحْدَثْتَ ‏ ‏فَلْيَقُلْ كَذَبْتَ إِلَّا مَا وَجَدَ رِيحًا بِأَنْفِهِ أَوْ صَوْتًا بِأُذُنِهِ ‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عِيَاضٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِذَا صَلَّى أَحَدُكُمْ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عِيَاضٍ ‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عِيَاضُ بْنُ هِلَالٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[11076,11076,"","আমি খুশি যে বাবা বলেছিলেন যে একজন মানুষ ঈশ্বরের কাছে প্রার্থনা করেছে যেন আমি আমার মা আর আমি চলে যাই। আমি এটা নিয়ে কথা বলি। ঐ জানোয়ার আর আমি মাটিতে যাব, তুমি চাও।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو رِفَاعَةَ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ ‏ ‏قَالَ ‏ ‏إِنَّ رَجُلًا قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِي أَمَةً وَأَنَا ‏ ‏أَعْزِلُ ‏ ‏عَنْهَا وَإِنِّي أَكْرَهُ أَنْ تَحْمِلَ وَإِنَّ ‏ ‏الْيَهُودَ ‏ ‏تَزْعُمُ أَنَّهَا ‏ ‏الْمَوْءُودَةُ ‏ ‏الصُّغْرَى قَالَ كَذَبَتْ ‏ ‏يَهُودُ ‏ ‏إِذَا أَرَادَ اللَّهُ أَنْ يَخْلُقَهُ لَمْ تَسْتَطِعْ أَنْ تَرُدَّهُ ‏","","",""],[11077,11077,"","আমি আমার বাবার খুশির কথা বলেছিলাম যে তিনি আমাকে হত্যা করার চেষ্টা করছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْعَزْلِ ‏ ‏أَنْتَ تَخْلُقُهُ أَنْتَ تَرْزُقُهُ ‏ ‏أَقِرَّهُ ‏ ‏قَرَارَهُ ‏ ‏فَإِنَّمَا ذَلِكَ الْقَدَرُ ‏","","",""],[11078,11078,"","ঈশ্বর এটা বলার প্রয়োজন নেই যে, এটা এতই নোংরা ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏وَحَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏ثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ النِّدَاءَ فَقُولُوا مِثْلَ مَا يَقُولُ الْمُؤَذِّنُ ‏","","",""],[11079,11079,"","আমি দুনিয়া সম্পর্কে কথা বলেছি আমার বাবা আপনাকে সেই ভবিষ্যদ্বাণী সম্পর্কে খুশির কথা বলেছেন। সূর্যটা বন্ধ না হওয়া পর্যন্ত","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصُومُوا يَوْمَيْنِ وَلَا تُصَلُّوا صَلَاتَيْنِ وَلَا تَصُومُوا يَوْمَ الْفِطْرِ وَلَا يَوْمَ الْأَضْحَى وَلَا تُصَلُّوا بَعْدَ الْفَجْرِ حَتَّى تَطْلُعَ الشَّمْسُ وَلَا بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ ‏","","",""],[11080,11080,"","আর তুমি তাকে ভালোবাসার সাথে পরবর্তী তিনদিন কাটাতে পারবে না।","‏ ‏وَلَا تُسَافِرُ الْمَرْأَةُ ثَلَاثًا إِلَّا وَمَعَهَا مَحْرَمٌ ‏","","",""],[11081,11081,"","আর তুমি মানুষটিকে খুঁজে পাওনি, সেই গৌরবান্বিত মৃত্যুটা খুজে পাও।","‏ ‏وَلَا تُشَدُّ الرِّحَالُ إِلَّا إِلَى ثَلَاثَةِ مَسَاجِدَ ‏ ‏مَسْجِدِ الْحَرَامِ ‏ ‏وَمَسْجِدِي ‏ ‏وَمَسْجِدِ بَيْتِ الْمَقْدِسِ ‏","","",""],[11082,11082,"","আমরা আমার মাতাল মাথাওয়ালা মানুষ সম্পর্কে কথা বলেছি। আমার বাবা তাকে মৃত অবস্থায় দেখে খুশি। মৃত হয়ে গিয়ে একে অপরকে কবর দিতে বলা হয়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏حَدَّثَنِي ‏ ‏عَامِرٌ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَمَرْوَانُ ‏ ‏جَالِسَيْنِ فَمُرَّ عَلَيْهِمَا بِجَنَازَةٍ فَقَامَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَقَالَ ‏ ‏مَرْوَانُ ‏ ‏اجْلِسْ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فَقَامَ ‏ ‏مَرْوَانُ ‏ ‏وَقَالَ ‏ ‏وَكِيعٌ ‏ ‏مَرَّتْ بِهِ جَنَازَةٌ فَقَامَ ‏","","",""],[11083,11083,"","আমরা ঈশ্বরের সর্বোচ্চ কথা বলেছি, কিন্তু আমি তাকে সাহায্য করার চেষ্টা করছি। সে বলল যে, ঈশ্বর তাকে উদ্ধার করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عِيَاضَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَخْرُجُ يَوْمَ الْفِطْرِ ‏ ‏يُصَلِّي ‏ ‏تَيْنِكَ ‏ ‏الرَّكْعَتَيْنِ ‏","","",""],[11084,11084,"","আমরা একজন যাজকের বালতির কথা বলেছিলাম যে আমার সাথে একজন সুখী পিতার কথা বলেছে, আমি শত্রুর রাজত্ব ছেড়ে দেব। সে বলল, আমি তাকে চিনি না যে তার শরীর গরম আর পরিষ্কার আর তার সঙ্গে এমন কিছু ঘটেছিল, যার জন্য তার একটা প্রয়োজন ছিল । কিছু কথা বলতে চাই বা না করতে চাই না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ قَيْسٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عِيَاضٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ يَوْمَ الْعِيدِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏لَا أَعْلَمُهُ إِلَّا قَالَ الْفِطْرِ وَالْأَضْحَى ‏ ‏فَيُصَلِّي بِالنَّاسِ رَكْعَتَيْنِ فَيَقُومُ قَائِمًا فَيَسْتَقْبِلُ النَّاسَ بِوَجْهِهِ وَيَقُولُ ‏ ‏تَصَدَّقُوا فَكَانَ أَكْثَرَ مَنْ يَتَصَدَّقُ النِّسَاءُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏بِالْخَاتَمِ ‏ ‏وَالْقُرْطِ ‏ ‏وَالشَّيْءِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏فَإِنْ كَانَتْ لَهُ حَاجَةٌ أَوْ أَرَادَ أَنْ يَضَعَ بَعْثًا تَكَلَّمَ وَإِلَّا انْصَرَفَ ‏","","",""],[11085,11085,"","আমরা কথা দিয়েছি বধিররা আমার বাবার সাথে কথা বলেছে। সে এমন একজন যে বলেছে যে তাকে ঈশ্বরের কাছে পাঠানো উচিৎ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَفَّانُ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي عِيسَى الْأُسْوَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏زَجَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الشُّرْبِ قَائِمًا ‏","","",""],[11086,11086,"","আমরা একে অপরের সাথে কথা বলেছি, কিন্তু আমরা আমার বাবাকে তার কৌশলের জালে ফেলার ব্যাপারে আগ্রহী। অন্ত্যেষ্টিক্রিয়ার সময় কিছু সময় বলে যে আমি খুব গরম হয়ে গেছি যে আমি ঈশ্বরের কাছে প্রার্থনা করতে পেরে খুশি। আমি ঠিক আছি.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏فُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَأَلَهُ رَجُلٌ عَنْ الْغُسْلِ مِنْ الْجَنَابَةِ فَقَالَ ‏ ‏ثَلَاثًا فَقَالَ إِنِّي كَثِيرُ الشَّعَرِ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثَرَ شَعَرًا مِنْكَ وَأَطْيَبَ ‏","","",""],[11087,11087,"","আমরা একে অপরের বাবার সাথে কথা বলেছি আমার বাবার খুশির কথা বলতে। ঈশ্বর আদেশ দিয়েছেন তাকে তার কাজে সমর্পণ করতে আর তোমাকে সেবা করতে। তাদের দেরি করে দাও.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ الْعَبْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَصْحَابِهِ تَأَخُّرًا فَقَالَ ‏ ‏تَقَدَّمُوا فَأْتَمُّوا بِي وَلْيَأْتَمَّ بِكُمْ مَنْ بَعْدَكُمْ وَلَا يَزَالُ قَوْمٌ يَتَأَخَّرُونَ حَتَّى يُؤَخِّرَهُمْ اللَّهُ ‏","","",""],[11088,11088,"","ঈশ্বরের মঙ্গলভাবের জন্য আমরা ঈশ্বরের কাছে ক্ষমা চাই, যে তার চাচার জন্য চলে গেছে, সে আমার বাবার সাথে খুশি ছিল এবং সে প্রভুর বার্তাবাহকের সাথে ছিল। ওর মুখের কথা বলে বা সে ছেলেটাকে পেয়ে যাবে, বাবা বলেছিল যদি সে তোমাকে জানতে চায়, সে সবসময় প্রার্থনা করে না, যতক্ষণ না সে এটা থেকে বের হয়।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ مَوْهَبٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَنْ ‏ ‏مَوْلًى لِأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ ‏ ‏كَانَ مَعَ ‏ ‏أَبِي سَعِيدٍ ‏ ‏وَهُوَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَدَخَلُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَأَى رَجُلًا جَالِسًا وَسَطَ الْمَسْجِدِ مُشَبِّكًا بَيْنَ أَصَابِعِهِ يُحَدِّثُ نَفْسَهُ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ ‏ ‏يَفْطِنْ ‏ ‏قَالَ فَالْتَفَتَ إِلَى ‏ ‏أَبِي سَعِيدٍ ‏ ‏فَقَالَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فَلَا يُشَبِّكَنَّ بَيْنَ أَصَابِعِهِ فَإِنَّ التَّشْبِيكَ مِنْ الشَّيْطَانِ فَإِنَّ أَحَدَكُمْ لَا يَزَالُ فِي صَلَاةٍ مَا دَامَ فِي الْمَسْجِدِ حَتَّى يَخْرُجَ مِنْهُ ‏","","",""],[11089,11089,"","আমি আমার বাবার জীবনের জন্য আপনার বাবার অনেক অভিজ্ঞতার কথা বলেছি, তিনি তার জন্য প্রার্থনা করেছিলেন এবং যদি আমি বিচারকের কাছে আসি, তাহলে তিনি আত্মসমর্পণ করতেন তার প্রার্থনায় শয়তান তোমাকে মেরে ফেলবে, শ্বাস নিতে পারবে না অথবা কান দিয়ে তার কণ্ঠ শুনবো না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ أَحَدَكُمْ الشَّيْطَانُ فِي صَلَاتِهِ فَقَالَ إِنَّكَ قَدْ ‏ ‏أَحْدَثْتَ ‏ ‏فَلْيَقُلْ كَذَبْتَ مَا لَمْ يَجِدْ رِيحًا بِأَنْفِهِ أَوْ يَسْمَعْ صَوْتًا بِأُذُنِهِ ‏","","",""],[11090,11090,"","আমরা গত দুই বছর ধরে একজন প্রত্যক্ষদর্শীর সাথে অথবা অনির্বাণে ভ্রমণ করার জন্য একটি চমক হিসেবে অ্যাটলাসের কথা বলেছি। হয়, আল্লাহের কথা শুনে খুশি হই, আর আমি এমন নই যে এটা নিয়ে কখনো স্বপ্ন দেখেও না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏أَوَّلُ مَنْ بَدَأَ بِالْخُطْبَةِ يَوْمَ عِيدٍ قَبْلَ الصَّلَاةِ ‏ ‏مَرْوَانُ بْنُ الْحَكَمِ ‏ ‏فَقَامَ إِلَيْهِ رَجُلٌ فَقَالَ الصَّلَاةُ قَبْلَ الْخُطْبَةِ فَقَالَ ‏ ‏مَرْوَانُ ‏ ‏تُرِكَ مَا هُنَالِكَ أَبَا فُلَانٍ فَقَالَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏أَمَّا هَذَا فَقَدْ قَضَى مَا عَلَيْهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ ‏","","",""],[11091,11091,"","আমরা আমার বাবা আর বাবার ব্যাপারে কথা বলেছি আর আমরা প্রেম নিয়ে কথা বলেছি। তিন দিন তার বাবা বা ভাই, তার ছেলে বা ছেলের সাথে কাটালে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُسَافِرُ الْمَرْأَةُ سَفَرَ ثَلَاثَةِ أَيَّامٍ فَصَاعِدًا إِلَّا مَعَ أَبِيهَا أَوْ أَخِيهَا أَوْ ابْنِهَا أَوْ زَوْجِهَا أَوْ مَعَ ذِي مَحْرَمٍ ‏","","",""],[11092,11092,"","আমরা বাবার প্রতারণার কথা বলেছি, ঈশ্বরের কাছে আমি কথা বলেছি, আমি কখনো তোমাকে জিততে দেব না যদি আমি তোমার একজনকে হারিয়ে ফেলি। আমরা এমন আবেগ নিয়ে কথা বলি যা নিয়ে এসেছে। আমার বাবার সুখী হওয়ার রীতি নিয়ে, ঈশ্বর আমাদের সাথে কথা বলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسُبُّوا أَصْحَابِي فَوَالَّذِي نَفْسِي بِيَدِهِ لَوْ أَنَّ أَحَدَكُمْ أَنْفَقَ مِثْلَ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا مَا أَدْرَكَ مُدَّ أَحَدِهِمْ وَلَا نَصِيفَهُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏مِثْلَهُ ‏","","",""],[11093,11093,"","ঈশ্বরের কাছে প্রেরিত হওয়াকে বলা হয় যেন তিনি তার কাছে আসেন এবং আপনার একজন কাছে তা সমর্পণ করেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏حَبَّانَ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فِي الثَّوْبِ الْوَاحِدِ فَلْيَجْعَلْ طَرَفَيْهِ عَلَى عَاتِقَيْهِ ‏","","",""],[11094,11094,"","আমার গুজবগুলো ব্যবহার করার জন্য আমার বাবা তাকে শান্তি ও মন দিয়ে প্রভাবিত করেছে । আগুনের আলো.","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ ‏ ‏حَيْوَةُ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ الْهَادِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ خَبَّابٍ ‏ ‏حَدَّثَهُمْ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذُكِرَ عِنْدَهُ عَمُّهُ ‏ ‏أَبُو طَالِبٍ ‏ ‏فَقَالَ ‏ ‏لَعَلَّهُ أَنْ تَنْفَعَهُ ‏ ‏شَفَاعَتِي ‏ ‏يَوْمَ الْقِيَامَةِ فَيُجْعَلَ فِي ‏ ‏ضَحْضَاحٍ ‏ ‏مِنْ النَّارِ يَبْلُغُ كَعْبَيْهِ يَغْلِي مِنْهُ دِمَاغُهُ ‏","","",""],[11095,11095,"","আমরা জ্ঞান নিয়ে জানার চেষ্টা করেছি যে ছেলে আমাকে বলল যে ঈশ্বরের ছেলে আমাকে মেরে ফেলার চেষ্টা করেছে এবং খুন করার চেষ্টা করেছে। আর সে বলবে টাকনির অনুগ্রহ হচ্ছে টাক-এর টাক-ক্রেসের টাক-এর টাক-এর টাকড়া আর ১০ ডিগ্রি।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ ‏ ‏حَيْوَةُ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَلَاةُ الْجَمَاعَةِ تَفْضُلُ صَلَاةَ ‏ ‏الْفَذِّ ‏ ‏بِخَمْسٍ وَعِشْرِينَ دَرَجَةً ‏","","",""],[11096,11096,"","আর এই নামই সে ঈশ্বরকে তার কাছে রাখতে বলেছে... ...আর সে বলেছে কে দেখেছে.","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ رَآنِي فَقَدْ رَآنِي الْحَقَّ فَإِنَّ الشَّيْطَانَ لَا يَتَكَوَّنُ بِي ‏","","",""],[11097,11097,"","এটা ঈশ্বরের চাওয়া... ...যে আমার বাবা এটা মনে রাখতে পেরে খুশি হবে, তুমি তাকে ডানা বলে ডাক, সে ঘুমাবে।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏ذَكَرَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ تُصِيبُهُ الْجَنَابَةُ فَيُرِيدُ أَنْ يَنَامَ ‏ ‏فَأَمَرَهُ أَنْ يَتَوَضَّأَ ثُمَّ يَنَامَ ‏","","",""],[11098,11098,"","আমরা আপনার অভিজ্ঞতার কথা বলেছিলাম যে, হয়তো ইশ্বর আপনার ছেলেকে বলতে চেয়েছেন, আমি বেনকে একটা গোপন কথা বলেছি... ...যে তার বাবার কাছে প্রার্থনা করছে, সে তার বাবার কাছে প্রার্থনা করছে, যে তার নখে পেরেক বেঁধে দিয়েছে। মূর্তিটা জানতো তার প্রতিমাগুলো কি ধরে রাখতে হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ قُرَيْطٍ ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ يَسَارٍ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ صَامَ رَمَضَانَ وَعَرَفَ حُدُودَهُ وَتَحَفَّظَ مِمَّا كَانَ يَنْبَغِي لَهُ أَنْ يَتَحَفَّظَ فِيهِ كَفَّرَ ‏ ‏مَا كَانَ ‏ ‏قَبْلَهُ ‏","","",""],[11099,11099,"","আমরা কিছু জিনিস নিয়ে পালাতে চেষ্টা করার কথা বলেছিলাম । আর আমি মানুষকে মৃত্যুর দিকে ঠেলে দিচ্ছি, আর আমি তাদের দেখতে পাচ্ছি সে একজন মহান মিথ্যাবাদী।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏الْفُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَبَّ النَّاسِ إِلَى اللَّهِ يَوْمَ الْقِيَامَةِ وَأَقْرَبَهُمْ مِنْهُ مَجْلِسًا إِمَامٌ عَادِلٌ وَإِنَّ أَبْغَضَ النَّاسِ إِلَى اللَّهِ يَوْمَ الْقِيَامَةِ وَأَشَدَّهُمْ عَذَابًا إِمَامٌ ‏ ‏جَائِرٌ ‏","","",""],[11100,11100,"","আমার বাবা আমার কাছে অমর, ঈশ্বরের প্রভু, তার জন্য তার নিজের জন্য এবং শান্তির জন্য । আপনার ভাই - বোনদের সঙ্গে কথা বলার সময় আপনার বিশ্বাস অথবা আপনার ভাল ইচ্ছাগুলো সুরক্ষিত থাকে ।","‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ بْنُ بِشْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏أَبِي سُلَيْمَانَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الْمُؤْمِنِ وَمَثَلُ الْإِيمَانِ كَمَثَلِ الْفَرَسِ فِي ‏ ‏آخِيَّتِهِ ‏ ‏يَجُولُ ثُمَّ يَرْجِعُ إِلَى ‏ ‏آخِيَّتِهِ ‏ ‏وَإِنَّ الْمُؤْمِنَ ‏ ‏يَسْهُو ثُمَّ يَرْجِعُ إِلَى الْإِيمَانِ فَأَطْعِمُوا طَعَامَكُمْ الْأَتْقِيَاءَ وَأَوْلُوا مَعْرُوفَكُمْ الْمُؤْمِنِينَ ‏ ‏حَدَّثَنَاه ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِئُ ‏ ‏وَهَذَا أَتَمُّ ‏","","",""],[11101,11101,"","ঈশ্বর আমাদের সর্বোচ্চ চেষ্টা করেছেন, আমাদের কাছে আমার ছেলে কখনো আমার সাথে কথা বলেনি কিন্তু আমার বাবা কখনোই দাস ছিলেন না। আমার বাবা আমার বাবার সুখী গাল নিয়ে গর্বিত যে আমার বাবা প্রার্থনা করেছেন। তার কাছে একটা স্বপ্ন আছে, কখনো সে জানতে বলেছে, তাকে কাকে মারতে বলা হয়েছে, আমি বের হবার ভাড়া নিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏الْمَهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ بَعْثًا إِلَى ‏ ‏بَنِي لِحْيَانَ ‏ ‏قَالَ ‏ ‏يَعْنِي لِيَنْبَعِثْ مِنْ كُلِّ رَجُلَيْنِ رَجُلٌ وَقَالَ لِلْقَاعِدِ ‏ ‏أَيُّكُمَا خَلَفَ الْخَارِجَ فِي أَهْلِهِ وَمَالِهِ بِخَيْرٍ كَانَ لَهُ مِثْلُ نِصْفِ أَجْرِ الْخَارِجِ ‏","","",""],[11102,11102,"","আমরা আমার ভাইকে সাহায্য করার কথা বলেছিলাম, তাকে আত্মসমর্পণ করতে হবে, আর আমি তাকে ভালোবাসি, প্রভু, যদি আমাদের এটা সহজে নিতে হয়।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏حَدَّثَهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أُتِيَ بِتَمْرٍ فَأَعْجَبَهُ جَوْدَتُهُ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّا أَخَذْنَا ‏ ‏صَاعًا ‏ ‏بِصَاعَيْنِ ‏ ‏لِنَطْعَمَهُ ‏ ‏فَكَرِهَ ذَلِكَ وَنَهَى عَنْهُ ‏","","",""],[11103,11103,"","আমরা একজন প্রিয় বাবাকে নিয়ে কথা বলেছি, ঈশ্বর আমার বাবার খবর নিয়ে, ঈশ্বরের পতাকায় যে সব কিছু বলা হবে তার জন্য সবচেয়ে ভাল হবে। পাঁচ থেকে দশ বছর বয়স।","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْحَجَّاجِ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي حَازِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَلَاةُ الْجَمَاعَةِ تَفْضُلُ صَلَاةَ الْفَذِّ بِخَمْسٍ وَعِشْرِينَ دَرَجَةً ‏","","",""],[11104,11104,"","আমরা আমার বাবার সাথে কথা বলেছিলাম... ...তিনি বলেছিলেন যে ঈশ্বর এটা উদ্ধার করতে ভুলে গেছেন আর মৃত্যুর জন্য যুদ্ধ করতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلَّهِ عَزَّ وَجَلَّ مِائَةُ رَحْمَةٍ فَقَسَمَ مِنْهَا جُزْءًا وَاحِدًا بَيْنَ الْخَلْقِ فَبِهِ يَتَرَاحَمُ النَّاسُ وَالْوَحْشُ وَالطَّيْرُ ‏","","",""],[11105,11105,"","ঈশ্বর তাকে তাঁর প্রতি দয়া দেখান, যাতে তিনি সেই সুখের উৎস হতে পারেন, তাই এটা সৃষ্টি করেছিলেন । যে তার ছিল তার মান।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلَّهِ مِائَةُ رَحْمَةٍ عِنْدَهُ تِسْعَةٌ وَتِسْعُونَ وَجَعَلَ عِنْدَكُمْ وَاحِدَةً ‏ ‏تَرَاحَمُونَ بِهَا بَيْنَ الْجِنِّ وَالْإِنْسِ وَبَيْنَ الْخَلْقِ فَإِذَا كَانَ يَوْمُ الْقِيَامَةِ ضَمَّهَا إِلَيْهَا ‏","","",""],[11106,11106,"","আমি আমার ভাই মাস্টারকে সাহায্য করার কথা বলেছিলাম, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করেছেন যে মানুষ তার প্রার্থনা চুরি করবে এবং বলে, তার হাঁটু যেন চলে না যায় এবং তার স্টকের স্টকগুলো। অজ্ঞাত অক্ষর, সনাক্ত করা সম্ভব হয় নি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَسْوَأَ النَّاسِ سَرِقَةً الَّذِي يَسْرِقُ صَلَاتَهُ قَالُوا يَا رَسُولَ اللَّهِ وَكَيْفَ يَسْرِقُهَا قَالَ لَا يُتِمُّ رُكُوعَهَا وَلَا سُجُودَهَا ‏","","",""],[11107,11107,"","ঈশ্বর তাকে আদেশ দিয়েছেন আর তিনি যদি অপরাধ করেন, তাহলে আমি তাকে আত্মসমর্পণ করব এবং আগুন জ্বালিয়ে দিব । সে বলেছে, খোদা চলে গেছে, ভালো বিশ্বাসের প্রেমে সে মারা গেছে, আর সে চলে গেছে। আমরা একে একে অপরের প্রেমে জড়িয়েছি, অথবা শান্তি পথে। আমাকে স্বপ্ন ছেড়ে দিতে হবে, সে দেখতে পায়নি সে একটা ভদ্র গ্রীষ্মের আয়োজন করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِذَا دَخَلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ وَأَهْلُ النَّارِ النَّارَ قَالَ يَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى ‏ ‏مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ ‏ ‏مِنْ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ إِيمَانٍ فَأَخْرِجُوهُ قَالَ فَيُخْرَجُونَ قَدْ ‏ ‏امْتَحَشُوا ‏ ‏وَعَادُوا فَحْمًا فَيُلْقَوْنَ فِي نَهَرٍ يُقَالُ لَهُ نَهَرُ الْحَيَاةِ فَيَنْبُتُونَ فِيهِ كَمَا تَنْبُتُ الْحِبَّةُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ ‏ ‏أَوْ قَالَ فِي ‏ ‏حَمِيلَةِ ‏ ‏السَّيْلِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ تَرَوْا أَنَّهَا تَنْبُتُ صَفْرَاءَ مُلْتَوِيَةً ‏","","",""],[11108,11108,"","আমরা কথা বলেছি একটা একা একার জন্য হয়েছে, তার কাছে শান্তি আছে যে ভাববাদী তার কাছে প্রার্থনা করেছেন... ...আর সে তোমাকে হত্যা করবে, কিন্তু সে মারা যাবে না তুমি, আমি সব থেকে তোমাকে বের করে দেব... ...যেগুলো তোমাকে কষ্ট দেয়... ...আর তোমার নাম থেকে গন্ধ পায়...","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ اشْتَكَيْتَ يَا ‏ ‏مُحَمَّدُ ‏ ‏فَقَالَ نَعَمْ فَقَالَ بِسْمِ اللَّهِ ‏ ‏أَرْقِيكَ مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ مِنْ شَرِّ كُلِّ عَيْنٍ وَنَفْسٍ ‏ ‏يَشْفِيكَ بِسْمِ اللَّهِ ‏ ‏أَرْقِيكَ ‏","","",""],[11109,11109,"","আমরা দুজন সালমামোনের ব্যাপারে কথা বলেছি কিন্তু অনেকবার আমরা হাত কাটাবার কথা বলেছি। আমার বাবা বলেছিলেন, প্রভু, আমি নিশ্চিত যে, সে এখানে নিরাপদ দাঙ্গা অথবা নাটক করতে করতে করতে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً ‏ ‏عَطَاءُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ الْمُؤْمِنِينَ أَفْضَلُ قَالَ مُؤْمِنٌ يُجَاهِدُ فِي سَبِيلِ اللَّهِ بِنَفْسِهِ وَمَالِهِ قَالُوا ثُمَّ مَنْ قَالَ مُؤْمِنٌ اعْتَزَلَ فِي ‏ ‏شِعْبٍ ‏ ‏مِنْ ‏ ‏الشِّعَابِ ‏ ‏أَوْ ‏ ‏الشُّعْبَةِ ‏ ‏كَفَى النَّاسَ شَرَّهُ ‏","","",""],[11110,11110,"","আমার বাবা একজন উত্তম দাস হওয়ার বিষয়ে আমরা কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَكْتُبُوا عَنِّي شَيْئًا غَيْرَ الْقُرْآنِ فَمَنْ كَتَبَ عَنِّي شَيْئًا غَيْرَ الْقُرْآنِ فَلْيَمْحُهُ ‏","","",""],[11111,11111,"","তারা আমাকে নিয়ে কথা বলেছে, কিন্তু তারা আমার ব্যাপারে কথা বলতে চায়নি এবং মিথ্যা বলতেও চায়নি।","‏ ‏وَقَالَ ‏ ‏حَدِّثُوا عَنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَلَا حَرَجَ حَدِّثُوا عَنِّي وَلَا تَكْذِبُوا قَالَ وَمَنْ كَذَبَ عَلَيَّ ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏أَحْسَبُهُ قَالَ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[11112,11112,"","আমরা বাবার পরম শান্তি নিয়ে কথা বলেছি। ঈশ্বরের ইচ্ছার নামে শপথ করে বলছি যে, সে যেন ঈশ্বরের কাছে শপথ করে। যে ব ্ যক ্ তি নিজেকে স ্ বীকার করে , তার জন ্ যে রয়েছে বিজয়ী । আল্লাহ আমাকে বলেছেন, যদি আমি না করি তবে তাঁর সাথে চিকিৎসা করা উচিত। তার প্রার্থনা এবং তার বধিরতা ধরে রাখার সিদ্ধান্ত নিয়েছে। তাহলে সে তার আগমনের দিকে তাকিয়ে থাকে, যদি কিছু না থাকে, সে চলে যাবে, হয়ত কেউ হয়তো অন্য কারো মত বিবেচনা করবে অথবা অন্য কাউকে হারানো হবে। ঈশ্বর তাকে আদেশ দিয়েছেন এবং আমি তাঁহার মৃত্যু ও মৃত্যু সাক্ষ্য দিব । ( ১ রাজাবলি ১১: ১ - ৩) তাঁর সঙ্গে মারা যাওয়ার পর ঈশ্বর তাঁর জন্য প্রার্থনা করেছিলেন এবং তিনি তা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْسِمُ قِسْمًا إِذْ جَاءَهُ ‏ ‏ابْنُ ذِي الْخُوَيْصِرَةِ التَّمِيمِيُّ ‏ ‏فَقَالَ اعْدِلْ يَا رَسُولَ اللَّهِ فَقَالَ وَيْلَكَ وَمَنْ يَعْدِلُ إِذَا لَمْ أَعْدِلْ فَقَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏يَا رَسُولَ اللَّهِ أَتَأْذَنُ لِي فِيهِ فَأَضْرِبَ عُنُقَهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُ فَإِنَّ لَهُ أَصْحَابًا يَحْتَقِرُ أَحَدُكُمْ صَلَاتَهُ مَعَ صَلَاتِهِ وَصِيَامَهُ مَعَ صِيَامِهِ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏فَيُنْظَرُ فِي ‏ ‏قُذَذِهِ ‏ ‏فَلَا يُوجَدُ فِيهِ شَيْءٌ ثُمَّ يُنْظَرُ فِي ‏ ‏نَضِيَّتِهِ ‏ ‏فَلَا يُوجَدُ فِيهِ شَيْءٌ ثُمَّ يُنْظَرُ فِي ‏ ‏رِصَافِهِ ‏ ‏فَلَا يُوجَدُ فِيهِ شَيْءٌ ثُمَّ يُنْظَرُ فِي ‏ ‏نَصْلِهِ ‏ ‏فَلَا يُوجَدُ فِيهِ شَيْءٌ قَدْ سَبَقَ ‏ ‏الْفَرْثَ ‏ ‏وَالدَّمَ مِنْهُمْ رَجُلٌ أَسْوَدُ فِي إِحْدَى يَدَيْهِ ‏ ‏أَوْ قَالَ إِحْدَى ثَدْيَيْهِ ‏ ‏مِثْلُ ثَدْيِ الْمَرْأَةِ ‏ ‏أَوْ مِثْلُ ‏ ‏الْبَضْعَةِ ‏ ‏تَدَرْدَرُ ‏ ‏يَخْرُجُونَ عَلَى حِينِ ‏ ‏فَتْرَةٍ ‏ ‏مِنْ النَّاسِ فَنَزَلَتْ فِيهِمْ ‏ { ‏وَمِنْهُمْ مَنْ يَلْمِزُكَ فِي ‏ ‏الصَّدَقَاتِ ‏ } ‏الْآيَةَ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَشْهَدُ أَنِّي سَمِعْتُ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَشْهَدُ أَنَّ ‏ ‏عَلِيًّا ‏ ‏حِينَ قَتَلَهُ وَأَنَا مَعَهُ جِيءَ بِالرَّجُلِ عَلَى ‏ ‏النَّعْتِ ‏ ‏الَّذِي ‏ ‏نَعَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11113,11113,"","আমরা আমার ভাইয়ের সবচেয়ে ভালটা নিয়ে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি কোন গানের সাথে বন্ধুত্বের সমাধান করতে পারবো না। রাতে অথবা ছুরি হাতে ধরা তুমি তার কাছ থেকে বিশ্বাস কর যে সে একজন গায়ক।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحِلُّ ‏ ‏الصَّدَقَةُ ‏ ‏لِغَنِيٍّ إِلَّا لِخَمْسَةٍ لِعَامِلٍ عَلَيْهَا أَوْ رَجُلٍ اشْتَرَاهَا بِمَالِهِ أَوْ ‏ ‏غَارِمٍ ‏ ‏أَوْ غَازٍ فِي سَبِيلِ اللَّهِ أَوْ مِسْكِينٍ تُصُدِّقَ عَلَيْهِ مِنْهَا فَأَهْدَى مِنْهَا لِغَنِيٍّ ‏","","",""],[11114,11114,"","দিনের সেরাটা নিয়ে আমরা কথা বলেছি, আমি বাবার কাছে ফিরে যাব, ঈশ্বরের সবচেয়ে ভালো হওয়ার জন্য খুশি হব। পরিকল্পনা করার আগে, সে তার লাইনে থাকবে। গতি এবং নিয়ন্ত্রণ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏أَخْبَرَنِي ‏ ‏الْحَارِثُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عَبْدِ اللَّهِ بْنِ سَعْدِ بْنِ أَبِي سَرْحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَبْدَأُ يَوْمَ الْفِطْرِ وَيَوْمَ الْأَضْحَى بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ ثُمَّ يَخْطُبُ ‏ ‏فَيَكُونُ فِي خُطْبَتِهِ ‏ ‏الْأَمْرُ بِالْبَعْثِ وَالسَّرِيَّةِ ‏","","",""],[11115,11115,"","আমি ঈশ্বরের সর্বোত্তমটা সম্বন্ধে বলেছিলাম । প্রভু, আমার বাবা তাকে কিছু একটা করার সময় মেরে ফেলতে বলেছিলেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَرَادَ أَنْ يَمُرَّ بَيْنَكَ وَبَيْنَ سُتْرَتِكَ أَحَدٌ فَارْدُدْهُ فَإِنْ أَبَى فَادْفَعْهُ فَإِنْ أَبَى فَقَاتِلْهُ فَإِنَّمَا هُوَ شَيْطَانٌ ‏","","",""],[11116,11116,"","আমরা কথা বলেছি 'Sun' সম্পর্কে ভাল কথা বলাটা ভাল, আমি তার জন্য ঈশ্বরের বার্তাবাহকের কাছে এসে পৌঁছেছে আর সে যুদ্ধের জন্য করেছে। আমি চাই না যে ঈশ্বর একজন থেকে ভালো কিছু করেছেন। আমি এটা শুনতে পেরে খুশি নই যে, ঈশ্বরের কাছে যুদ্ধ করার জন্য তার জন্য। আমি যদি যুদ্ধ করি, তাহলে আমি এটা শুনতে চাই না যে, ঈশ্বরের কাছে ক্ষমা প্রার্থনা করছি। আমি যদি আমার পক্ষ থেকে কিছু একটা জিনিস আছে। আমি চাই না। আমি মনে করি, আমি যদি আমার মনে করি, আমি এটা একটা জিনিস আছে। কিন্তু আমি চাই না যে, তা হলে আমরা আমাদের জন্য একটা ভাল কাজ করতে পারি। আমি এটা করতে চাই। আমি চাই। আমি চাই না। আমি চাই, আমি চাই না যে আমি এটা করতে চাই। আমি চাই, আমি চাই, আমি চাই না যে আমি এটা আমার কাছে একটা বিষয় নিয়ে কথা বলি, আমি শুধু একটা প্রশ্ন করি। আমি যদি আমি চাই, আমি চাই, আমি এটা একটা প্রশ্ন করি, আমি চাই, আমি শুধু একটা প্রশ্ন করি। কিন্তু আমি চাই, আমি চাই, আমি চাই, আমি চাই, আমি চাই, আমি চাই, আমি চাই, আমি এটা একটা কথা বলি, শ্বাস নাও সে তোমার ছেলেকে বলেছিল আর তারপর ও এটা বলবে না, আমি এটা ভেঙ্গে দিচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ حَبِيبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا الْمُثَنَّى ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏مَرْوَانَ ‏ ‏يَسْأَلُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏أَسَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ النَّفْخِ فِي الشَّرَابِ فَقَالَ نَعَمْ قَالَ فَقَالَ رَجُلٌ فَإِنِّي لَا ‏ ‏أُرْوَى يَا رَسُولَ اللَّهِ مِنْ نَفَسٍ وَاحِدٍ قَالَ ‏ ‏فَأَبِنْ ‏ ‏الْقَدَحَ عَنْ ‏ ‏فِيكَ ثُمَّ تَنَفَّسْ قَالَ إِنِّي أَرَى ‏ ‏الْقَذَى ‏ ‏فِيهِ قَالَ ‏ ‏فَأَهْرِقْهُ ‏","","",""],[11117,11117,"","ঈশ্বরের সর্বোত্তমটা সম্বন্ধে আমরা কথা বলেছিলাম, আমরা হয়তো এর জন্য প্রশংসা লাভ করেছি । ঈশ্বরের দোহাই, পর্বত আর দেশের ভাগ্য ড্রাগনের শিল্পে পরিচিত।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوشِكُ أَنْ يَكُونَ خَيْرَ مَالِ الرَّجُلِ غَنَمٌ يَتْبَعُ بِهَا ‏ ‏شَعَفَ ‏ ‏الْجِبَالِ وَمَوَاقِعَ ‏ ‏الْقَطْرِ ‏ ‏يَفِرُّ بِدِينِهِ مِنْ ‏ ‏الْفِتَنِ ‏","","",""],[11118,11118,"","বাবা আমাদের বলেছেন যে আমার বাবা খুশি হবেন, তারা তাকে ভাববাদীর ব্যাপারে বলছে, ঈশ্বর এটা করতে হবে আর তিনি তাদের ছেড়ে দিবেন. আমি আমার থেকে বঞ্চিত ছিলাম. তিন দিন মৃত্যুর পর, তারা মারা গেছে এবং সবাই মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏وَعَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏كِلَاهُمَا يَرْوِيهِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَحَدُهُمَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي كُنْتُ حَرَّمْتُ لُحُومَ الْأَضَاحِيِّ فَوْقَ ثَلَاثَةِ أَيَّامٍ فَكُلُوا وَتَزَوَّدُوا وَادَّخِرُوا مَا شِئْتُمْ ‏ ‏وَقَالَ ‏ ‏الْآخَرُ كُلُوا وَأَطْعِمُوا وَادَّخِرُوا مَا شِئْتُمْ ‏","","",""],[11119,11119,"","আমরা সবার সেরা লোকের ব্যাপারে কথা বলেছি, আর তারপর আমরা আমার কিছু সংবাদ উড়িয়ে দিবো, বাবা তাকে বলে যে সে এতই খুশি যে সে এই পরিমাপ হারিয়ে ফেলেছে যখন সে আমার ছেলে না, তখন সে কত বড় ভুল করেছে। প্রভু, আমরা ঈশ্বরের মত করে তৈরি করেছি, তাই আমরা সূর্যয় আছি, অথবা আমরা তোমাকে পরিবর্তন করেছি... ...যা বলে যে, এই আলোই লাফ দেওয়াকে তার ক্ষমতার ক্ষতি করে দেয় না, আর আদালতে নয়। রাজ্য বলছে সে দুইবার মোয়াপ জিতেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا ثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو قَزَعَةَ ‏ ‏أَنَّ ‏ ‏أَبَا نَضْرَةَ ‏ ‏أَخْبَرَهُ ‏ ‏وَحَسَنًا ‏ ‏أَخْبَرَهُمَا أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏وَفْدَ عَبْدِ الْقَيْسِ ‏ ‏لَمَّا أَتَوْا نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا يَا نَبِيَّ اللَّهِ جَعَلَنَا اللَّهُ فِدَاءَكَ مَاذَا يَصْلُحُ لَنَا فِي الْأَشْرِبَةِ فَقَالَ ‏ ‏لَا تَشْرَبُوا فِي ‏ ‏النَّقِيرِ ‏ ‏فَقَالُوا يَا نَبِيَّ اللَّهِ جَعَلنَا اللَّهُ فِدَاءَكَ أَوَتَدْرِ مَا ‏ ‏النَّقِيرُ ‏ ‏قَالَ نَعَمْ ‏ ‏الْجِذْعُ ‏ ‏يُنْقَرُ وَسَطُهُ وَلَا فِي ‏ ‏الدُّبَّاءِ ‏ ‏وَلَا فِي ‏ ‏الْحَنْتَمَةِ ‏ ‏وَعَلَيْكُمْ ‏ ‏بِالْمُوكَإِ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏بِالْمُوكَإِ ‏ ‏مَرَّتَيْنِ ‏","","",""],[11120,11120,"","আমি আমার ভাইয়ের গালের চেয়ে ভালো কাউকে বেনের সাথে কথা বলেছি। ঈশ্বরের ইচ্ছা জানতে চাইলে তাকে জিজ্ঞেস করুন, আমি কি করবো, নাকি আমরা যা করব তা করব। তাকে যেতে বলা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْعَزْلِ ‏ ‏فَقَالَ أَوَإِنَّكُمْ تَفْعَلُونَ قَالُوا نَعَمْ قَالَ ‏ ‏فَلَا عَلَيْكُمْ أَنْ لَا تَفْعَلُوا فَإِنَّ اللَّهَ تَعَالَى لَمْ يَقْضِ لِنَفْسٍ أَنْ يَخْلُقَهَا إِلَّا هِيَ ‏ ‏كَائِنَةٌ ‏","","",""],[11121,11121,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আমি কখনও এই কথা বলতে চাই না যে, আপনি ঈশ্বরের জন্য প্রার্থনা করবেন । আমি তোমার মত না, আর চুপ করো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو النَّدَبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُوَاصِلُوا ‏ ‏قَالُوا فَإِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ إِنِّي لَسْتُ مِثْلَكُمْ إِنِّي أَبِيتُ أُطْعَمُ وَأُسْقَى ‏","","",""],[11122,11122,"","আমরা আমার বাবার সঙ্গে আমার প্রভুর আনন্দপূর্ণ প্রেম সম্বন্ধে কথা বলেছিলাম । তুমি বলো আমরা স্বাধীন, নাকি আমরা আমাদের লোক হারিয়েছি? প্রাসুল ঈশ্বরের কাছে প্রার্থনা করতে যাচ্ছি। যদি কোন বাবা-মাকে জিজ্ঞেস করে তাহলে তার ইচ্ছা হবে। নাহলে আমি তোমার পিল বা তোমার সমস্যা নিয়ে তোমার সমস্যা নিয়ে আসব। কিন্তু আমি যেতে আদেশ দিয়েছি। এমনকি তারা তা করবে না। আমাকে ভাল বোধ করা.","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏اجْتَمَعَ أُنَاسٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالُوا ‏ ‏آثَرَ ‏ ‏عَلَيْنَا غَيْرَنَا فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَمَعَهُمْ ثُمَّ خَطَبَهُمْ فَقَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَلَمْ تَكُونُوا أَذِلَّةً فَأَعَزَّكُمْ اللَّهُ قَالُوا صَدَقَ اللَّهُ وَرَسُولُهُ قَالَ أَلَمْ تَكُونُوا ضُلَّالًا فَهَدَاكُمْ اللَّهُ قَالُوا صَدَقَ اللَّهُ وَرَسُولُهُ قَالَ أَلَمْ تَكُونُوا فُقَرَاءَ فَأَغْنَاكُمْ اللَّهُ قَالُوا صَدَقَ اللَّهُ وَرَسُولُهُ ثُمَّ قَالَ أَلَا تُجِيبُونَنِي أَلَا تَقُولُونَ أَتَيْتَنَا طَرِيدًا فَآوَيْنَاكَ وَأَتَيْتَنَا خَائِفًا فَآمَنَّاكَ أَلَا تَرْضَوْنَ أَنْ يَذْهَبَ النَّاسُ ‏ ‏بِالشَّاءِ ‏ ‏وَالْبُقْرَانِ ‏ ‏يَعْنِي الْبَقَرَ ‏ ‏وَتَذْهَبُونَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتُدْخِلُونَهُ بُيُوتَكُمْ لَوْ أَنَّ النَّاسَ سَلَكُوا وَادِيًا ‏ ‏أَوْ ‏ ‏شُعْبَةً ‏ ‏وَسَلَكْتُمْ وَادِيًا ‏ ‏أَوْ ‏ ‏شُعْبَةً ‏ ‏سَلَكْتُ وَادِيَكُمْ ‏ ‏أَوْ ‏ ‏شُعْبَتَكُمْ ‏ ‏لَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَإِنَّكُمْ سَتَلْقَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏فَاصْبِرُوا حَتَّى تَلْقَوْنِي عَلَى الْحَوْضِ ‏","","",""],[11123,11123,"","আমরা এটা নিয়ে কথা বলেছি নিজের জীবনের সৌভাগ্যের সাথে। আমি আমার বাবার জন্য খাওয়া-দাওয়ার জন্য, সুখী গাল বলে যে ঈশ্বর তার সাথে এমন করেছে এবং সে ঐ লোভীদের পেয়েছে। তাদের মধ্যে কেউ কেউ ভ্রূণ এবং আগুনের মধ্যে বল স্থাপন করতে পছন্দ করে।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏فِي قَوْلِهِ ‏ { ‏وَنَزَعْنَا مَا فِي صُدُورِهِمْ مِنْ غِلٍّ ‏} ‏قَالَ ثَنَا ‏ ‏أَبُو الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْلُصُ الْمُؤْمِنُونَ مِنْ النَّارِ فَيُحْبَسُونَ عَلَى قَنْطَرَةٍ بَيْنَ الْجَنَّةِ وَالنَّارِ فَيُقْتَصُّ لِبَعْضِهِمْ مِنْ بَعْضٍ ‏","","",""],[11124,11124,"","আমি আমার ভাইয়ের চেয়ে আমার সবচেয়ে ভাল বাবাকে খুঁজে পাওয়ার ব্যাপারে তর্ক করেছি। ড্রাগটা আমার ভাইকে পছন্দ করে। তোমরা যে মানুষ আমি ঈশ্বরের বিকেলে কাজ করি না, সে এত সাহসী যে সে লিখতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ ‏ ‏تَبُوكَ ‏ ‏خَطَبَ النَّاسَ وَهُوَ مُسْنِدٌ ظَهْرَهُ إِلَى نَخْلَةٍ فَقَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ النَّاسِ وَشَرِّ النَّاسِ إِنَّ مِنْ خَيْرِ النَّاسِ رَجُلًا عَمِلَ فِي سَبِيلِ اللَّهِ عَلَى ظَهْرِ فَرَسِهِ أَوْ عَلَى ظَهْرِ بَعِيرِهِ أَوْ عَلَى قَدَمَيْهِ حَتَّى يَأْتِيَهُ الْمَوْتُ وَإِنَّ مِنْ شَرِّ النَّاسِ رَجُلًا فَاجِرًا جَرِيئًا يَقْرَأُ كِتَابَ اللَّهِ لَا ‏ ‏يَرْعَوِي ‏ ‏إِلَى شَيْءٍ مِنْهُ ‏","","",""],[11125,11125,"","আমরা একটা ছেলে সম্পর্কে কথা বলেছি যে ঈশ্বরের পুত্র রক্ষা করার চেষ্টা করেছে। আমি তাকে বলতে চাই না যে, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তাকে একটি আংটি দিয়েছে। মাঝরাতে, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি একটি গল্প দেবেন তিনি জয়ী হবেন এবং তিনি বললেন যদি আপনি মারা যান তাহলে তার মৃত্যু হবে। এটা তার গোপন বা তার বামের কথা। পা.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَأَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏أَخْبَرَاهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي حَائِطِ الْمَسْجِدِ فَتَنَاوَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَصَاةً فَحَتَّهَا ثُمَّ قَالَ ‏ ‏إِذَا ‏ ‏تَنَخَّعَ ‏ ‏أَحَدُكُمْ فَلَا ‏ ‏يَتَنَخَّمْ ‏ ‏قِبَلَ وَجْهِهِ وَلَا عَنْ يَمِينِهِ لِيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏","","",""],[11126,11126,"","আমরা ঈশ্বরের চেয়ে ভালো কিছু খুঁজে পেতে বলেছি, তাকে বলা হয়েছে যে সে একজন মানুষ। ঈশ্বর আপনাকে যা খুঁজে পেয়েছেন এবং আপনাকে যা খুঁজে পেয়েছেন, তা নিয়ে নিন ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏أُصِيبَ رَجُلٌ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثِمَارٍ ابْتَاعَهَا فَكَثُرَ دَيْنُهُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَصَدَّقُوا عَلَيْهِ قَالَ فَتَصَدَّقَ النَّاسُ عَلَيْهِ فَلَمْ يَبْلُغْ ذَلِكَ وَفَاءَ دَيْنِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذُوا مَا وَجَدْتُمْ وَلَيْسَ لَكُمْ إِلَّا ذَلِكَ ‏","","",""],[11127,11127,"","আমরা আমার সবচেয়ে ভালো বন্ধুকে খুঁজে বের করেছি বাবাকে খুঁজে পেতে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং যারা সেটা বহন করেছে তাদের অন্ত্যেষ্টিক্রিয়ার সময় তিনি আত্মসমর্পণ করেছেন। সে খুবই ঈর্ষান্বিত ছিল, সে কোথায় যেতে চেয়েছিল, আমার ভয় পেয়ে কথা বলেছিলাম, তার মানে বাবা বলবে না সে একটা ঝামেলা করছে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا وُضِعَتْ الْجِنَازَةُ فَاحْتَمَلَهَا الرِّجَالُ عَلَى أَعْنَاقِهِمْ فَإِنْ كَانَتْ صَالِحَةً قَالَتْ قَدِّمُونِي وَإِنْ كَانَتْ غَيْرَ صَالِحَةٍ قَالَتْ يَا وَيْلَهَا أَيْنَ تَذْهَبُونَ بِهَا يَسْمَعُ صَوْتَهَا كُلُّ شَيْءٍ إِلَّا الْإِنْسَانَ وَلَوْ سَمِعَهَا الْإِنْسَانُ ‏ ‏لَصَعِقَ ‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ يَعْنِي أَبَا سَلَمَةَ ‏ ‏إِلَّا أَنَّهُ قَالَ ‏ ‏لَصَعِقَ ‏","","",""],[11128,11128,"","আমরা কথা বলেছি আর তাই আমার সুখ খুঁজে পাওয়ার জন্য আমাদের সর্বোচ্চ চেষ্টাকে ভয় পাচ্ছি। আমার প্রভু আমার বাবার কাছে এসেছেন, স্বাধীন ইচ্ছার সবচেয়ে ভালো হতে পেরে আমি খুশি। আমি চেষ্টা করছি। তাকে চেষ্টা করে বলো যে তার ঋণ খুঁজে বের করতে হবে না এবং তোমার কাছে বলবে, ঈশ্বরের এটা করা দরকার এবং সে বলবে যে তার সবচেয়ে ভাল চেষ্টা হবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏وثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏الْمَهْرِيِّ ‏ ‏أَنَّهُ جَاءَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏لَيَالِي ‏ ‏الْحَرَّةِ ‏ ‏فَاسْتَشَارَهُ فِي ‏ ‏الْجَلَاءِ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏وَشَكَا إِلَيْهِ أَسْعَارَهَا وَكَثْرَةَ عِيَالِهِ وَأَخْبَرَهُ أَنَّهُ لَا صَبْرَ لَهُ عَلَى جَهْدِ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ ‏ ‏وَيْحَكَ ‏ ‏لَا آمُرُكَ بِذَلِكَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَصْبِرُ أَحَدٌ عَلَى جَهْدِ ‏ ‏الْمَدِينَةِ ‏ ‏وَلَأْوَائِهَا ‏ ‏فَيَمُوتُ إِلَّا كُنْتُ لَهُ ‏ ‏شَفِيعًا ‏ ‏أَوْ شَهِيدًا ‏ ‏يَوْمَ الْقِيَامَةِ إِذَا كَانَ مُسْلِمًا ‏","","",""],[11129,11129,"","আমরা তার বাবার কথা বলেছিলাম যে আমি আমার ছেলের মৃত্যুর পরে মারা যাচ্ছি। সে একবার তার কথাকে ঘৃণা করবে। তুমি বলেছিলে আমরা দু বছর আগে এটা কিনেছি এবং ঈশ্বর আছে। আমি এটা একটা শট দেবো।","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَنْبَأَنِي ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ صَاحِبَ التَّمْرِ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِتَمْرَةٍ فَأَنْكَرَهَا فَقَالَ ‏ ‏أَنَّى لَكَ هَذَا قَالَ اشْتَرَيْنَا ‏ ‏بِصَاعَيْنِ ‏ ‏مِنْ تَمْرِنَا ‏ ‏صَاعًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَيْتُمْ ‏","","",""],[11130,11130,"","আমরা একটি রাজধানী সম্পর্কে কথা বলেছিলাম যে, আমি কিভাবে সুখী ছিলাম যে এক মহিলা ছিল এবং হয়ত এক মহিলা মহিলা ছিল যে ছিল এক মহিলা মহিলা, যে ছিল মহিলা মহিলা, যে ছিল মহিলা। ঈশ্বর প্রতিজ্ঞা করেছিলেন যে, তিনি শপথের মতো একটা গহ্বরের মতো যেতে পারেন । তার কথা না শুনলেও সে আমাকে ভেতরে ঢুকতে দিলো।","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَأَبَا هُرَيْرَةَ ‏ ‏وَأَبَا سَعِيدٍ ‏ ‏حَدَّثُوا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الذَّهَبُ بِالذَّهَبِ مِثْلًا بِمِثْلٍ وَالْفِضَّةُ بِالْفِضَّةِ مِثْلًا بِمِثْلٍ عَيْنًا بِعَيْنٍ مَنْ زَادَ أَوْ ازْدَادَ فَقَدْ ‏ ‏أَرْبَى ‏ ‏قَالَ ‏ ‏شُرَحْبِيلُ ‏ ‏إِنْ لَمْ أَكُنْ سَمِعْتُهُ فَأَدْخَلَنِي اللَّهُ النَّارَ ‏","","",""],[11131,11131,"","আমরা ক্ষমার এক বিশেষ বৈশিষ্ট্যের কথা বলেছি, যা আমাদের কাছে ঘটেছে, যখন আমরা বাবার সুখী ভাইয়ের উপর বাবার বজ্রপাতের শব্দ খুঁজছি। ( গীতসংহিতা ৩৬: ৯) আর ঈশ্বরের ইচ্ছা হল, তাঁর সঙ্গে আপনার সম্পর্ক নষ্ট হয়ে যাবে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏اشْتَكَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَهُ ‏ ‏جِبْرِيلُ ‏ ‏فَرَقَاهُ فَقَالَ بِسْمِ اللَّهِ ‏ ‏أَرْقِيكَ مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ مِنْ كُلِّ عَيْنٍ وَحَاسِدٍ ‏ ‏يَشْفِيكَ ‏ ‏أَوْ قَالَ اللَّهُ ‏ ‏يَشْفِيكَ ‏","","",""],[11132,11132,"","আমরা আমার বাবা মাতাল হওয়ার চেষ্টা করে বলেন, \"ঈশ্বর,\" তার শান্তি আছে যা ভবিষ্যদ্বাণী, তার আশীর্বাদ আর আশীর্বাদ আর ফেরেশতা আর আশীর্বাদ সব থেকে বড় তার মা বলবে যে, যদি সে তোমাকে জানে, তা হলে তাদেরকে বলা হবে । মাটিতে যাও, তোমার সুনাম আছে","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجِيءُ النَّبِيُّ يَوْمَ الْقِيَامَةِ وَمَعَهُ الرَّجُلُ وَالنَّبِيُّ وَمَعَهُ الرَّجُلَانِ وَأَكْثَرُ مِنْ ذَلِكَ ‏ ‏فَيُدْعَى قَوْمُهُ فَيُقَالُ لَهُمْ هَلْ بَلَّغَكُمْ هَذَا فَيَقُولُونَ لَا فَيُقَالُ لَهُ هَلْ بَلَّغْتَ قَوْمَكَ فَيَقُولُ نَعَمْ فَيُقَالُ لَهُ مَنْ يَشْهَدُ لَكَ فَيَقُولُ ‏ ‏مُحَمَّدٌ ‏ ‏وَأُمَّتُهُ ‏ ‏فَيُدْعَى ‏ ‏مُحَمَّدٌ ‏ ‏وَأُمَّتُهُ فَيُقَالُ لَهُمْ هَلْ بَلَّغَ هَذَا قَوْمَهُ فَيَقُولُونَ نَعَمْ فَيُقَالُ وَمَا عِلْمُكُمْ فَيَقُولُونَ جَاءَنَا نَبِيُّنَا فَأَخْبَرَنَا أَنَّ الرُّسُلَ قَدْ بَلَّغُوا فَذَلِكَ قَوْلُهُ ‏ { ‏وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا ‏} ‏قَالَ يَقُولُ عَدْلًا ‏ { ‏لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا ‏}","","",""],[11133,11133,"","আমি আমার বাবার সাথে মজা করার কথা বলেছিলাম, সে আমাকে ছেড়ে যেতে দেবে না। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি তার এই ভুলের জন্য প্রার্থনা করেছেন এবং গ্রাহক আর পাসের জন্য।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي أَرْطَاةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الزَّهْوِ ‏ ‏وَالتَّمْرِ وَالزَّبِيبِ وَالتَّمْرِ ‏","","",""],[11134,11134,"","আমরা একটা ছেলের কথা বলেছি যে বাবার সাথে ঘুমের জন্য আমি আমার নাম নিয়ে সাহায্য করব।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ بْنُ سَعِيدِ بْنِ مَسْرُوقٍ ‏ ‏عَنِ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ أَبِي عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ بَاعَدَ اللَّهُ بِذَلِكَ الْيَوْمِ النَّارَ عَنْ وَجْهِهِ سَبْعِينَ خَرِيفًا ‏","","",""],[11135,11135,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করেছেন, যাতে আমি আপনাকে গ্রহণ করার নামে আপনাকে ছেড়ে যেতে পারি ঈশ্বরের অন্যান্য লেখকদেরও আমাকে ভিন্নমত পোষণ করতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي قَدْ تَرَكْتُ فِيكُمْ مَا إِنْ أَخَذْتُمْ بِهِ لَنْ تَضِلُّوا بَعْدِي ‏ ‏الثَّقَلَيْنِ ‏ ‏أَحَدُهُمَا أَكْبَرُ مِنْ الْآخَرِ كِتَابُ اللَّهِ حَبْلٌ مَمْدُودٌ مِنْ السَّمَاءِ إِلَى الْأَرْضِ ‏ ‏وَعِتْرَتِي ‏ ‏أَهْلُ بَيْتِي أَلَا وَإِنَّهُمَا لَنْ يَفْتَرِقَا حَتَّى يَرِدَا عَلَيَّ الْحَوْضَ ‏","","",""],[11136,11136,"","আমরা বাবার সবচেয়ে ভালো গাল নিয়ে কথা বলেছিলাম, ঈশ্বর তার কাছে প্রার্থনা করলেন আর তিনি আমাকে নিরাপদে উদ্ধার করলেন আর একটা উজ্জ্বল পোষাকে প্রার্থনা করলেন।","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ ‏ ‏مُتَوَشِّحًا ‏","","",""],[11137,11137,"","ঈশ্বর তাকে প্রার্থনা করেছিলেন এবং তিনি একটা ঘোড়ার জন্য প্রার্থনা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي عَلَى حَصِيرٍ ‏","","",""],[11138,11138,"","আমি বাবার কাছে প্রার্থনা করেছিলাম যেন তিনি ঈশ্বরের কাছে প্রার্থনা করেন, তিনি আমাকে বলেছিলেন, তিনি পঞ্চম বা পঞ্চম ব্যক্তি নন । U-dd-ddO-dd-dd-dd উপস্থিতd-dd-d উপস্থিতd-d-d উপস্থিতdd-dddOOOOOd-d-dOOU-dOOd-dOOOOOOOOO-d-d-d-dOOOd-d-d-dOOOOddd-dd-d-dOOOOd-d-dd-ddOd-d-ddOdOOOOOO-d-d-dddddddOO-dddd-ddddddddddd-dd-ddddddddddd-d-dddd-ddddddddddddd-dddddddddddddddddd-d-d-ddddddddddd-dd-d-d-dddddddddddddddddddd D-d-dd-ddd-dd-dd উপস্থিতd-d-d-dd-dd-d উপস্থিতd-ddd-ddd-dd-ddddd উপস্থিত","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏إِدْرِيسُ الْأَوْدِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسَةِ ‏ ‏أَوْسَاقٍ ‏ ‏زَكَاةٌ ‏ ‏وَالْوَسْقُ ‏ ‏سِتُّونَ ‏ ‏مَخْتُومًا ‏","","",""],[11139,11139,"","তার ভাড়া করা টাকা দিতে হবে এবং স্বপ্নের সাফল্য অর্জন করতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ اسْتِئْجَارِ الْأَجِيرِ حَتَّى يُبَيَّنَ لَهُ أَجْرُهُ وَعَنْ ‏ ‏النَّجْشِ ‏ ‏وَاللَّمْسِ ‏ ‏وَإِلْقَاءِ ‏ ‏الْحَجَرِ ‏","","",""],[11140,11140,"","বাবা তার প্রভুর খোঁজ করছিল বলে আমরা আমার বাবা খুশির সাথে কথা বলেছি, আমি তার বাবাকে খুন করতে জন্ম নিয়েছি, না হলে সব পানিই নষ্ট হয়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْعَزْلِ ‏ ‏فَقَالَ ‏ ‏لَيْسَ مِنْ كُلِّ ‏ ‏الْمَاءِ ‏ ‏يَكُونُ الْوَلَدُ وَإِذَا أَرَادَ اللَّهُ أَنْ يَخْلُقَ مِنْهُ شَيْئًا لَمْ يَمْنَعْهُ شَيْءٌ ‏","","",""],[11141,11141,"","আমার বাবা আমাদের কথা বলছিল যে কিভাবে দ্বিতীয় খুশির কথা বলতে হয়, আমি ঈশ্বরের কাছে প্রার্থনা করব তার আঙ্গুলে লেখা তার প্রার্থনাকে তার বাড়ি থেকে। প্রার্থনা করছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَضَى أَحَدُكُمْ صَلَاتَهُ فِي الْمَسْجِدِ فَلْيَجْعَلْ لِبَيْتِهِ نَصِيبًا مِنْ صَلَاتِهِ إِنَّ اللَّهَ جَاعِلٌ فِي بَيْتِهِ مِنْ صَلَاتِهِ خَيْرًا ‏","","",""],[11142,11142,"","প্রভু তার জন্য প্রার্থনা করেছিলেন এবং যদি তিনি তার প্রার্থনার উত্তর খুঁজে পেতে পারতেন, তা হলে তিনি আত্মসমর্পণ করতেন । তার প্রার্থনার সময়, আমরা একটা ঋতুর জন্য কাজ করেছি যখন আমরা আমার প্রিয় বাবার জন্য একটি ছেলে পেয়েছি, আমি তার জন্য প্রার্থনা করেছি এবং সে যদি আপনার প্রার্থনা করে তাহলে সে বলবে, যদি আপনার কাছে প্রার্থনা করে থাকে। তাহলে আমরা তাকে সাহায্য করতে পারি। কিন্তু আপনি যদি আমার বাবা-মা'র প্রার্থনা করেন, তাহলে আপনি কি করবেন? আপনি যদি আমার বাবা আপনার প্রার্থনা করেন, আপনি তাকে বলেন, আপনি কি করবেন? আপনি যদি আপনার প্রার্থনা করেন, আপনি জানেন, আপনি কি? আপনি আপনার প্রার্থনা করেন, আপনি জানেন, আপনি আপনার প্রার্থনা করুন, আপনি জানেন না? আপনি কি? আপনি আপনার সন্তান না? আপনি যদি আপনার সন্তান না? আপনি জানেন, আপনি কি? আপনি জানেন, আপনি আপনার সন্তান আপনার সন্তান আপনার সন্তান আপনার সন্তান আপনার সন্তান আপনার জন্য একটি মহান সন্তান হবে? আপনার সন্তান হবে। আপনি কি? আপনার সন্তান আপনার সন্তান আপনার সন্তান হবে? আপনার জন্য একটি পরিবার এবং আপনার জন্য একটি বিশেষ সুযোগ। আপনার সন্তান হবে? এবং আপনার সন্তান আপনার সন্তান আপনার জন্য একটি বিশেষ সুযোগ। আপনি যদি আপনি আপনার প্রার্থনা করে থাকেন, আপনার সন্তান থাকে, আপনার সন্তান থাকে, আপনার সন্তান হবে। আপনি আপনার প্রার্থনা, আপনার জন্য ধন্যবাদ।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَضَى أَحَدُكُمْ صَلَاتَهُ فِي الْمَسْجِدِ فَلْيَجْعَلْ لِبَيْتِهِ نَصِيبًا مِنْ صَلَاتِهِ فَإِنَّ اللَّهَ جَاعِلٌ فِي بَيْتِهِ مِنْ صَلَاتِهِ خَيْرًا ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِذَا قَضَى أَحَدُكُمْ صَلَاتَهُ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[11143,11143,"","আমরা আমার বাবার কথা বলেছি, প্রভু, আমাকে তাড়াতাড়ি এসে ছেড়ে দিতে হবে আর আমার বোনের ফোন আর আমি তার সাথে কাজ করছি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوِصَالِ ‏ ‏فِي الصِّيَامِ ‏ ‏وَهَذِهِ أُخْتِي ‏ ‏تُوَاصِلُ ‏ ‏وَأَنَا ‏ ‏أَنْهَاهَا ‏","","",""],[11144,11144,"","আমি কিভাবে বলব সে সম্পর্কে আমরা কথা বলেছি. এটা আমার বাবার সবচেয়ে ভাল দাসেদের নিয়ে... ...ঈশ্বর আমার স্বপ্নকে রক্ষা করেছেন. তিনি কীভাবে তাকে জড়িয়ে ধরেছিলেন এবং বলেছিলেন যে, তিনি আবারও তাকে কীভাবে কোলে নিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ فِي أَقَلَّ مِنْ خَمْسَةِ ‏ ‏أَوْسَاقٍ ‏ ‏مِنْ حَبٍّ وَلَا تَمْرٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَيْسَ فِي أَقَلَّ مِنْ خَمْسَةِ ‏ ‏أَوَاقٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَيْسَ فِي أَقَلَّ مِنْ خَمْسِ ‏ ‏ذَوْدٍ ‏ ‏صَدَقَةٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏مِثْلَهُ بِإِسْنَادِهِ وَقَالَ ثَمَرٍ ‏ ‏و قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏تَمْرٍ ‏ ‏وَقَالَ ثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏فَذَكَرَهُ ‏","","",""],[11145,11145,"","আমরা বাবার দুই ছেলের জন্য তার জন্য বসবাসের জন্য সবচেয়ে ভালো কথা বলেছিলাম, সে বলবে যদি সে মুক্ত হত, তাহলে প্রার্থনা করতো যদি সে বিনামূল্যেই থাকে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[11146,11146,"","আমরা বাবার সবচেয়ে খুশির কথা বলেছিলাম, লর্ড তার কাছে প্রার্থনা করল আর সে রাত থেকে সূর্যকে নিচে সরিয়ে দু'টো প্রার্থনা করতে বলবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏مَوْلَى ‏ ‏زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا صَلَاةَ بَعْدَ صَلَاتَيْنِ بَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ ‏","","",""],[11147,11147,"","আমরা আপনাদের টাকাপয়সাকে অমর বলে রাখার বিষয়ে কথা বলেছিলাম । ভাববাদীর জন্য ভাল প্রার্থনা করা এবং তার আদর্শগুলোকে স্বীকার করা","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ يَعْنِي ابْنَ أَبِي صَعْصَعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسَةِ ‏ ‏أَوْسُقٍ ‏ ‏صَدَقَةٌ وَلَا خَمْسِ ‏ ‏أَوَاقٍ ‏ ‏صَدَقَةٌ وَلَا خَمْسِ ‏ ‏ذَوْدٍ ‏ ‏صَدَقَةٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَشُعْبَةَ ‏ ‏وَمَالِكٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[11148,11148,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং এর মূল্য উপলব্ধির জন্য তাকে সমর্পণ করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الْمُزَابَنَةِ وَالْمُحَاقَلَةِ ‏ ‏وَالْمُزَابَنَةُ اشْتِرَاءُ الثَّمَرَةِ فِي رُءُوسِ النَّخْلِ بِالتَّمْرِ كَيْلًا وَالْمُحَاقَلَةُ فِي ‏ ‏كِرَاءِ ‏ ‏الْأَرْضِ ‏","","",""],[11149,11149,"","দুই বছর পর আমার বাবার কাছ থেকে চলে যাওয়ার জন্য একটা ছেলেকে দেওয়ার জন্য একটা ছেলেকে নিযুক্ত করা হল সবচেয়ে ভাল দাস । ঈশ্বরের প্রভু হবে, এই জনতার প্রত্যেক পণ্ডিতকে উত্তর দিতে হবে ।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو سَلَمَةَ يَعْنِي الْخُزَاعِيَّ ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏غُسْلُ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ ‏ ‏مُحْتَلِمٍ ‏","","",""],[11150,11150,"","তিনি বলেছিলেন: “আপনার টাকাপয়সা মাংসের বাপ্তিস্মের দ্বারা আনন্দের সঙ্গে জীবনযাপন করতে হবে । তাদের প্রার্থনা ও হৃদয় দিয়ে বিশ্বাস করতে হয়। সে আর্মির দিকে কিছু দেখে না, সে বলে হয়তো সে সুখী নয়, এটাই কথা।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَخْرُجُ فِيكُمْ قَوْمٌ ‏ ‏تَحْقِرُونَ ‏ ‏صَلَاتَكُمْ مَعَ صَلَاتِهِمْ وَصِيَامَكُمْ مَعَ صِيَامِهِمْ وَأَعْمَالَكُمْ مَعَ أَعْمَالِهِمْ يَقْرَءُونَ الْقُرْآنَ ‏ ‏لَا يُجَاوِزُ ‏ ‏حَنَاجِرَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ ‏ ‏مُرُوقَ ‏ ‏السَّهْمِ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏يَنْظُرُ فِي ‏ ‏النَّصْلِ ‏ ‏فَلَا يَرَى شَيْئًا ثُمَّ يَنْظُرُ فِي ‏ ‏الْقِدْحِ ‏ ‏فَلَا يَرَى شَيْئًا وَيَنْظُرُ فِي ‏ ‏الرِّيشِ ‏ ‏فَلَا يَرَى شَيْئًا ‏ ‏وَيَتَمَارَى ‏ ‏فِي ‏ ‏الْفُوقِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا بِهِ ‏ ‏مَالِكٌ ‏ ‏يَعْنِي هَذَا الْحَدِيثَ ‏","","",""],[11151,11151,"","আমার বাবার কথা বলেছিলাম আমি কত কিছু করেছি, লজ্জা পাবার যোগ্য আর সবচেয়ে ভালোর জন্য আমার কাছে মাসটা ভালো ঈশ্বর আমাদের সিংহাসনের দশম দশমাংশ দিয়েছেন । ঈশ্বরের অনুগ্রহে পাপ করেছেন এবং তার শান্তির উপর নামছেন। তার সবচেয়ে ভালো কথা হলো, সে দিনের সেরাটা ভুলে গেছে। আমরা ভিতরে এবং প্রার্থনা করার মাধ্যমে এতটাই উদিত হয়েছিলাম যে, আমরা তার পকেটে কাদার প্রভাব দেখতে পাই ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏تَذَاكَرْنَا لَيْلَةَ الْقَدْرِ فِي ‏ ‏نَفَرٍ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَأَتَيْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏وَكَانَ صَدِيقًا لِي فَقُلْتُ اخْرُجْ بِنَا إِلَى النَّخْلِ فَخَرَجَ وَعَلَيْهِ ‏ ‏خَمِيصَةٌ ‏ ‏لَهُ فَقُلْتُ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ لَيْلَةَ الْقَدْرِ قَالَ نَعَمْ ‏ ‏اعْتَكَفْنَا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَشْرَ الْوَسَطَ مِنْ رَمَضَانَ فَخَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَبِيحَةَ عِشْرِينَ فَقَالَ ‏ ‏أُرِيتُ لَيْلَةَ الْقَدْرِ فَأُنْسِيتُهَا ‏ ‏أَوْ قَالَ فَنَسِيتُهَا ‏ ‏فَالْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ فِي ‏ ‏الْوَتْرِ ‏ ‏فَإِنِّي رَأَيْتُ أَنِّي أَسْجُدُ فِي مَاءٍ وَطِينٍ فَمَنْ كَانَ ‏ ‏اعْتَكَفَ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلْيَرْجِعْ فَرَجَعْنَا وَمَا نَرَى فِي السَّمَاءِ ‏ ‏قَزَعَةً ‏ ‏فَجَاءَتْ سَحَابَةٌ فَمُطِرْنَا حَتَّى سَالَ سَقْفُ الْمَسْجِدِ وَكَانَ مِنْ جَرِيدِ النَّخْلِ وَأُقِيمَتْ الصَّلَاةُ وَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِي الْمَاءِ وَالطِّينِ حَتَّى رَأَيْتُ ‏ ‏أَثَرَ ‏ ‏الطِّينِ فِي جَبْهَتِهِ ‏","","",""],[11152,11152,"","আমরা কথা বলেছি আমার বাবার আনন্দ বৃদ্ধি করে বেনকে সাহায্য করতে। ঈশ্বর আপনার উত্তরাধিকারের থেকে আত্মসমর্পণ করবেন এবং টাকা দিয়ে তার টাকা এত বেশী হবে যে সে তা করেনি। এখন এটা গুনবো।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ خُلَفَائِكُمْ خَلِيفَةٌ ‏ ‏يَحْثِي ‏ ‏الْمَالَ ‏ ‏حَثْيًا ‏ ‏لَا يَعُدُّهُ عَدًّا ‏","","",""],[11153,11153,"","আমি তাকে বলেছি, আমি তাকে যে খুশি নেশার সন্তান বলবো, সে তাকে লিখে রাখবো, সে হবে। কখনো তাকে বলবে না যে, ঈশ্বর যদি কিছু ছেলেদের জন্য প্রার্থনা করেন তাহলে তাকে প্রার্থনা করতে হবে। এটা এমন নয় যে আমরা এর মধ্যে দিয়ে যেতে অসুস্থ। আপনি সিদ্ধান্ত নেন যে, আপনার প্রভু যদি পাশ থেকে চলে যান, তাহলে তিনি যদি আমাদের ছেড়ে চলে যান। তাহলে আপনি নিশ্চিত যে, আপনি নিশ্চিত নন, এটা আপনার প্রভু যদি আমাদের জন্য একটি ভাল সন্তান থাকে, তাহলে আপনি তাকে ছেড়ে চলে যাবে। এবং আপনি কি করবেন? এবং আপনি যদি আপনি আপনার প্রভু যদি আপনার জন্য প্রার্থনা করেন, আপনি জানেন যে আপনি আপনার জন্য একটি ভাল সন্তান না? আপনি যদি আপনি জানেন, আপনি যদি আপনি একটি মহান পিতা হয়ে থাকেন, আপনি একটি মহান পিতা হতে পারেন, আপনি কি? আপনি আপনার জন্য একটি মহান পিতা, আপনি কি? আপনি আপনার জন্য একটি মহান পিতা হতে পারেন, আপনি কি না? এটা আপনার প্রভু যদি আপনি একটি মহান সময়, আপনি একটি মহান পিতা, আপনি একটি মহান মহান আপ কি না? এটা আপনার জন্য প্রার্থনা করতে পারেন, আপনি কি না? এটা আপনার জন্য একটি মহান মহান মহান মহান সময়, এটা আপনার প্রভু। তারপর তৃতীয় থেকে যে ফিরে এসেছে তাকে কিছু একটা কিনে নাও.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ الصَّرْفِ فَقَالَ يَدٌ بِيَدٍ قُلْتُ نَعَمْ قَالَ لَا بَأْسَ فَلَقِيتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏فَأَخْبَرْتُهُ أَنِّي سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ الصَّرْفِ فَقَالَ لَا بَأْسَ فَقَالَ ‏ ‏أَوَقَالَ ذَاكَ أَمَّا إِنَّا سَنَكْتُبُ إِلَيْهِ فَلَنْ يُفْتِيَكُمُوهُ قَالَ فَوَاللَّهِ لَقَدْ جَاءَ بَعْضُ فِتْيَانِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِتَمْرٍ فَأَنْكَرَهُ فَقَالَ ‏ ‏كَأَنَّ هَذَا لَيْسَ مِنْ تَمْرِ أَرْضِنَا فَقَالَ كَانَ فِي تَمْرِنَا الْعَامَ بَعْضُ الشَّيْءِ وَأَخَذْتُ هَذَا وَزِدْتُ بَعْضَ الزِّيَادَةِ فَقَالَ أَضْعَفْتَ أَرْبَيْتَ لَا تَقْرَبَنَّ هَذَا إِذَا رَابَكَ مِنْ تَمْرِكَ شَيْءٌ فَبِعْهُ ثُمَّ اشْتَرِ الَّذِي تُرِيدُ مِنْ الثَّمَرِ ‏","","",""],[11154,11154,"","আমরা আমার বাবার কথা বলেছিলাম আমরা কাজ করতে পারিনি। আমি ঈশ্বরের কাছে প্রার্থনা করছি, রসুনের তৃতীয় স্থানে তাকে উদ্ধার করতে হবে। সব কিছু ঈশ্বরের প্রার্থনা আছে। তার জন্য এবং লর্ড লর্ডের লর্ডের হত্যা করা হয়েছে এমন একজন লোকের ক্ষেত্রে, যারা তাদের স্বাধীনতা থেকে বঞ্চিত হয়েছে, ঈশ্বর প্রার্থনা করেছেন, কিন্তু আমি সমাধান করতে চাই। সে একটা গাছ, যাকে আমি ঘৃণা করি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏لَمْ نَعْدُ أَنْ فُتِحَتْ ‏ ‏خَيْبَرُ ‏ ‏وَقَعْنَا ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي تِيكَ ‏ ‏الْبَقْلَةِ ‏ ‏فِي الثُّومِ فَأَكَلْنَا مِنْهَا أَكْلًا شَدِيدًا وَنَاسٌ جِيَاعٌ ثُمَّ رُحْنَا إِلَى الْمَسْجِدِ فَوَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرِّيحَ فَقَالَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ ‏ ‏الْبَقْلَةِ ‏ ‏الْخَبِيثَةِ شَيْئًا فَلَا يَقْرَبْنَا فِي الْمَسْجِدِ فَقَالَ نَاسٌ حُرِّمَتْ حُرِّمَتْ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَيُّهَا النَّاسُ إِنَّهُ لَيْسَ لِي تَحْرِيمُ مَا أَحَلَّ اللَّهُ وَلَكِنَّهَا شَجَرَةٌ أَكْرَهُ رِيحَهَا ‏","","",""],[11155,11155,"","আমি একটা হাত দেওয়ার প্রতিশ্রুতির কথা বলেছিলাম, ঈশ্বর তাকে প্রার্থনা করেছিলেন আর তাকে মূল্য দিতে হবে। ঠিক আছে, এমনকি অভিযোগও না, ঈশ্বর সেটা রক্ষা করুন।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُؤْمِنَ لَا يُصِيبُهُ ‏ ‏نَصَبٌ ‏ ‏وَلَا ‏ ‏وَصَبٌ ‏ ‏وَلَا ‏ ‏سَقَمٌ ‏ ‏وَلَا حَزَنٌ وَلَا أَذًى حَتَّى الْهَمُّ يُهِمُّهُ إِلَّا اللَّهُ يُكَفِّرُ عَنْهُ مِنْ سَيِّئَاتِهِ ‏","","",""],[11156,11156,"","আমি আমার বাবার সাথে কথা বলেছি যে সে চলে গেছে, আমি তার সাথে কথা বলেছি, তুমি তার সাথে ঈশ্বরের শান্তি নিয়ে কথা বলেছ আর আমি তাকে শান্তি দেব, সে বলবে না যেতে, কিন্তু আগুন। আঘাতটা পছন্দ করবে না, তুমি ওর থেকে বোকা কিছু বিক্রি করবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏دَخَلَ عَلَى ‏ ‏أَبِي سَعِيدٍ ‏ ‏وَأَنَا مَعَهُ فَقَالَ إِنَّ هَذَا حَدَّثَنِي حَدِيثًا يَزْعُمُ أَنَّكَ تُحَدِّثُهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَسَمِعْتَهُ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَبِيعُوا الذَّهَبَ بِالذَّهَبِ وَلَا ‏ ‏الْوَرِقَ ‏ ‏بِالْوَرِقِ ‏ ‏إِلَّا مِثْلًا بِمِثْلٍ وَلَا ‏ ‏تُشِفُّوا ‏ ‏بَعْضَهَا عَلَى بَعْضٍ وَلَا تَبِيعُوا شَيْئًا ‏ ‏غَائِبًا ‏ ‏مِنْهَا ‏ ‏بِنَاجِزٍ ‏","","",""],[11157,11157,"","আমরা আমাদের বাবার সেরাদের ব্যাপারে কথা বলেছি, ছেলে হতে পেরে খুশি, তাকে আত্মসমর্পণ করতে হবে, আর মানুষটিকে আগুনে যেতে হবে এবং হয়তো বাঘের সাথে আমাদের কথা বলতে হবে। কিন্তু, তারা তাদের ভাইদের সঙ্গে বাইবেল অধ্যয়ন করতে রাজি হন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ وَالْجُلُوسَ عَلَى الطَّرِيقِ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏مَعْمَرٌ ‏ ‏عَلَى ‏ ‏الصُّعُدَاتِ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ لَا بُدَّ لَنَا مِنْ مَجَالِسِنَا قَالَ فَأَدُّوا حَقَّهَا قَالُوا وَمَا حَقُّهَا قَالَ رُدُّوا السَّلَامَ وَغُضُّوا الْبَصَرَ وَأَرْشِدُوا السَّائِلَ وَأْمُرُوا بِالْمَعْرُوفِ وَانْهَوْا عَنْ الْمُنْكَرِ ‏","","",""],[11158,11158,"","আমার বাবার বিষয়ে আমার এক উত্তম ছেলেকে কীভাবে বলা হয়েছিল, সেই বিষয়ে আমরা কথা বলেছিলাম । আমাদের ঋণ হল, একে অন্যের চোখে আপনাকে দেখতে দেওয়া এক মিষ্টি ও রোমাঞ্চকর বিষয় । ( হিতোপদেশ ২: ৩) বোকারা গতিকে বাড়িয়ে দেবে এবং তারা দ্রুত গতি লাভ করবে । বোকারা আস্তে আস্তে বলে যে গাধাটা খুব বেশি কিছু করে ফেলে, যদি আমি শুধু তোমাকে খুজে পাই তুমি বলবে যে একজন মানুষ খুব ভালো, সে প্রতারিত হবে। দরিদ্র ও খারাপ, দরিদ্রের চাহিদা, তারপর বলেন যে মানুষ ভালোর দাবি পূরণ করতে ব্যর্থ হয়েছে এবং নিরাপদ জীবন যাপন করতে এবং মানুষ দীর্ঘ সময় বেঁচে থাকার জন্য জন্ম নিয়েছে। যে ব্যক্তি অনেক প্রাণ দেয় এবং মারা যায় সে এতই বিশাল এবং তারপর সে নিজের অনুষ্ঠানে বলে, আর আমি যা করি তার চেয়ে ভালো কিছু আমি তোমাকে বাঁচাতে পারবো না। আর তুমি তোমার মাকে ভালো মনে রাখবে আর আমি তাকে ঈশ্বরের কথা মনে রাখবো আর তার কথা মনে আছে। আর তারপর সেটা চলতে লাগল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْعَصْرِ ذَاتَ يَوْمٍ بِنَهَارٍ ثُمَّ قَامَ يَخْطُبُنَا إِلَى أَنْ غَابَتْ الشَّمْسُ فَلَمْ يَدَعْ شَيْئًا مِمَّا يَكُونُ إِلَى يَوْمِ الْقِيَامَةِ إِلَّا حَدَّثَنَاهُ حَفِظَ ذَلِكَ مَنْ حَفِظَ وَنَسِيَ ذَلِكَ مَنْ نَسِيَ وَكَانَ فِيمَا قَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّ الدُّنْيَا خَضِرَةٌ حُلْوَةٌ وَإِنَّ اللَّهَ مُسْتَخْلِفُكُمْ فِيهَا فَنَاظِرٌ كَيْفَ تَعْمَلُونَ فَاتَّقُوا الدُّنْيَا وَاتَّقُوا النِّسَاءَ أَلَا إِنَّ لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءً ‏ ‏يَوْمَ الْقِيَامَةِ بِقَدْرِ ‏ ‏غَدْرَتِهِ ‏ ‏يُنْصَبُ عِنْدَ ‏ ‏اسْتِهِ ‏ ‏يُجْزَى بِهِ وَلَا ‏ ‏غَادِرَ ‏ ‏أَعْظَمُ مِنْ أَمِيرِ عَامَّةٍ ثُمَّ ذَكَرَ الْأَخْلَاقَ فَقَالَ يَكُونُ الرَّجُلُ سَرِيعَ الْغَضَبِ قَرِيبَ ‏ ‏الْفَيْئَةِ ‏ ‏فَهَذِهِ بِهَذِهِ وَيَكُونُ بَطِيءَ الْغَضَبِ بَطِيءَ ‏ ‏الْفَيْئَةِ ‏ ‏فَهَذِهِ بِهَذِهِ فَخَيْرُهُمْ بَطِيءُ الْغَضَبِ سَرِيعُ ‏ ‏الْفَيْئَةِ ‏ ‏وَشَرُّهُمْ سَرِيعُ الْغَضَبِ بَطِيءُ ‏ ‏الْفَيْئَةِ ‏ ‏قَالَ وَإِنَّ الْغَضَبَ جَمْرَةٌ فِي قَلْبِ ابْنِ ‏ ‏آدَمَ ‏ ‏تَتَوَقَّدُ أَلَمْ تَرَوْا إِلَى حُمْرَةِ عَيْنَيْهِ وَانْتِفَاخِ ‏ ‏أَوْدَاجِهِ ‏ ‏فَإِذَا وَجَدَ أَحَدُكُمْ ذَلِكَ فَلْيَجْلِسْ ‏ ‏أَوْ قَالَ فَلْيَلْصَقْ بِالْأَرْضِ ‏ ‏قَالَ ثُمَّ ذَكَرَ الْمُطَالَبَةَ فَقَالَ يَكُونُ الرَّجُلُ حَسَنَ الطَّلَبِ سَيِّئَ ‏ ‏الْقَضَاءِ ‏ ‏فَهَذِهِ بِهَذِهِ وَيَكُونُ حَسَنَ ‏ ‏الْقَضَاءِ ‏ ‏سَيِّئَ الطَّلَبِ فَهَذِهِ بِهَذِهِ فَخَيْرُهُمْ الْحَسَنُ الطَّلَبِ الْحَسَنُ ‏ ‏الْقَضَاءِ ‏ ‏وَشَرُّهُمْ السَّيِّئُ الطَّلَبِ السَّيِّئُ ‏ ‏الْقَضَاءِ ‏ ‏ثُمَّ قَالَ إِنَّ النَّاسَ خُلِقُوا عَلَى طَبَقَاتٍ فَيُولَدُ الرَّجُلُ مُؤْمِنًا وَيَعِيشُ مُؤْمِنًا وَيَمُوتُ مُؤْمِنًا وَيُولَدُ الرَّجُلُ كَافِرًا وَيَعِيشُ كَافِرًا وَيَمُوتُ كَافِرًا وَيُولَدُ الرَّجُلُ مُؤْمِنًا وَيَعِيشُ مُؤْمِنًا وَيَمُوتُ كَافِرًا وَيُولَدُ الرَّجُلُ كَافِرًا وَيَعِيشُ كَافِرًا وَيَمُوتُ مُؤْمِنًا ثُمَّ قَالَ فِي حَدِيثِهِ وَمَا شَيْءٌ أَفْضَلَ مِنْ كَلِمَةِ عَدْلٍ تُقَالُ عِنْدَ سُلْطَانٍ ‏ ‏جَائِرٍ ‏ ‏فَلَا يَمْنَعَنَّ أَحَدَكُمْ اتِّقَاءُ النَّاسِ أَنْ يَتَكَلَّمَ بِالْحَقِّ إِذَا رَآهُ أَوْ شَهِدَهُ ثُمَّ بَكَى ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَقَالَ قَدْ وَاللَّهِ مَنَعَنَا ذَلِكَ قَالَ وَإِنَّكُمْ تُتِمُّونَ سَبْعِينَ أُمَّةً أَنْتُمْ خَيْرُهَا وَأَكْرَمُهَا عَلَى اللَّهِ ثُمَّ ‏ ‏دَنَتْ ‏ ‏الشَّمْسُ أَنْ تَغْرُبَ فَقَالَ وَإِنَّ مَا بَقِيَ مِنْ الدُّنْيَا فِيمَا مَضَى مِنْهَا مِثْلُ مَا بَقِيَ مِنْ يَوْمِكُمْ هَذَا فِيمَا مَضَى مِنْهُ ‏","","",""],[11159,11159,"","আমরা বাবার মত করে কথা বলেছি যে সে আমার বাবাকে খুঁজে বের করার চেষ্টা করছে. সে খুব সতর্ক ছিল তাকে বলতে যে সে তার নিজের জন্য ঈশ্বরের কাছে যাবে আর সে হাল ছেড়ে দেবে তার হাত, তুমি আকাশের কুবিকে দেখেছ, তার বাবা একবার তাদের জন্য কাজ করেছিল আর আমি তাকে খুন করবো। সে শ্বাসরুদ্ধকর প্যারেড দিয়ে এবং আমি নিশ্চিত সে আমার ক্লান্ত। ভাই, সে শুনেছি, ভাববাদী তার কাছে প্রার্থনা করেছে, আর সে এটা বলবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَالِدًا ‏ ‏يَقُولُ أَشْهَدُ عَلَى ‏ ‏أَبِي الْوَدَّاكِ ‏ ‏أَنَّهُ شَهِدَ عَلَى ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ سَمِعَهُ يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَهْلَ الْجَنَّةِ لَيَرَوْنَ أَهْلَ ‏ ‏عِلِّيِّينَ ‏ ‏كَمَا تَرَوْنَ الْكَوْكَبَ ‏ ‏الدُّرِّيَّ ‏ ‏فِي ‏ ‏أُفُقِ ‏ ‏السَّمَاءِ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏لَمِنْهُمْ وَأَنْعَمَا ‏ ‏فَقَالَ ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏وَهُوَ جَالِسٌ مَعَ ‏ ‏مُجَالِدٍ ‏ ‏عَلَى ‏ ‏الطِّنْفِسَةِ ‏ ‏وَأَنَا ‏ ‏أَشْهَدُ عَلَى ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏أَنَّهُ شَهِدَ عَلَى ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ذَلِكَ ‏","","",""],[11160,11160,"","আমি আমার বাবার সাথে কথা বলেছি, কিন্তু আমার বাবা আমাকে আদেশ করেছেন, ঈশ্বর তাকে প্রভুর অন্ত্যেষ্টিক্রিয়ার জন্য প্রার্থনা করতে বলেছেন। আমি নিশ্চিত নই সে শেষ পর্যন্ত চলে গেছে। তার হাড়ের চোখ আর তোমার ব্যর্থতা... ...যখন সে চলে যায়, সে সেটা অন্ত্যেষ্টিক্রিয়ায় ফেলে দেয়, যতক্ষণ না তুমি বন্ধ করো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَرْجُمَ ‏ ‏مَاعِزَ بْنَ مَالِكٍ ‏ ‏خَرَجْنَا بِهِ إِلَى ‏ ‏الْبَقِيعِ ‏ ‏فَوَاللَّهِ مَا حَفَرْنَا لَهُ وَلَا أَوْثَقْنَاهُ وَلَكِنَّهُ قَامَ لَنَا فَرَمَيْنَاهُ بِالْعِظَامِ ‏ ‏وَالْخَزَفِ ‏ ‏فَاشْتَكَى فَخَرَجَ يَشْتَدُّ حَتَّى انْتَصَبَ لَنَا فِي عُرْضِ ‏ ‏الْحَرَّةِ ‏ ‏فَرَمَيْنَاهُ ‏ ‏بِجَلَامِيدِ ‏ ‏الْجَنْدَلِ ‏ ‏حَتَّى سَكَتَ ‏","","",""],[11161,11161,"","আমরা ভালোবাসার কথা বলেছি আমার ভালোবাসার শোকের পর্দা দিয়ে, সে ঈশ্বরের কাছে প্রার্থনা করতে বলেছিল, আর আমি তোমার জন্য ভাল কিছু বয়ে আনবে।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏الْمُسْتَمِرُّ بْنُ الرَّيَّانِ الزَّهْرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَطْيَبُ الطِّيبِ الْمِسْكُ ‏","","",""],[11162,11162,"","ঈশ্বরের প্রেম নিয়ে আমরা একে অপরের সাথে কথা বলেছি। আমার বাবা তার বাবাকে জিজ্ঞেস করেছেন যে আমি ঈশ্বরের আদেশ শুনেছি এবং তার মঙ্গলভাবের কথা বলব। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং সেবা করবেন না। মৃত্যুর উদ্দেশ্য ভেঙ্গে গেছে, মানুষ কেমন আছে?","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيِّا بْنُ عَدِيٍّ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى الْمِنْبَرِ ‏ ‏مَا بَالُ أَقْوَامٍ تَقُولُ إِنَّ رَحِمَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَنْفَعُ يَوْمَ الْقِيَامَةِ وَاللَّهِ إِنَّ رَحِمِي لَمَوْصُولَةٌ فِي الدُّنْيَا وَالْآخِرَةِ وَإِنِّي أَيُّهَا النَّاسُ ‏ ‏فَرَطٌ ‏ ‏لَكُمْ عَلَى الْحَوْضِ ‏","","",""],[11163,11163,"","আমরা এমন একজন বাবার সঙ্গে কথা বলেছিলাম, যিনি তার প্রতি প্রেম দেখাতে চেয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سَهْمِ بْنِ مِنْجَابٍ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُسَافِرْ امْرَأَةٌ ثَلَاثًا إِلَّا مَعَ ذِي رَحِمٍ ‏","","",""],[11164,11164,"","আমরা ঈশ্বরের সাথে কথা বলেছিলাম যখন আমরা তোমাকে করতে চেষ্টা করলাম। তাই সে বলেছিল, আমি ঈশ্বরের নামে শপথ করে বলছি যে সে তাকে নিয়ে যেতে পেরে খুশি হবে। তার মুখে একটা অপরাধ পাওয়া গেছে, অন্য কোথাও।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏كَذَا قَالَ ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُسَافِرْ امْرَأَةٌ فَوْقَ يَوْمَيْنِ إِلَّا وَمَعَهَا زَوْجُهَا أَوْ ذُو مَحْرَمٍ مِنْهَا ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ وَأَحْسَبُنِي قَدْ سَمِعْتُهُ مِنْهُ فِي مَوَاضِعَ أُخَرَ ‏","","",""],[11165,11165,"","আমি ভালোবাসা কথা বলেছি আমার প্রভুর সাথে আমার বাবার সাহায্য করতে। ঈশ্বর তার কাছে প্রার্থনা করেন এবং তিনি বিজয়ী হওয়ার আগ পর্যন্ত হাল ছেড়ে দেন।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنِي ‏ ‏إِسْمَاعِيلُ بْنُ مُسْلِمٍ النَّاجِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَدَّدَ آيَةً حَتَّى أَصْبَحَ ‏","","",""],[11166,11166,"","তিনি বলেছিলেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেন এবং তিনি সবচেয়ে ভালো এবং সবচেয়ে ভালো ব্যক্তিকে দিয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي نُعْمٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَسَنُ ‏ ‏وَالْحُسَيْنُ ‏ ‏سَيِّدَا شَبَابِ أَهْلِ الْجَنَّةِ ‏","","",""],[11167,11167,"","আমার বাবার ভালবাসা সালাদের কথা বলেছিলাম, গেরিলারা বলেছে সে বাবাকে ঈশ্বরের সেবা করতে ভালোবাসে, আমার কাছে একটা শুরু আছে, তাই আমি এটা করতে যাচ্ছি। হয়তো ঈশ্বর তা করবেন না। সে তোমাকে ছেড়ে দিয়েছে, তারপর তুমি যা কিনেছ,","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ أَبِي سَلَّامٍ الْحَبَشِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَحْيَى بْنَ أَبِي كَثِيرٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَبْدِ الْغَافِرِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏جَاءَ ‏ ‏بِلَالٌ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِتَمْرٍ فَقَالَ مِنْ أَيْنَ لَكَ هَذَا فَقَالَ كَانَ عِنْدِي تَمْرٌ رَدِيءٌ فَبِعْتُهُ بِهَذَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَّهْ ‏ ‏عَيْنُ الرِّبَا عَيْنُ الرِّبَا فَلَا تَقْرَبَنَّهُ وَلَكِنْ بِعْ تَمْرَكَ بِمَا شِئْتَ ثُمَّ اشْتَرِ بِهِ مَا بَدَا لَكَ ‏","","",""],[11168,11168,"","আমি আমার বাবাকে বলেছিলাম যে, আমার বাবা একটা ভালবাসার জীবন খনন করে। ঈশ্বরের কাছে প্রার্থনা করে তার কাছে প্রার্থনা করে এবং আমার মনের মধ্যে ঔদ্ধত্য রেখে চলে যায়। এমনকি আমি একটি ভুল স্বপ্নের জন্ম দিতে চাই। যতক্ষণ না সে সাদা হয়ে যায় আর সে ভালো থাকে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏وَأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَا أَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏وَقَيْسُ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي ‏ ‏سَبْيِ ‏ ‏أَوْطَاسٍ ‏ ‏لَا ‏ ‏تُوطَأُ ‏ ‏حَامِلٌ ‏ ‏قَالَ ‏ ‏أَسْوَدُ ‏ ‏حَتَّى تَضَعَ ‏ ‏وَلَا غَيْرُ حَامِلٍ حَتَّى تَحِيضَ حَيْضَةً ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَوْ تَسْتَبْرِئَ بِحَيْضَةٍ ‏","","",""],[11169,11169,"","ঈশ্বরের পুত্রদের কথা বলেছিলাম আমার ভাইয়ের নাম নিয়ে খুশি হওয়ার জন্য, সে বলল ঈশ্বর তার জন্য প্রার্থনা করুক আর সে আমাকে গর্ভের মধ্যে দিয়ে যেতে দেয় নি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا وِصَالَ ‏ ‏يَعْنِي فِي الصَّوْمِ ‏","","",""],[11170,11170,"","আমরা বাবার সাথে কথা বলেছি আর একবার ডিনার করার সময় তোমাকে বাঁচানোর চেষ্টা করেছি। বল, আমরা করি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَمُعَاوِيَةُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ التَّمْرِ وَالزَّبِيبِ وَعَنْ ‏ ‏الزَّهْوِ ‏ ‏وَالتَّمْرِ ‏ ‏فَقُلْتُ ‏ ‏لِسُلَيْمَانَ ‏ ‏أَنْ ‏ ‏يُنْبَذَا ‏ ‏جَمِيعًا قَالَ نَعَمْ ‏","","",""],[11171,11171,"","আমি বলেছিলাম যে, ঈশ্বর আমাকে এই কথা বলতে বা কথা বলতে নিষেধ করবেন না । তার বাবা-মা'র সাথে কথা বলে রাগ করে তাকে খাও আর আমি তার সাথে কিছু করতে পারি নি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ عَامَّةُ طَعَامِ أَهْلِي ‏ ‏يَعْنِي الضِّبَابَ ‏ ‏فَلَمْ يُجِبْهُ فَلَمْ يُجَاوِزْ إِلَّا قَرِيبًا فَعَاوَدَهُ فَلَمْ يُجِبْهُ فَعَاوَدَهُ ثَلَاثًا فَقَالَ ‏ ‏إِنَّ اللَّهَ تَعَالَى لَعَنَ ‏ ‏أَوْ غَضِبَ عَلَى ‏ ‏سِبْطٍ ‏ ‏مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَمُسِخُوا ‏ ‏دَوَابَّ فَلَا أَدْرِي لَعَلَّهُ بَعْضُهَا فَلَسْتُ بِآكِلِهَا وَلَا أَنْهَى عَنْهَا ‏","","",""],[11172,11172,"","আমরা ক্যাম্পের বাপ্তিস্মের আগে রাজা একটি ছেলে আছে, তার ছেলে আছে সাহায্য করার জন্য এগিয়ে এসেছে। সে আমার বাবার সুখী ছেলে যে তাকে বলেছে যে একটা ছেলে আছে যে এটা করেছে। সে বলেছে, সে ঈশ্বরের বার্তাবাহকের কাছ থেকে বলেছে, সে তার জন্য প্রার্থনা করছে এবং সে তার জন্য প্রার্থনা করছে। পৌঁছে গেছি।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ الْخَيَّاطُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَمْرِو بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ قَوْمِهِ يُقَالُ لَهُ ‏ ‏فُلَانُ بْنُ مُعَاوِيَةَ ‏ ‏أَوْ ‏ ‏مُعَاوِيَةُ بْنُ فُلَانٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏الْمَيِّتُ يَعْرِفُ مَنْ يُغَسِّلُهُ ‏ ‏وَيَحْمِلُهُ ‏ ‏وَيُدَلِّيهِ قَالَ فَقُمْتُ مِنْ عِنْدِ ‏ ‏أَبِي سَعِيدٍ ‏ ‏إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏فَأَخْبَرْتُهُ فَمَرَّ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَقَالَ لَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏مِمَّنْ سَمِعْتَ هَذَا الْحَدِيثَ قَالَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11173,11173,"","আমরা বাবার ছেলেকে শুনতে চেষ্টা করেছি যখন আমরা হালকা আলো খুঁজে পাওয়ার চেষ্টা করেছি। আমার বাবা খুশি যে তার ছেলে ঈশ্বরের কাছে প্রার্থনা করেছে এবং সে মানুষটি দেখতে পায়নি। যে ব ্ যক ্ তি উপুড় হয়ে পড়েছে , সেই সফলকাম হয় । সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি, যিনি সম্ভবত সেই ব্যক্তি । গর্ভের মধ্যে মানুষটিকে পরাজিত না করে এবং মানুষ পরাজিত হবে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ بْنِ أَبِي فُدَيْكٍ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ يَعْنِي ابْنَ عُثْمَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْظُرْ الرَّجُلُ إِلَى عَوْرَةِ الرَّجُلِ وَلَا تَنْظُرْ الْمَرْأَةُ إِلَى عَوْرَةِ الْمَرْأَةِ وَلَا ‏ ‏يُفْضِ ‏ ‏الرَّجُلُ إِلَى الرَّجُلِ فِي الثَّوْبِ وَلَا ‏ ‏تُفْضِ ‏ ‏الْمَرْأَةُ إِلَى الْمَرْأَةِ فِي الثَّوْبِ ‏","","",""],[11174,11174,"","আমরা একটি ছেলেকে সাহায্য করার কথা বলেছিলাম। এই ঢালটি হচ্ছে, আমরা জয়-উইন ফ্যাশনে বিজয়ী হতে পেরে আনন্দিত। ঈশ্বর আমাদের সহায় হতে দিয়েছিলেন এবং আমরা ছিলাম যারা তা নিয়ে যেত বা নিয়ে যেতাম । আমরা আবার গাড়ি চালিয়ে গিয়েছিলাম এবং আমরা তোমাদের বলেছিলাম যে ঈশ্বর তোমাদের কাছে সমর্পণ করেছেন, তিনি যা কিছু করেছেন, আমরা তার জন্য মৃত্যুদণ্ডের শাস্তি হিসেবে কাজ করতে চাইছিলো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ مُحَيْرِيزٍ الشَّامِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا صِرْمَةَ الْمَازِنِيَّ ‏ ‏وَأَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولَانِ ‏ ‏أَصَبْنَا ‏ ‏سَبَايَا ‏ ‏فِي غَزْوَةِ ‏ ‏بَنِي الْمُصْطَلِقِ ‏ ‏وَهِيَ الْغَزْوَةُ الَّتِي أَصَابَ فِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جُوَيْرِيَةَ ‏ ‏وَكَانَ مِنَّا مَنْ يُرِيدُ أَنْ يَتَّخِذَ أَهْلًا وَمِنَّا مَنْ يُرِيدُ أَنْ يَسْتَمْتِعَ وَيَبِيعَ فَتَرَاجَعْنَا فِي ‏ ‏الْعَزْلِ ‏ ‏فَذَكَرْنَا ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا عَلَيْكُمْ أَنْ لَا ‏ ‏تَعْزِلُوا ‏ ‏فَإِنَّ اللَّهَ قَدَّرَ مَا هُوَ خَالِقٌ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[11175,11175,"","আমি আমার বাবাকে মদ খেতে সাহায্য করার চেষ্টা করেছিলাম । সম্ভবত ঋণের আগে তারা চলে যাওয়ার অনুমতি পেয়েছিল, আমি তার শহরের মোটেল খুঁজছি, ঋণের মধ্যে ছিল।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْلُصُ الْمُؤْمِنُونَ مِنْ النَّارِ يَوْمَ الْقِيَامَةِ فَيُحْتَبَسُونَ عَلَى قَنْطَرَةٍ بَيْنَ الْجَنَّةِ وَالنَّارِ فَيُقْتَصُّ لِبَعْضِهِمْ مِنْ بَعْضٍ مَظَالِمُ كَانَتْ بَيْنَهُمْ فِي الدُّنْيَا حَتَّى إِذَا هُذِّبُوا وَنُقُّوا أُذِنَ لَهُمْ فِي دُخُولِ الْجَنَّةِ فَوَالَّذِي نَفْسِي بِيَدِهِ لَأَحَدُهُمْ أَهْدَى لِمَنْزِلِهِ فِي الْجَنَّةِ مِنْهُ بِمَنْزِلِهِ كَانَ فِي الدُّنْيَا ‏","","",""],[11176,11176,"","আমরা গোপন একটা রহস্য পেয়েছি যে শিকারী আমাদের সাথে কথা বলেছে... ...যে আমাদের সাথে পৃথিবীর কথা বলেছে. আমি দেখতে চাই যে আমাদের কেউ এর থেকে খারাপ কিছু পড়তে পারবে না। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করবেন। ঈশ্বরের বই পড়া আমাদের কাছে এবং ঈশ্বর যা বলেছেন তা হল, ঈশ্বরের নিজস্ব আদেশ এবং আত্মসমর্পণ করা। তাদের মধ্যে একজন, আপনাদের জগত অর্ধেক বছর গান গাওয়ার আগে অপরাধতে প্রবেশ করছে।","‏ ‏حَدَّثَنَا ‏ ‏سَيَّارٌ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ بَشِيرٍ الْمُزَنِيُّ ‏ ‏وَكَانَ وَاللَّهِ مَا عَلِمْتُ شُجَاعًا عِنْدَ اللِّقَاءِ بَكَّاءً عِنْدَ الذِّكْرِ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي حَلْقَةٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِنَّ بَعْضَنَا لَيَسْتَتِرُ بِبَعْضٍ مِنْ الْعُرْيِ وَقَارِئٌ لَنَا يَقْرَأُ عَلَيْنَا فَنَحْنُ نَسْمَعُ إِلَى كِتَابِ اللَّهِ إِذْ وَقَفَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَعَدَ فِينَا لِيَعُدَّ نَفْسَهُ مَعَهُمْ فَكَفَّ الْقَارِئُ فَقَالَ مَا كُنْتُمْ تَقُولُونَ فَقُلْنَا يَا رَسُولَ اللَّهِ كَانَ قَارِئٌ لَنَا يَقْرَأُ عَلَيْنَا كِتَابَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ وَحَلَّقَ بِهَا ‏ ‏يُومِئُ ‏ ‏إِلَيْهِمْ أَنْ تَحَلَّقُوا فَاسْتَدَارَتْ الْحَلْقَةُ فَمَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَرَفَ مِنْهُمْ أَحَدًا غَيْرِي قَالَ فَقَالَ ‏ ‏أَبْشِرُوا يَا مَعْشَرَ الصَّعَالِيكِ تَدْخُلُونَ الْجَنَّةَ قَبْلَ الْأَغْنِيَاءِ بِنِصْفِ يَوْمٍ وَذَلِكَ خَمْسُ مِائَةِ عَامٍ ‏","","",""],[11177,11177,"","আমরা আমাদের বাবা কিভাবে বলেছিলেন যে আপনার টাকা আমার হাতের উপর হিংসাত্মক ছিল, ঈশ্বর তাকে দাবি করেছেন এবং তিনি আমার মায়ের কাছে আত্মসমর্পণ করেছেন যে তিনি এক বছর সেবা করতে পারবেন না যে - লোকেরা জেলে যাবে, তাদের জন্য তাকে চুমু দেওয়া হবে ।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الرَّجُلَ مِنْ أُمَّتِي ‏ ‏لَيَشْفَعُ ‏ ‏لِلْفِئَامِ ‏ ‏مِنْ النَّاسِ فَيَدْخُلُونَ الْجَنَّةَ ‏ ‏بِشَفَاعَتِهِ ‏ ‏وَإِنَّ الرَّجُلَ ‏ ‏لَيَشْفَعُ ‏ ‏لِلْقَبِيلَةِ مِنْ النَّاسِ فَيَدْخُلُونَ الْجَنَّةَ ‏ ‏بِشَفَاعَتِهِ ‏ ‏وَإِنَّ الرَّجُلَ ‏ ‏لَيَشْفَعُ ‏ ‏لِلرَّجُلِ وَأَهْلِ بَيْتِهِ فَيَدْخُلُونَ الْجَنَّةَ ‏ ‏بِشَفَاعَتِهِ ‏","","",""],[11178,11178,"","আমরা একজন সুখী দাসের কথা বলেছি, যিনি আমাদের চলে যেতে বলেছিলেন আর আমরা বলেছিলাম যে আমরা বাপ্তিস্ম নিতে যাচ্ছি। আমি আমার বাবার একজন সৎ মা হয়ে আছি। আমি আল্লাহ্‌র কাছে প্রার্থনা করতে পেরে খুশি, আর আমি বলবো, আমি তাকে রক্ষা করার উদ্দেশ্যে তোমার শেষ করে দেবো, তারা আল্লাহ্‌কে ছেড়ে দিবে। এক ঘন্টা পর চলে এসেছে আর কিছু ড্রিংক আর পানীয় পান করার জন্য শেষ পর্যন্ত, গরু তার সাথে দেখা করার ব্যাপারে, তুমি বলবে না হাইজ্যাকড।","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنَا ‏ ‏فُلَيْحٌ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَ ثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏مَرَّ بِي ‏ ‏ابْنُ عُمَرَ ‏ ‏فَقُلْتُ مِنْ أَيْنَ أَصْبَحْتَ غَادِيًا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ إِلَى ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏فَانْطَلَقْتُ مَعَهُ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنِّي نَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ وَادِّخَارِهِ بَعْدَ ثَلَاثَةِ أَيَّامٍ فَكُلُوا وَادَّخِرُوا فَقَدْ جَاءَ اللَّهُ بِالسَّعَةِ وَنَهَيْتُكُمْ عَنْ أَشْيَاءَ مِنْ الْأَشْرِبَةِ ‏ ‏وَالْأَنْبِذَةِ ‏ ‏فَاشْرَبُوا وَكُلُّ مُسْكِرٍ حَرَامٌ وَنَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ فَإِنْ زُرْتُمُوهَا فَلَا تَقُولُوا هُجْرًا ‏","","",""],[11179,11179,"","আমরা শপথ নিয়ে কথা বলেছি এবং আমাদের ভালোবাসায় আমাদের সুরক্ষা করা হবে আমার ছেলে বলেছে যে সে বিষাক্ত ছিল। খুশি যে আমাকে বলতে গেলে আল্লাহ তার কাছে প্রার্থনা করেছেন। আমি তার নিজের একটা জিততে চাই।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا ثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏السَّمَّانُ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏إِلَى شَيْءٍ يَسْتُرُهُ مِنْ النَّاسِ ‏ ‏فَأَرَادَ أَحَدٌ أَنْ يَجْتَازَ بَيْنَ يَدَيْهِ فَلْيَدْفَعْ فِي نَحْرِهِ فَإِنْ أَبَى فَلْيُقَاتِلْهُ فَإِنَّمَا هُوَ شَيْطَانٌ ‏","","",""],[11180,11180,"","আমরা কথা বলেছি, আমার বাবা কীভাবে লর্ডের সাথে খুশি ছিলেন, সে বলল আমি যদি তাদের বিচারককে তার সেবা করার জন্য যাই তাহলে অবাক হবেন না।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَسُبُّوا أَصْحَابِي فَلَوْ أَنَّ أَحَدَكُمْ أَنْفَقَ ‏ ‏مِثْلَ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا مَا بَلَغَ ‏ ‏مُدَّ ‏ ‏أَحَدِهِمْ وَلَا نَصِيفَهُ ‏","","",""],[11181,11181,"","আমরা কিভাবে সুখী হয়েছিলাম এবং তারপর তিনি ঈশ্বরের কাছে প্রার্থনা করলেন তিনি তাকে যেতে দেবেন না। মসজিদ হচ্ছে যুদ্ধ এবং সংক্ষিপ্ত ছোট ছোট ছোট এবং আমার গৌরব। এটা.","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏حَدَّثَنِي ‏ ‏شَهْرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏وَذُكِرَتْ عِنْدَهُ صَلَاةٌ فِي ‏ ‏الطُّورِ ‏ ‏فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْبَغِي ‏ ‏لِلْمَطِيِّ ‏ ‏أَنْ تُشَدَّ ‏ ‏رِحَالُهُ ‏ ‏إِلَى مَسْجِدٍ يُبْتَغَى فِيهِ الصَّلَاةُ غَيْرَ ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏وَالْمَسْجِدِ الْأَقْصَى ‏ ‏وَمَسْجِدِي ‏ ‏هَذَا ‏","","",""],[11182,11182,"","আর কাউকে একটা চমক দিয়ে বের হতে না বলাটা ঠিক নয়।","‏ ‏وَلَا يَنْبَغِي لِامْرَأَةٍ دَخَلَتْ الْإِسْلَامَ أَنْ تَخْرُجَ مِنْ بَيْتِهَا مُسَافِرَةً إِلَّا مَعَ بَعْلٍ أَوْ مَعَ ذِي مَحْرَمٍ مِنْهَا ‏","","",""],[11183,11183,"","সূর্য ওঠার দুই ঘন্টার মধ্যে নামাজ পড়বে না।","‏ ‏وَلَا يَنْبَغِي الصَّلَاةُ فِي سَاعَتَيْنِ مِنْ النَّهَارِ مِنْ بَعْدِ صَلَاةِ الْفَجْرِ إِلَى أَنْ تَرْحَلَ الشَّمْسُ وَلَا بَعْدَ صَلَاةِ الْعَصْرِ إِلَى أَنْ تَغْرُبَ الشَّمْسُ ‏","","",""],[11184,11184,"","নীল রঙের রঙের রঙের মধ্যে গর্ভ বড় হবে না।","‏ ‏وَلَا يَنْبَغِي الصَّوْمُ فِي يَوْمَيْنِ مِنْ الدَّهْرِ يَوْمِ الْفِطْرِ مِنْ رَمَضَانَ وَيَوْمِ النَّحْرِ ‏","","",""],[11185,11185,"","আমরা এক অন্ধকার মধ্যে কথা বলেছি কিন্তু একটি ঘোড়ার কথা আমাদের নিজের এক সৌন্দর্যের জন্য চেষ্টা করেছি. আমি মনে করি এটা বলা ভাল যে ঈশ্বর আমাকে কথা বলেছেন যে আমার পিতা আমাকে বলেছেন. সে এমন একটা মই পাবে যেটা সে পাগলের যন্ত্রণায় করতে পেরেছে: সে একটা কুত্তীকে খাচ্ছিল যে বলে যে সে হয়তো একজন শিকারী যে আমার গলা কেটে ফেলেছে সম্মান।","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ شَرْفَيْ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَيْنَ قَبْرِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ ‏ ‏: ‏ ‏إِسْحَاقُ بْنُ شَرْفَيْ ‏ ‏حَدَّثَنَا عَنْهُ ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏إِسْحَاقُ بْنُ شَرْفَيْ ‏","","",""],[11186,11186,"","বাবা আমাকে সাহায্য করার চেষ্টা করছিল, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আমার মায়ের মৃত্যু হবে। আমরা আমার বাবার সাথে কথা বলেছি। দয়া করে আমাকে সাহায্য করার চেষ্টা করছি, ঈশ্বর তার মতো করে কথা বলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكُونُ فِي أُمَّتِي فِرْقَتَانِ يَخْرُجُ بَيْنَهُمَا ‏ ‏مَارِقَةٌ ‏ ‏يَلِي قَتْلَهَا أَوْلَاهُمَا بِالْحَقِّ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[11187,11187,"","আমরা আমাদের সময় নিয়ে কথা বলেছি এবং এটা আমার বাবার ভালো কিছু খোঁজার ব্যাপারে, সে প্রার্থনা করেছে যে ঈশ্বর তাকে উদ্ধার করতে হবে এবং সে বলে কেউ বিশ্বাস করবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَسْوَدُ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا جَاءَ وَقَدْ صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَلَا رَجُلٌ يَتَصَدَّقُ عَلَى هَذَا فَيُصَلِّيَ مَعَهُ ‏","","",""],[11188,11188,"","আমরা এই বিদ্রুপাত্মক কাজে সাহায্য করে হাত রক্ষা করার চেষ্টা করেছি। লর্ড তার জন্য প্রার্থনা করেছে এবং আশ্বস্ত করেছে যে খারাপ লোকেরা সব সমস্যায় পড়বে। কিভাবে রানরের স্টক উপত্যকায় ফিরে যাবে, তারপর তীর ফিরে না আসা পর্যন্ত তারা ফিরে আসবে না। তারা ডাকিনী বলে ডাক দেয়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سِيرِينَ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَخْرُجُ أُنَاسٌ مِنْ قِبَلِ الْمَشْرِقِ يَقْرَءُونَ الْقُرْآنَ ‏ ‏لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏ثُمَّ لَا يَعُودُونَ فِيهِ حَتَّى يَعُودَ السَّهْمُ عَلَى ‏ ‏فُوقِهِ ‏ ‏قِيلَ مَا ‏ ‏سِيمَاهُمْ ‏ ‏قَالَ ‏ ‏سِيمَاهُمْ ‏ ‏التَّحْلِيقُ وَالتَّسْبِيتُ ‏","","",""],[11189,11189,"","আমি বাবার কথা বলেছিলাম আমার বাবার অতীতকে সাহায্য করার কথা। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং অতিথিকে তিনদিনের পর আপনি চুপ করে আছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَسَعِيدٌ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ فَمَا كَانَ بَعْدَ ذَلِكَ فَهُوَ ‏ ‏صَدَقَةٌ ‏","","",""],[11190,11190,"","আমরা আমার ভাইকে খুশি করার চেষ্টা নিয়ে কথা বলেছি, ঈশ্বর আছে আর সে সব গেরিলাকে তার জীবন বাঁচিয়ে রাখার জন্য বলবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خُلَيْدِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ عِنْدَ ‏ ‏اسْتِهِ ‏","","",""],[11191,11191,"","আমরা দ্বিতীয় বারের মতো আমার বাবার সঙ্গে কথা বলেছিলাম, যিনি আমাকে সাহায্য করার চেষ্টা করছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ ثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيُحَجَّنَّ ‏ ‏الْبَيْتُ ‏ ‏وَلَيُعْتَمَرَنَّ بَعْدَ خُرُوجِ ‏ ‏يَأْجُوجَ ‏ ‏وَمَأْجُوجَ ‏","","",""],[11192,11192,"","আমরা পরবর্তী বার ঈশ্বরের কাজ করেছি, যখন আমরা বাবার ছেলের চেয়ে ভালো কাজ করেছি। সবচেয়ে ভালো হবে, লর্ডের সেরা প্রভু হতে হবে। দুই বছর বয়স পার হয়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ ثَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي نُعْمٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَسَنُ ‏ ‏وَالْحُسَيْنُ ‏ ‏سَيِّدَا شَبَابِ أَهْلِ الْجَنَّةِ ‏ ‏وَفَاطِمَةُ ‏ ‏سَيِّدَةُ نِسَائِهِمْ إِلَّا مَا كَانَ ‏ ‏لِمَرْيَمَ بِنْتِ عِمْرَانَ ‏","","",""],[11193,11193,"","আমরা একটি কঠিন সময় কথা বলেছি যে আমরা আমার বাবার চেয়ে একটি ছেলেকে বেশী ভয় পাচ্ছি না, কৌশল হচ্ছে যে প্রভু তার কাছে প্রার্থনা করেছেন এবং বলতে বলেছেন, ঈশ্বর আমার আছে, তুমি তাকে একটা বিরতি দিচ্ছ আর নাবিককে কখনো কিছু করতে দেখেও না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ ثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ أَعْرَابِيًّا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي إِبِلًا وَإِنِّي أُرِيدُ الْهِجْرَةَ فَمَا تَأْمُرُنِي قَالَ هَلْ تَمْنَحُ مِنْهَا قَالَ نَعَمْ قَالَ وَتُؤَدِّي زَكَاتَهَا قَالَ نَعَمْ قَالَ وَتَحْلِبُهَا يَوْمَ وِرْدِهَا قَالَ نَعَمْ فَقَالَ ‏ ‏انْطَلِقْ وَاعْمَلْ وَرَاءَ الْبِحَارِ فَإِنَّ اللَّهَ لَنْ يَتِرَكَ مِنْ عَمَلِكَ شَيْئًا وَإِنَّ شَأْنَ الْهِجْرَةِ شَدِيدٌ ‏","","",""],[11194,11194,"","আমরা আমার বাবা আমাকে সাহায্য করার চেষ্টা করেছে বলে সে ঘন্টার পর ঘন্টা বিপদে পড়েছে। তারা বলবে যে দুই ছেলে আটকে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَكْثُرُ الصَّوَاعِقُ عِنْدَ اقْتِرَابِ السَّاعَةِ ‏ ‏حَتَّى يَأْتِيَ الرَّجُلُ الْقَوْمَ فَيَقُولَ مَنْ صَعِقَ تِلْكُمْ ‏ ‏الْغَدَاةَ ‏ ‏فَيَقُولُونَ صَعِقَ فُلَانٌ وَفُلَانٌ ‏","","",""],[11195,11195,"","আমি আমার ভাইকে ছেড়ে দিতে আমার বাবার সাথে যে ঝামেলার আলোচনা হয়েছিল, তার কথা বলেছিলাম। মাদকটি আমরা ঈশ্বরের কাছে প্রার্থনা করতাম যেন তিনি এটা করতে পারেন এবং তার বুকে তুলে ধরেন। আপনি তো জানেন। মারা যাওয়ার পর, তোমাকে ঈশ্বরের কাছে করা হবে... ...তুমি যা বদলেছ... ...তা হলে... ...তুমি বলেছিলে... ...তুমি তাকে প্রার্থনা করতে, আর তাকে এটা বলতে বলা হয়েছে যে... আমি কখনও ভগবানকে হত্যা করি, তাকে আমি হারিয়ে ফেলি, আমি বিশ্বাস করি তার প্রার্থনা তাকে হারাতে হবে। ডাক্তার বলেছে যে আমার বাবা খুশি, আমি নিশ্চিত তারা মারা যাবার সময় ধরা পরে মারা গেছে, খুন হয়ে গেছে। যে ধরনের কাজ তোমাকে করতে বলা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏وَالضَّحَّاكِ الْمِشْرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ يَقْسِمُ مَالًا إِذْ أَتَاهُ ‏ ‏ذُو الْخُوَيْصِرَةِ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏اعْدِلْ فَوَاللَّهِ مَا عَدَلْتَ مُنْذُ الْيَوْمَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ ‏ ‏لَا تَجِدُونَ بَعْدِي أَعْدَلَ عَلَيْكُمْ مِنِّي ثَلَاثَ مَرَّاتٍ فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ أَتَأْذَنُ لِي فَأَضْرِبَ عُنُقَهُ فَقَالَ لَا إِنَّ لَهُ أَصْحَابًا يَحْقِرُ أَحَدُكُمْ صَلَاتَهُ مَعَ صَلَاتِهِمْ وَصِيَامَهُ مَعَ صِيَامِهِمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏يَنْظُرُ صَاحِبُهُ إِلَى ‏ ‏فُوقِهِ ‏ ‏فَلَا يَرَى شَيْئًا آيَتُهُمْ رَجُلٌ إِحْدَى يَدَيْهِ كَالْبَضْعَةِ ‏ ‏أَوْ كَثَدْيِ الْمَرْأَةِ ‏ ‏يَخْرُجُونَ عَلَى فِرْقَتَيْنِ مِنْ النَّاسِ يَقْتُلُهُمْ أَوْلَى الطَّائِفَتَيْنِ بِاللَّهِ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَأَشْهَدُ أَنِّي سَمِعْتُ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنِّي شَهِدْتُ ‏ ‏عَلِيًّا ‏ ‏حِينَ قَتَلَهُمْ فَالْتَمَسَ فِي الْقَتْلَى فَوَجَدَ عَلَى ‏ ‏النَّعْتِ ‏ ‏الَّذِي ‏ ‏نَعَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11196,11196,"","আমরা আমাদের সময়ের অনুগ্রহে বাপ্তাইজিত হয়েছি, কিন্তু আমার পাপকে আরও ভাল করে বোঝাতে চাই। ঈশ্বরের অনুগ্রহের জন্য প্রার্থনা করে তার জন্য প্রার্থনা করে এবং তিনি পৃথিবীর সেরাটা দেবেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَبِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْحَسَنِ يَعْنِي ابْنَ عَطِيَّةَ الْعَوْفِيَّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّائِحَةَ وَالْمُسْتَمِعَةَ ‏","","",""],[11197,11197,"","আমরা একটি বাপ্তিস্মের কথা বলেছিলাম, যে কিনা আমাদের সাথে যুদ্ধের মাধ্যমে কথা বলেছে, সে আমাদের সাথে কথা বলেছে। আমরা ঈশ্বরের বার্তাবাহকের সাথে গিয়েছিলাম, সে প্রার্থনা করেছিল তোমার ক্ষতি উদ্ধার করতে, সে বলল, \"ঈশ্বর আছে।\" \"কিছু কথায়, তাঁদের কাছে রসুন আছে আর খুনিদের আগমনের পর ঈশ্বর এটা দিয়েছেন। তিনি বলেছেন, এটা খাওয়া থেকে না খেতে, তিনি আমাদের খুব কাছের। আর আমাদের কাছের।\" আমরা গুলি করতে পারি আর ভবিষ্যদ্বাণী করতে পারব যে তাকে উদ্ধার করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ حَرْبٍ ‏ ‏سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يُحَدِّثُ قَالَ ‏ ‏غَزَوْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَكَ ‏ ‏وَخَيْبَرَ ‏ ‏قَالَ فَفَتَحَ اللَّهُ عَلَى رَسُولِهِ ‏ ‏فَدَكَ ‏ ‏وَخَيْبَرَ ‏ ‏فَوَقَعَ النَّاسُ فِي بَقْلَةٍ لَهُمْ هَذَا الثُّومُ وَالْبَصَلُ قَالَ فَرَاحُوا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدَ رِيحَهَا فَتَأَذَّى بِهِ ثُمَّ عَادَ الْقَوْمُ فَقَالَ ‏ ‏أَلَا لَا تَأْكُلُوهُ فَمَنْ أَكَلَ مِنْهَا شَيْئًا فَلَا يَقْرَبَنَّ مَجْلِسَنَا قَالَ وَوَقَعَ النَّاسُ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏فِي لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ وَنَصَبُوا الْقُدُورَ وَنَصَبْتُ قِدْرِي فِيمَنْ نَصَبَ فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَنْهَاكُمْ عَنْهُ ‏ ‏أَنْهَاكُمْ عَنْهُ مَرَّتَيْنِ ‏ ‏فَأُكْفِئَتْ ‏ ‏الْقُدُورُ ‏ ‏فَكَفَأْتُ ‏ ‏قِدْرِي فِيمَنْ ‏ ‏كَفَأَ ‏","","",""],[11198,11198,"","আমরা আমার বাবাকে সাহায্য করার কথা বলেছিলাম, আমরা ঈশ্বরের কাছে প্রার্থনা করতাম আর তিনি এক ঘন্টার মধ্যে স্বর্গে থাকেন। যদি আমি তাকে বলি আমি তাকে বলি আমি একজন দেবতা। আমি তাকে এই সময় তাকে একটা শিক্ষককে জিজ্ঞেস করবো যে তাকে খুঁজে পাবে। সে চলে যাওয়ার আগে তার ক্ষমতা আছে, সে এটা আদেশ করেছে যদি সে নিজের মুখ উড়িয়ে দেয়, এমন একটা বেড়া যা তার মুখে থুতু দিতে পারে না অথবা তাকে বলে দেয় তারপর মুখ থেকে বেরিয়ে এসে সে শেষ রাতের প্রার্থনায় লর্ডকে মারার জন্য দেয়া হয়, কিন্তু সে কখনো না, ঈশ্বর তার প্রার্থনা দেখতে চাই যদি আমি তাকে বলি যে সে আমাকে দেখে আমি তাকে হারিয়ে না পারা পর্যন্ত ধরা পড়ে। এটা নিয়ে তোমার মা তোমাকে ১০ টা আলো দেবে এবং তোমাকে ঘরে ছেড়ে দিবে এবং গর্ভের মধ্যে হারিয়ে যাবে। সে বলেছে, \"আমিও তোমাকে ভালবাসি\" সমাজে, আপনার কি কোন জ্ঞান আছে যে আমি ঈশ্বরের কাছে প্রার্থনা করব এবং এটা জিজ্ঞাসা করব? আমি তাকে ভুলে গেছি যে আমি কি করে এর থেকে বের হয়ে যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يُحَدِّثُنَا ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ فِي الْجُمُعَةِ سَاعَةً لَا ‏ ‏يُوَافِقُهَا ‏ ‏مُسْلِمٌ وَهُوَ فِي صَلَاةٍ يَسْأَلُ اللَّهَ خَيْرًا إِلَّا آتَاهُ إِيَّاهُ قَالَ وَقَلَّلَهَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏بِيَدِهِ قَالَ فَلَمَّا تُوُفِّيَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قُلْتُ وَاللَّهِ لَوْ جِئْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏فَسَأَلْتُهُ عَنْ هَذِهِ السَّاعَةِ أَنْ يَكُونَ عِنْدَهُ مِنْهَا عِلْمٌ فَأَتَيْتُهُ فَأَجِدُهُ يُقَوِّمُ ‏ ‏عَرَاجِينَ ‏ ‏فَقُلْتُ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏مَا هَذِهِ ‏ ‏الْعَرَاجِينُ ‏ ‏الَّتِي أَرَاكَ تُقَوِّمُ قَالَ هَذِهِ ‏ ‏عَرَاجِينُ ‏ ‏جَعَلَ اللَّهُ لَنَا فِيهَا بَرَكَةً كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّهَا وَيَتَخَصَّرُ بِهَا فَكُنَّا نُقَوِّمُهَا ‏ ‏وَنَأْتِيهِ بِهَا فَرَأَى بُصَاقًا فِي قِبْلَةِ الْمَسْجِدِ وَفِي يَدِهِ ‏ ‏عُرْجُونٌ ‏ ‏مِنْ تِلْكَ ‏ ‏الْعَرَاجِينِ ‏ ‏فَحَكَّهُ وَقَالَ إِذَا كَانَ أَحَدُكُمْ فِي صَلَاتِهِ فَلَا يَبْصُقْ أَمَامَهُ فَإِنَّ رَبَّهُ أَمَامَهُ وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ فَإِنْ لَمْ ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏لَمْ يَجِدْ ‏ ‏مَبْصَقًا ‏ ‏فَفِي ثَوْبِهِ أَوْ نَعْلِهِ قَالَ ثُمَّ هَاجَتْ السَّمَاءُ مِنْ تِلْكَ اللَّيْلَةِ فَلَمَّا خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِصَلَاةِ الْعِشَاءِ الْآخِرَةِ بَرَقَتْ بَرْقَةٌ فَرَأَى ‏ ‏قَتَادَةَ بْنَ النُّعْمَانِ ‏ ‏فَقَالَ مَا ‏ ‏السُّرَى ‏ ‏يَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ عَلِمْتُ يَا رَسُولَ اللَّهِ أَنَّ شَاهِدَ الصَّلَاةِ قَلِيلٌ فَأَحْبَبْتُ أَنْ أَشْهَدَهَا قَالَ فَإِذَا صَلَّيْتَ فَاثْبُتْ حَتَّى أَمُرَّ بِكَ فَلَمَّا انْصَرَفَ أَعْطَاهُ ‏ ‏الْعُرْجُونَ ‏ ‏وَقَالَ خُذْ هَذَا فَسَيُضِيءُ أَمَامَكَ عَشْرًا وَخَلْفَكَ عَشْرًا فَإِذَا دَخَلْتَ الْبَيْتَ وَتَرَاءَيْتَ سَوَادًا فِي زَاوِيَةِ الْبَيْتِ فَاضْرِبْهُ قَبْلَ أَنْ يَتَكَلَّمَ فَإِنَّهُ شَيْطَانٌ قَالَ فَفَعَلَ فَنَحْنُ نُحِبُّ هَذِهِ ‏ ‏الْعَرَاجِينَ ‏ ‏لِذَلِكَ قَالَ قُلْتُ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏إِنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدَّثَنَا عَنْ السَّاعَةِ الَّتِي فِي الْجُمُعَةِ فَهَلْ عِنْدَكَ مِنْهَا عِلْمٌ فَقَالَ سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهَا فَقَالَ إِنِّي كُنْتُ قَدْ أُعْلِمْتُهَا ثُمَّ أُنْسِيتُهَا كَمَا أُنْسِيتُ لَيْلَةَ الْقَدْرِ ‏ ‏قَالَ ‏ ‏ثُمَّ خَرَجْتُ مِنْ عِنْدِهِ فَدَخَلْتُ عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏","","",""],[11199,11199,"","আমি আমার বাবাকে সাহায্য করার চেষ্টা করেছি ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا بَكْرِ بْنَ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى كُلِّ ‏ ‏مُحْتَلِمٍ ‏ ‏الْغُسْلُ يَوْمَ ‏ ‏الْجُمُعَةِ وَيَلْبَسُ مِنْ صَالِحِ ثِيَابِهِ وَإِنْ كَانَ لَهُ طِيبٌ مَسَّ مِنْهُ ‏","","",""],[11200,11200,"","আমরা এক কিশোরের কথা বলেছিলাম, সে যদি বোতামের কাছে যাওয়ার জন্য সবচেয়ে ভালো হতো, তাহলে আমি তার কাছে প্রার্থনা করতাম আর বাবাকে বল আমি তাকে ধোঁকা দিতে সাহায্য করতে। সে আমাকে সাহায্য করতে চায় না। একজন মহিলাকে তার জন্য যেতে দাও।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ هِيَ بِنْتُ عَبْدِ الرَّحْمَنِ بْنِ سَعْدِ بْنِ زُرَارَةَ الْأَنْصَارِيَّةُ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُخْبِرَتْ أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يُفْتِي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَصْلُحُ لِلْمَرْأَةِ أَنْ تُسَافِرَ إِلَّا وَمَعَهَا ذُو مَحْرَمٍ لَهَا ‏","","",""]];
